// Акафісти (Київський ізвод, церковнослов'янські тексти українською транслітерацією) — https://xn--80ad6b1e.xn--j1amh/b/akafisty-cs-ukr
// Файл згенеровано scripts/build_akafisty.py. Абзац з префіксом § — рубрика (напис), з префіксом # — підзаголовок; ⁽n⁾ — примітка n зі списку notes.
import type { MvBook } from './molytvoslov';
export const AKAFISTY: MvBook[] = [{"u":"Акафіст Сладчайшому Господу нашому Ісусу Христу","e":"Akathist to our Sweetest Lord Jesus Christ","secs":[{"h":"Кондак 1","ps":["Возбра́нний Воєво́до і Го́споди, а́да побіди́телю, я́ко ізба́влься от ві́чния сме́рти, похва́льная воспису́ю Ті, созда́ніє і раб Твой; но, я́ко імі́яй милосе́рдіє неізрече́нноє, от вся́ких м'я бід свободи́, зову́ща:","Ісу́се, Си́не Бо́жий, поми́луй м'я."]},{"h":"Ікос 1","ps":["А́нгелов Тво́рче і Го́споди сил, отве́рзи мі недоумі́нний ум і язи́к на похвалу́ пречи́стаго Твоєго́ і́мене, я́коже глухо́му і гугни́вому дре́вле слух і язи́к отве́рзл єси́, і глаго́лаше зови́й такова́я:","Ісу́се пречу́дний, а́нгелов Удивле́ніє; Ісу́се преси́льний, прароди́телей Ізбавле́ніє.","Ісу́се пресла́дкий, патріа́рхов Велича́ніє; Ісу́се пресла́вний, царе́й Укріпле́ніє.","Ісу́се прелюби́мий, проро́ков Ісполне́ніє; Ісу́се преди́вний, му́чеников Крі́посте.","Ісу́се прети́хій, мона́хов Ра́досте; Ісу́се преми́лостивий, пресві́теров Сла́досте.","Ісу́се премилосе́рдий, по́стников Воздержа́ніє; Ісу́се пресла́достний, преподо́бних Ра́дованіє.","Ісу́се пречестни́й, ді́вственних Цілому́дріє; Ісу́се предві́чний, грі́шников Спасе́ніє.","Ісу́се, Си́не Бо́жий, поми́луй м'я."]},{"h":"Кондак 2","ps":["Ви́дя вдови́цю зі́льні⁽1⁾ пла́чущу, Го́споди, я́коже бо тогда́ умилосе́рдився, си́на єя́ на погребе́ніє несо́ма воскреси́л єси́; си́це і о мні умилосе́рдися, Человіколю́бче, і гріхми́ умерщвле́нную мою́ ду́шу воскреси́, зову́щую: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум неуразумі́нний разумі́ти Фили́пп іщя́: Го́споди, покажи́ нам Отця́, глаго́лаше. Ти же к нему́: толи́коє вре́м'я сий со Мно́ю, не позна́л ли єси́, я́ко Оте́ць во Мні, і Аз во Отці́ єсьм? Ті́мже, Неізслі́дованне, со стра́хом зову́ Ті:","Ісу́се, Бо́же предві́чний; Ісу́се, Царю́ преси́льний.","Ісу́се, Влади́ко долготерпіли́вий; Ісу́се, Спа́се преми́лостивий.","Ісу́се, Храни́телю мой преблаги́й; Ісу́се, очи́сти гріхи́ моя́.","Ісу́се, отими́ беззако́нія моя́; Ісу́се, отпусти́ непра́вди моя́.","Ісу́се, Наде́ждо моя́, не оста́ви мене́; Ісу́се Помо́щниче мой, не отри́ни мене́.","Ісу́се, Созда́телю мой, не забу́ди мене́; Ісу́се, Па́стирю мой, не погуби́ мене́.","Ісу́се, Си́не Бо́жий, поми́луй м'я."]},{"h":"Кондак 3","ps":["Си́лою сви́ше апо́столи облеки́й, Ісу́се, во Ієрусали́мі сідя́щия, облеци́ і мене́, обнаже́ннаго от вся́каго благотворе́нія, теплото́ю Ду́ха Свята́го Твоєго́, і даждь мі с любо́вію пі́ти Тебі́: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яй бога́тство милосе́рдія, митарі́ і грі́шники, і неві́рния призва́л єси́, Ісу́се: не пре́зри і мене́ ни́ні, подо́бнаго їм, но я́ко многоці́нноє ми́ро, прийми́ піснь сію́:","Ісу́се, Си́ло непобіди́мая; Ісу́се, Ми́лосте безконе́чная.","Ісу́се, Красото́ пресві́тлая; Ісу́се, люби́ неізрече́нная.","Ісу́се, Си́не Бо́га жива́го; Ісу́се, поми́луй м'я, грі́шнаго.","Ісу́се, усли́ши м'я, в беззако́ніїх зача́таго; Ісу́се, очи́сти м'я, во грісі́х рожде́ннаго.","Ісу́се, научи́ м'я, непотре́бнаго; Ісу́се, освіти́ м'я, те́мнаго.","Ісу́се, очи́сти м'я, скве́рнаго; Ісу́се, возведи́ м'я, блу́днаго.","Ісу́се, Си́не Бо́жий, поми́луй м'я."]},{"h":"Кондак 4","ps":["Бу́рю внутр імі́яй помишле́ній сумни́тельних, Петр утопа́ше; узрі́в же во пло́ті Тя су́ща, Ісу́се, і по вода́м ходя́ща, позна́ Тя Бо́га і́стиннаго, і ру́ку спасе́нія получи́в, рече́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша сліпи́й, Го́споди, мимоходя́ща Тя путе́м, вопія́ше: Ісу́се, Си́не Дави́дов, поми́луй м'я! і призва́в, отве́рзл єси́ о́чі єго́. Просвіти́ у́бо ми́лостію Твоє́ю о́чі ми́сленния се́рдця, і мене́, вопію́ща Ті і глаго́люща:","Ісу́се, ви́шніх Созда́телю; Ісу́се, ни́жніх Іскупи́телю.","Ісу́се, преіспо́дніх Потреби́телю; Ісу́се, всея́ тва́рі Украси́телю.","Ісу́се, душі́ моєя́ Уті́шителю; Ісу́се, ума́ моєго́ Просвіти́телю.","Ісу́се, се́рдця моєго́ Весе́ліє; Ісу́се, ті́ла моєго́ Здра́віє.","Ісу́се Спа́се мой, спаси́ м'я; Ісу́се, Сві́те мой, просвіти́ м'я.","Ісу́се, му́ки вся́кия ізба́ви м'я; Ісу́се, спаси́ м'я, недосто́йнаго.","Ісу́се, Си́не Бо́жий, поми́луй м'я."]},{"h":"Кондак 5","ps":["Богото́чною Кро́вію я́коже іскупи́л єси́ нас дре́вле от зако́нния кля́тви, Ісу́се, си́це ізми́ нас от сі́ті, є́юже змій зап'я́т ни страстьми́ плотськи́ми, і блу́дним наважде́нієм, і злим уни́нієм, вопію́щия Ті: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше о́троци євре́йстії во о́бразі челові́честім Созда́вшаго руко́ю челові́ка і Влади́ку разумі́вше Єго́, потща́шася ві́твми угоди́ти Єму́, оса́нна вопію́ще. Ми же піснь прино́сим Ті глаго́люще:","Ісу́се, Бо́же і́стинний; Ісу́се, Си́не Дави́дов.","Ісу́се, Царю́ пресла́вний; Ісу́се, А́гнче непоро́чний.","Ісу́се, Па́стирю преди́вний; Ісу́се, Храни́телю во мла́дості моє́й.","Ісу́се, Корми́телю во ю́ності моє́й; Ісу́се, Похвало́ в ста́рості моє́й.","Ісу́се, Наде́ждо в сме́рті моє́й; Ісу́се, Животе́ по сме́рті моє́й.","Ісу́се, Утіше́ніє моє́ на суді́ Твоє́м; Ісу́се, Жела́ніє моє́, не посрами́ мене́ тогда́.","Ісу́се Си́не Бо́жий, поми́луй м'я."]},{"h":"Кондак 6","ps":["Пропові́дник богоно́сних віща́ніє і глаго́ли ісполня́я, Ісу́се, на землі́ я́влься і с челові́ки, Невмісти́мий, пожи́л єси́ і болі́зні на́ша под'я́л єси́, отню́дуже ра́нами Твої́ми ми ісцілі́вше, пі́ти навико́хом: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ вселе́нній просвіще́ніє і́стини Твоєя́, і отгна́ся лесть бісо́вськая: і́доли бо, Спа́се наш, не терп'я́ще Твоєя́ крі́пости, падо́ша. Ми же, спасе́ніє получи́вше, вопіє́м Ті:","Ісу́се, І́стино, лесть отгоня́щая; Ісу́се, Сві́те преви́шший всіх сві́тлостей.","Ісу́се, Царю́, премога́яй всіх крі́пості; Ісу́се, Бо́же, пребива́яй в ми́лості.","Ісу́се, Хлі́бе Живо́тний, наси́ти м'я, а́лчущаго; Ісу́се, Істо́чниче ра́зума, напо́й м'я, жа́ждущаго.","Ісу́се, Оде́ждо весе́лія, оді́й м'я, тлі́ннаго; Ісу́се, Покро́ве ра́дости, покри́й м'я, недосто́йнаго.","Ісу́се, Пода́телю прося́щим, даждь мі плач за гріхи́ моя́; Ісу́се, Обрі́теніє і́щущих, обря́щи ду́шу мою́.","Ісу́се, Отве́рзителю толку́щим, отве́рзи се́рдце моє́, окая́нноє; Ісу́се, Іскупи́телю грі́шних, очи́сти беззако́нія моя́.","Ісу́се, Си́не Бо́жий, поми́луй м'я."]},{"h":"Кондак 7","ps":["Хотя́ сокрове́нную та́йну от ві́ка откри́ти, я́ко овча́ на заколе́ніє веде́н бил єси́, Ісу́се, і я́ко а́гнець пря́мо стригу́щаго єго́ безгла́сен; і я́ко Бог із ме́ртвих воскре́сл єси́, і со сла́вою на Небеса́ возне́слся єси́, і нас совоздви́гл єси́, зову́щих: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вную показа́ твар, явле́йся Творе́ць нам: без сі́мене от Ді́ви воплоти́ся, із гро́ба печа́ти не руши́в, воскре́се, і ко апо́столом, две́рем затворе́нним, с пло́тію вни́де. Ті́мже чудя́щеся, воспої́м:","Ісу́се, Сло́ве необиме́нний; Ісу́се, Сло́ве несогляда́ємий.","Ісу́се, Си́ло непостижи́мая; Ісу́се, Му́дросте недоми́слимая.","Ісу́се, Бо́жество́ неопи́санноє; Ісу́се, Госпо́дство неісче́тноє.","Ісу́се, Ца́рство непобіди́моє; Ісу́се, Вдлади́чество безконе́чноє.","Ісу́се, Крі́посте височа́йшая; Ісу́се, Вла́сте ві́чная.","Ісу́се, Тво́рче мой, уще́дри м'я; Ісу́се, Спа́се мой, спаси́ м'я.","Ісу́се, Си́не Бо́жий, поми́луй м'я."]},{"h":"Кондак 8","ps":["Стра́нно Бо́га вочелові́чшася ви́дяще, устрані́мся су́єтнаго ми́ра і ум на Боже́ственная возложі́м. Сего́ бо ра́ди Бог на зе́млю сни́де, да нас на Небеса́ возведе́ть, вопію́щих Єму́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бі в ни́жніх, і ви́шніх ніка́коже отступи́ Неісче́тний, єгда́ во́лею нас ра́ди пострада́, і сме́ртію Своє́ю на́шу смерть умертви́, і воскресе́нієм живо́т дарова́ пою́щим:","Ісу́се, Сла́досте серде́чная; Ісу́се, Крі́посте тіле́сная.","Ісу́се, Сві́тлосте душе́вная; Ісу́се, бистрото́ у́мная.","Ісу́се, Ра́досте со́вістная; Ісу́се, Наде́ждо ізві́стная.","Ісу́се, Па́м'яте предві́чная; Ісу́се, Похвало́ висо́кая.","Ісу́се, Сла́во моя́ превознесе́нная; Ісу́се, Жела́ніє моє́, не отри́ни мене́.","Ісу́се, Па́стирю мой, взищи́ мене́; Ісу́се, Спа́се мой, спаси́ мене́.","Ісу́се, Си́не Бо́жий, поми́луй м'я."]},{"h":"Кондак 9","ps":["Все єстество́ а́нгельськоє безпреста́ні сла́вить пресвято́є і́м'я Твоє́, Ісу́се, на Небесі́: Свят, Свят, Свят, вопію́ще; ми же, грі́шнії, на землі́ бре́нними устна́ми вопіє́м: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я многовіща́нния я́коже ри́би безгла́сния ви́дим о Тебі́, Ісу́се, Спа́се наш: недоумі́ють бо глаго́лати, ка́ко Бог непрело́жний і челові́к соверше́нний пребива́єши? Ми же та́їнству див'я́щеся, вопіє́м ві́рно:","Ісу́се, Бо́же Предві́чний; Ісу́се, Царю́ ца́рствующих.","Ісу́се, Влади́ко владі́ющих; Ісу́се, Судіє́ живи́х і ме́ртвих.","Ісу́се, Наде́ждо ненаде́жних; Ісу́се, Утіше́ніє пла́чущих.","Ісу́се, Сла́во ни́щих; Ісу́се, не осуди́ м'я по діло́м мої́м.","Ісу́се, очи́сти м'я по ми́лості Твоє́й; Ісу́се, отжени́ от мене́ уни́ніє.","Ісу́се, просвіти́ моя́ ми́слі серде́чния; Ісу́се, даждь мі па́м'ять сме́ртную.","Ісу́се, Си́не Бо́жий, поми́луй м'я."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ мир, Восто́че восто́ком, к те́мному за́паду єстеству́ на́шему прише́д, смири́лся єси́ до сме́рти; ті́мже превознесе́ся і́м'я Твоє́ па́че вся́каго і́мене, і от всіх колі́н небе́сних і земни́х сли́шиши: Аллилу́я."]},{"h":"Ікос 10","ps":["Царю́ преві́чний, Уті́шителю, Христе́ і́стинний, очи́сти ни от вся́кия скве́рни, я́коже очи́стил єси́ де́сять прокаже́нних, і ісціли́ ни, я́коже ісціли́л єси́ сребролюби́вую ду́шу Закхе́я митаря́, да вопіє́м Ті во умиле́нії, зову́ще:","Ісу́се, Сокро́вище нетлі́нноє; Ісу́се, Бога́тство неістощи́моє.","Ісу́се, Пи́ще крі́пкая; Ісу́се, Питіє́ неісчерпа́ємоє.","Ісу́се, ни́щих Одія́ніє; Ісу́се, вдов Заступле́ніє.","Ісу́се, си́рих Защи́тниче; Ісу́се, тружда́ющихся По́моще.","Ісу́се, стра́нних Наста́вниче; Ісу́се, пла́вающих Ко́рмчий.","Ісу́се, бу́рних Оти́шіє; Ісу́се Бо́же, воздви́гни м'я, па́дшаго.","Ісу́се, Си́не Бо́жий, поми́луй м'я."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє приношу́ Ті недосто́йний, вопію́ Ті, я́ко Ханане́я: Ісу́се, поми́луй м'я! Не дщер бо, но плоть і́мам страстьми́ лю́ті біся́щуюся і я́ростію пали́мую, і ісціле́ніє даждь вопію́щу Ті: Аллилу́я."]},{"h":"Ікос 11","ps":["Світопода́тельна світи́льника су́щим во тьмі неразу́мія, пре́жде гоня́й Тя Па́вел, богоразу́мнаго гла́са си́лу внуши́ і душе́вную бистроту́ уясни́; си́це і мене́ те́мния зі́ниці душе́вния просвіти́, зову́ща:","Ісу́се, Царю́ мой прекрі́пкий; Ісу́се, Бо́же мой преси́льний.","Ісу́се, Го́споди мой пребезсме́ртний; Ісу́се, Созда́телю мой пресла́вний.","Ісу́се, Наста́вниче мой предо́брий; Ісу́се, Па́стирю мой преще́дрий.","Ісу́се, Влади́ко мой преми́лостивий; Ісу́се, Спа́се мой премилосе́рдий.","Ісу́се просвіти́ моя́ чу́вствія потемне́нная страстьми́; Ісу́се, ісціли́ моє́ ті́ло острупле́нноє гріхми́.","Ісу́се, очи́сти мой ум от по́мислов су́єтних; Ісу́се, сохрани́ се́рдце моє́ от по́хотей лука́вих.","Ісу́се, Си́не Бо́жий, поми́луй м'я."]},{"h":"Кондак 12","ps":["Благода́ть пода́ждь мі, всіх долго́в Ріши́телю, Ісу́се, і прийми́ м'я, ка́ющася, я́коже прия́л єси́ Петра́, отве́ргшагося Тебе́, і призови́ м'я, унива́ющаго, я́коже дре́вле Па́вла, гоня́ща Тя, і усли́ши м'я вопію́ща Ті: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоє́ вочелові́ченіє, восхваля́єм Тя всі і ві́руєм со Фомо́ю, я́ко Госпо́дь і Бог єси́ сідя́й со Отце́м і хотя́й суди́ти живи́м і ме́ртвим; тогда́ у́бо сподо́би м'я десна́го стоя́нія⁽2⁾, вопію́щаго:","Ісу́се, Царю́ предві́чний, поми́луй м'я; Ісу́се, Цві́те благово́нний, облагоуха́й м'я.","Ісу́се, Теплото́ люби́мая, огрі́й м'я; Ісу́се, Хра́ме предві́чний, покри́й м'я.","Ісу́се, Оде́ждо сві́тлая, украси́ м'я; Ісу́се, Би́сере честни́й, осія́й м'я.","Ісу́се, Ка́меню драги́й, просвіти́ м'я; Ісу́се, Со́лнце пра́вди, освіти́ м'я.","Ісу́се, Сві́те святи́й, облиста́й м'я; Ісу́се, болі́зні душе́вния і тіле́сния ізба́ви м'я.","Ісу́се, із руки́ сопроти́вния ізми́ м'я; Ісу́се, огня́ неугаси́маго і про́чих ві́чних мук свободи́ м'я.","Ісу́се, Си́не Бо́жий, поми́луй м'я."]},{"h":"Кондак 13","ps":["О пресла́дкий і всеще́дрий Ісу́се! Прийми́ ни́ні ма́лоє моле́ніє сіє́ на́ше, я́коже прия́л єси́ вдови́ці дві ле́пті; і сохрани́ достоя́ніє Твоє́ от враг ви́димих і неви́димих, от наше́ствія іноплеме́нник, от неду́га і гла́да, от вся́кия ско́рби, і смертоно́сния ра́ни, і гряду́щия ізми́ му́ки всіх, вопію́щих Ті: Аллилу́я, аллилу́я, аллилу́я.","§Цей кондак читається тричі. Після цього знову читають ікос 1 і кондак 1."]},{"h":"Ікос 1","ps":["А́нгелов Тво́рче і Го́споди сил, отве́рзи мі недоумі́нний ум і язи́к на похвалу́ пречи́стаго Твоєго́ і́мене, я́коже глухо́му і гугни́вому дре́вле слух і язи́к отве́рзл єси́, і глаго́лаше зови́й такова́я:","Ісу́се пречу́дний, а́нгелов Удивле́ніє; Ісу́се преси́льний, прароди́телей Ізбавле́ніє.","Ісу́се пресла́дкий, патріа́рхов Велича́ніє; Ісу́се пресла́вний, царе́й Укріпле́ніє.","Ісу́се прелюби́мий, проро́ков Ісполне́ніє; Ісу́се преди́вний, му́чеников Крі́посте.","Ісу́се прети́хій, мона́хов Ра́досте; Ісу́се преми́лостивий, пресві́теров Сла́досте.","Ісу́се премилосе́рдий, по́стников Воздержа́ніє; Ісу́се пресла́достний, преподо́бних Ра́дованіє.","Ісу́се пречестни́й, ді́вственних Цілому́дріє; Ісу́се предві́чний, грі́шников Спасе́ніє.","Ісу́се, Си́не Бо́жий, поми́луй м'я."]},{"h":"Кондак 1","ps":["Возбра́нний Воєво́до і Го́споди, а́да побіди́телю, я́ко ізба́влься от ві́чния сме́рти, похва́льная воспису́ю Ті, созда́ніє і раб Твой; но, я́ко імі́яй милосе́рдіє неізрече́нноє, от вся́ких м'я бід свободи́, зову́ща:","Ісу́се, Си́не Бо́жий, поми́луй м'я."]}],"notes":["Зі́льні — вельми, гірко.","стояння праворуч"]},{"u":"Акафіст Пресвятій Владичиці нашій Богородиці","e":"Akathist to our Most Holy Lady the Theotokos","secs":[{"ps":["Глас 8"]},{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді побіди́тельная, я́ко ізба́вльшеся от злих, благода́рственная воспису́єм Ті раби́ Твої́, Богоро́дице; но, я́ко іму́щая держа́ву непобіди́мую, от вся́ких нас бід свободи́, да зове́м Ті: Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Ікос 1","ps":["А́нгел предста́тель с небесе́ по́слан бисть, рещи́ Богоро́диці: \"Ра́дуйся!\" і, со безпло́тним гла́сом воплоща́єма Тя зря⁽1⁾, Го́споди, ужаса́шеся і стоя́ше, зови́й к Ней такова́я:","Ра́дуйся, Є́юже ра́дость возсія́єть; ра́дуйся, Є́юже кля́тва ісче́знеть.","Ра́дуйся, па́дшаго Ада́ма воззва́ніє; ра́дуйся, слез Є́виних ізбавле́ніє.","Ра́дуйся, Висото́ неудобовосходи́мая челові́чеськими по́мисли; ра́дуйся, Глубино́ неудобозри́мая і а́нгельськима очи́ма.","Ра́дуйся, я́ко єси́ Царе́во Сіда́лище; ра́дуйся, я́ко но́сиши Нося́щаго вся.","Ра́дуйся, Звіздо́ явля́ющая Со́лнце; ра́дуйся, Утро́бо Боже́ственнаго воплоще́нія.","Ра́дуйся, Є́юже обновля́ється твар; ра́дуйся, Є́юже покланя́ємся Творцю́.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 2","ps":["Ви́дящи Свята́я Себе́ в чистоті́, глаго́леть Гавриї́лу де́рзостно: \"Пресла́вноє твоєго́ гла́са неудобоприя́тельно душі́ Моє́й явля́ється, безсі́меннаго бо зача́тія рождество́ ка́ко глаго́леши, зови́й: Аллилу́я\"."]},{"h":"Ікос 2","ps":["Ра́зум недоразуміва́ємий разумі́ти Ді́ва і́щущи, возопи́ к служа́щему: \"Із боку́ чи́сту, Си́ну ка́ко єсть роди́тися мо́щно, рци Мі?\" К Не́йже он рече́ со стра́хом, оба́че зови́й си́це:","Ра́дуйся, сові́та неізрече́ннаго Таї́ннице; ра́дуйся, молча́нія прося́щих Ві́ро.","Ра́дуйся, чуде́с Христо́вих Нача́ло; ра́дуйся, велі́ній Єго́ Глави́зно.","Ра́дуйся, Лі́ствице Небе́сная, Є́юже сни́де Бог; ра́дуйся, Мо́сте, преводя́й су́щих от землі́ на Не́бо.","Ра́дуйся, А́нгелов многослову́щеє Чу́до; ра́дуйся, бісо́в многоплаче́вний Стру́пе.","Ра́дуйся, Світ неізрече́нно роди́вшая; ра́дуйся, є́же ка́ко, ні єди́нагоже научи́вшая.","Ра́дуйся, прему́дрих превосходя́щая ра́зум; ра́дуйся, ві́рних озаря́ющая сми́сли.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіни́ тогда́ к зача́тію Браконеіску́сную, і благопло́дная Тоя́ ложесна́, я́ко село́ показа́ сла́дкоє, всім хотя́щим жа́ти спасе́ніє, внегда́ пі́ти си́це: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи Богоприя́тную Ді́ва утро́бу, востече́ ко Єлисаве́ті, младе́нець же о́ноя а́біє позна́в Сея́ цілова́ніє, ра́довашеся, і ігра́ньми, я́ко пі́сньми, вопія́ше к Богоро́диці:","Ра́дуйся, о́траслі неув'яда́ємия Розго́; ра́дуйся, Плода́ безсме́ртнаго Стяжа́ніє.","Ра́дуйся, Ді́лателя ді́лающая Человіколю́бця; ра́дуйся, Сади́теля Жи́зні на́шея ро́ждшая.","Ра́дуйся, Ни́во, растя́щая гобзова́ніє щедро́т; ра́дуйся, Трапе́зо, нося́щая оби́ліє очище́ній.","Ра́дуйся, я́ко рай пи́щний процвіта́єши; ра́дуйся, я́ко приста́нище душа́м гото́виши.","Ра́дуйся, прия́тноє моли́тви Кади́ло; ра́дуйся, всего́ ми́ра очище́ніє.","Ра́дуйся, Бо́жиє к сме́ртним Благоволе́ніє; ра́дуйся, сме́ртних к Бо́гу Дерзнове́ніє.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 4","ps":["Бу́рю внутр імі́я помишле́ній сумни́тельних, цілому́дренний Іо́сиф см'яте́ся, к Тебі́ зря, небра́чній, і бракоокра́дованную помишля́я, Непоро́чная; уві́дів же Твоє́ зача́тіє от Ду́ха Свя́та, рече́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша па́стиріє А́нгелов, пою́щих плотсько́є Христо́во прише́ствіє, і те́кше, я́ко к Па́стирю, ви́дять Сего́, я́ко а́гнця непоро́чна, во чре́ві Марі́їні упа́сшася, Ю́же, пою́ще, рі́ша:","Ра́дуйся, А́гнця і Па́стиря Ма́ти; ра́дуйся, Дво́ре слове́сних ове́ць.","Ра́дуйся, неви́димих враго́в Муче́ніє; ра́дуйся, ра́йських две́рей Отверзе́ніє.","Ра́дуйся, я́ко Небе́сная сра́дуються земни́м; ра́дуйся, я́ко земна́я сликовству́ють Небе́сним.","Ра́дуйся, апо́столов немо́лчная Уста́; ра́дуйся, страстоте́рпцев непобіди́мая Де́рзосте.","Ра́дуйся, тве́рдоє ві́ри Утвержде́ніє; ра́дуйся, сві́тлоє благода́ті Позна́ніє.","Ра́дуйся, Є́юже обнажи́ся ад; ра́дуйся, Є́юже облеко́хомся сла́вою.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 5","ps":["Боготе́чную звізду́ узрі́вше волсви́, тоя́ послі́доваша зарі́; і, я́ко світи́льник держа́ще ю, то́ю іспита́ху крі́пкаго Царя́; і, дости́гше Непостижи́маго, возра́довашася, Єму́ вопію́ще: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діша о́троци Халде́йстії на руку́ Діви́чу, созда́вшаго рука́ма челові́ки, і Влади́ку разуміва́юще Єго́, а́ще і ра́бій прия́т зрак, потща́шася дарми́ послужи́ти Єму́ і возопи́ти Благослове́нній:","Ра́дуйся, Звізди́ незаходи́мия Ма́ти; ра́дуйся, Заре́ та́їнственнаго дне.","Ра́дуйся, пре́лести пещ угаси́вшая; ра́дуйся, Тро́йці таї́нники просвіща́ющая.","Ра́дуйся, мучи́теля безчелові́чнаго ізмета́ющая от нача́льства; ра́дуйся, Го́спода Человіколю́бця показа́вшая Христа́.","Ра́дуйся, ва́рварськаго ізбавля́ющая служе́нія; ра́дуйся, тимі́нія⁽2⁾ ізима́ющая діл.","Ра́дуйся, огня́ поклоне́ніє угаси́вшая; ра́дуйся, пла́мене страсте́й ізміня́ющая.","Ра́дуйся, ві́рних Наста́внице цілому́дрія; ра́дуйся, всіх родо́в Весе́ліє.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 6","ps":["Пропові́дници Богоно́снії би́вше волсви́, возврати́шася в Вавило́н, сконча́вше Твоє́ проро́чество; і пропові́давше Тя, Христа́, всім, оста́виша І́рода, я́ко буєсло́в'яща, не ві́дуща пі́ти: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́вий во Єги́пті просвіще́ніє і́стини, отгна́л єси́ лжі тьму; і́доли бо єго́, Спа́се, не терп'я́ще Твоєя́ крі́пости, падо́ша. Сих же ізба́вльшіїся вопія́ху к Богоро́диці:","Ра́дуйся, ісправле́ніє челові́ков; ра́дуйся, Низпаде́ніє бісо́в.","Ра́дуйся, пре́лести держа́ву попра́вшая; ра́дуйся, і́дольськую лесть обличи́вшая.","Ра́дуйся, Мо́ре, потопи́вшеє фарао́на ми́сленнаго; ра́дуйся, Ка́меню, напої́вший жа́ждущия жи́зні.","Ра́дуйся, о́гненний Сто́лпе, наставля́яй су́щия во тьмі; ра́дуйся, Покро́ве ми́ру, ши́рший о́блака.","Ра́дуйся, Пи́ще, ма́нни Приє́мнице; ра́дуйся, сла́дости святи́я Служи́тельнице.","Ра́дуйся, Земле́ обітова́нія; ра́дуйся, із Нея́же тече́ть мед і млеко́.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 7","ps":["Хотя́щу Симео́ну от ни́нішняго ві́ка преста́витися преле́стнаго, вда́лся єси́, я́ко младе́нець, тому́; но позна́лся єси́ єму́ і Бог Соверше́нний. Ті́мже удиви́ся Твоє́й неізрече́нній прему́дрості, зови́й: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую показа́ твар, я́влься Зижди́тель нам от Него́ би́вшим, із безсі́менния прозя́б утро́би, і сохрани́в Ю, я́коже бі, нетлі́нну. Да чу́до ви́дяще, воспої́м Ю, вопію́ще:","Ра́дуйся, Цві́те нетлі́нія; ра́дуйся, Ві́нче воздержа́нія.","Ра́дуйся, воскресе́нія о́браз облиста́ющая; ра́дуйся, А́нгельськоє житіє́ явля́ющая.","Ра́дуйся, Дре́во світлоплодови́тоє, от него́же пита́ються ві́рнії; ра́дуйся, Дре́во благосінноли́ственноє, і́мже покрива́ються мно́зі.","Ра́дуйся, во чре́ві нося́щая Ізба́вителя пліне́нним; ра́дуйся, ро́ждшая наста́вника заблу́ждшим.","Ра́дуйся, Судії́ Пра́веднаго Умоле́ніє; ра́дуйся, мно́гих согріше́ній проще́ніє.","Ра́дуйся, оде́ждо наги́х дерзнове́нія; ра́дуйся, Люби́, вся́коє жела́ніє побіжда́ющая.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 8","ps":["Стра́нноє рождество́ ви́дівше, устрані́мся ми́ра, ум на Небеса́ прело́жше; сего́ бо ра́ди висо́кий Бог, на землі́ яви́ся смире́нний челові́к, хотя́й привлещи́ к висоті́, Тому́ вопію́щия: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бі в ни́жніх, і ви́шніх ніка́коже отступи́ неопи́санноє Сло́во; снизхожде́ніє бо Боже́ственноє, не прехожде́ніє же мі́стноє бисть, і Рождество́ от Ді́ви Богоприя́тния, сли́шащия сія́:","Ра́дуйся, Бо́га невмісти́маго Вмісти́лище; ра́дуйся, честна́го та́їнства две́рі.","Ра́дуйся, неві́рних сумни́тельноє сли́шаніє; ра́дуйся, ві́рних ізві́стная Похвало́.","Ра́дуйся, Колесни́це Пресвята́я Су́щаго на Херуви́міх; ра́дуйся, Селе́ніє пресла́вноє Су́щаго на Серафи́міх.","Ра́дуйся, проти́вная в то́жде собра́вшая; ра́дуйся, ді́вство і рождество́ сочета́вшая.","Ра́дуйся, Є́юже разріши́ся преступле́ніє; ра́дуйся, Є́юже отве́рзеся рай.","Ра́дуйся, ключу́ Ца́рствія Христо́ва; ра́дуйся, Наде́ждо благ ві́чних.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ А́нгельськоє удиви́ся вели́кому Твоєго́ вочелові́ченія ді́лу; непристу́пнаго бо я́ко Бо́га, зря́ше всім присту́пнаго Челові́ка, нам у́бо спребива́юща, сли́шаща же от всіх: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я многовіща́нния, я́ко ри́би безгла́сния, ви́дим о Тебі́, Богоро́дице; недоуміва́ють бо глаго́лати, є́же ка́ко, і Ді́ва пребива́єши, і роди́ти возмогла́ єси́; ми же, та́їнству див'я́щеся, ві́рно вопіє́м:","Ра́дуйся, прему́дрости Бо́жия Прия́телище; ра́дуйся, промишле́нія Єго́ Сокро́вище.","Ра́дуйся, любому́дрия нему́дрия явля́ющая; ра́дуйся, хитрослове́сния безслове́сния облича́ющая.","Ра́дуйся, я́ко обуя́ша лю́тії взиска́теле; ра́дуйся, я́ко ув'ядо́ша баснотво́рці.","Ра́дуйся, афіне́йськая плете́нія растерза́ющая; ра́дуйся, ри́барськія мре́жі ісполня́ющая.","Ра́дуйся, із глубини́ неві́дінія ізвлача́ющая; ра́дуйся, мно́гі в ра́зумі просвіща́ющая.","Ра́дуйся, Кораблю́ хотя́щих спасти́ся; ра́дуйся, Приста́нище жите́йських пла́ваній.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ мир, І́же всіх Украси́тель, к сему́ самообітова́н при́йде, і Па́стир сий я́ко Бог, нас ра́ди яви́ся по нам челові́к; подо́бним бо подо́бноє призва́в, я́ко Бог сли́шить: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ ді́вам, Богоро́дице Ді́во, і всім к Тебі́ прибіга́ющим; і́бо небесе́ і землі́ Творе́ць устро́ї Тя, Пречи́стая, все́лься во утро́бі Твоє́й, і вся приглаша́ти Тебі́ научи́в:","Ра́дуйся, Сто́лпе ді́вства; ра́дуйся, Двер спасе́нія.","Ра́дуйся, Нача́льнице ми́сленнаго назда́нія; ра́дуйся, Пода́тельнице Бо́же́ственния бла́гости.","Ра́дуйся, Ти бо обнови́ла єси́ зача́тия сту́дно; ра́дуйся, Ти бо наказа́ла єси́ окра́денния умо́м.","Ра́дуйся, тли́теля сми́слов упражня́ющая; ра́дуйся, Сі́ятеля чистоти́ ро́ждшая.","Ра́дуйся, Черто́же безсі́меннаго уневі́щенія; ра́дуйся, ві́рних Го́сподеві сочета́вшая.","Ра́дуйся, до́брая Младопита́тельнице ді́вам; ра́дуйся, Невістокраси́тельнице душ святи́х.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 11","ps":["Пі́ніє вся́коє побіжда́ється, спростре́тися тща́щеєся ко мно́жеству мно́гих щедро́т Твої́х; равночи́сленния бо піска́ пі́сні а́ще прино́сим Ті, Царю́ Святи́й, нічто́же соверша́єм досто́йно, я́же дал єси́ нам, Тебі́ вопію́щим: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мную свіщу́, су́щим во тьмі я́вльшуюся, зрим Святу́ю Ді́ву; невеще́ственний бо вжига́ющи огнь, наставля́єть к ра́зуму Бо́же́ственному вся, заре́ю ум просвіща́ющая, зва́нієм же почита́ємая, си́ми:","Ра́дуйся, Луче́ у́мнаго Со́лнця; ра́дуйся, Світи́ло незаходи́маго Сві́та.","Ра́дуйся, Мо́лніє, ду́ші просвіща́ющая; ра́дуйся, я́ко гром, враги́ устраша́ющая.","Ра́дуйся, я́ко многосві́тлоє возсіява́єши просвіще́ніє; ра́дуйся, я́ко многотеку́щую істоча́єши ріку́.","Ра́дуйся, купі́лі живопису́ющая о́браз; ра́дуйся, гріхо́вную от'є́млющая скве́рну.","Ра́дуйся, Ба́не, омива́ющая со́вість; ра́дуйся, Ча́ше, че́рплющая ра́дость.","Ра́дуйся, Обоня́ніє Христо́ва благоуха́нія; ра́дуйся, Животе́ та́йнаго весе́лія.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 12","ps":["Благода́ть да́ти восхоті́в долго́в дре́вніх, всіх долго́в Ріши́тель челові́ком, при́йде Собо́ю ко отше́дшим Того́ благода́ті; і, раздра́в рукописа́ніє, сли́шить от всіх си́це: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоє́ Рождество́, хва́лим Тя всі, я́ко одушевле́нний храм, Богоро́дице; во Твоє́й бо всели́вся утро́бі, содержа́й вся руко́ю Госпо́дь, освяти́, просла́ви, научи́ вопи́ти Тебі́ всіх:","Ра́дуйся, Селе́ніє Бо́га і Сло́ва; ра́дуйся, Свята́я святи́х бо́льшая.","Ра́дуйся, Ковче́же позлаще́нний Ду́хом; ра́дуйся, Сокро́вище живота́ неістощи́моє.","Ра́дуйся, честни́й ві́нче люде́й благочести́вих; ра́дуйся, честна́я Похвало́ ієре́єв благогові́йних.","Ра́дуйся, Це́ркве непоколеби́мий Сто́лпе; ра́дуйся, ца́рствія неруши́мая Стіно́.","Ра́дуйся, Є́юже воздви́жуться побі́ди; ра́дуйся, Є́юже низпа́дають вразі́.","Ра́дуйся, ті́ла моєго́ врачева́ніє; ра́дуйся, душі́ Моєя́ спасе́ніє.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти, ро́ждшая всіх святи́х Святі́йшеє Сло́во, ни́нішнєє приє́мши приноше́ніє, от вся́кия ізба́ви напа́сти всіх, і бу́дущия ізми́ му́ки, Тебі́ вопію́щих: Аллилу́я.","§Цей кондак читається тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел предста́тель с небесе́ по́слан бисть, рещи́ Богоро́диці: \"Ра́дуйся!\" і, со безпло́тним гла́сом воплоща́єма Тя зря, Го́споди, ужаса́шеся і стоя́ше, зови́й к Ней такова́я:","Ра́дуйся, Є́юже ра́дость возсія́єть; ра́дуйся, Є́юже кля́тва ісче́знеть.","Ра́дуйся, па́дшаго Ада́ма воззва́ніє; ра́дуйся, слез Є́виних ізбавле́ніє.","Ра́дуйся, Висото́ неудобовосходи́мая челові́чеськими по́мисли; ра́дуйся, Глубино́ неудобозри́мая і а́нгельськима очи́ма.","Ра́дуйся, я́ко єси́ Царе́во Сіда́лище; ра́дуйся, я́ко но́сиши Нося́щаго вся.","Ра́дуйся, Звіздо́ явля́ющая Со́лнце; ра́дуйся, Утро́бо Боже́ственнаго воплоще́нія.","Ра́дуйся, Є́юже обновля́ється твар; ра́дуйся, Є́юже покланя́ємся Творцю́.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді побіди́тельная, я́ко ізба́вльшеся от злих, благода́рственная воспису́єм Ті раби́ Твої́, Богоро́дице; но, я́ко іму́щая держа́ву непобіди́мую, от вся́ких нас бід свободи́, да зове́м Ті: Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Молитва","ps":["Пресвята́я Влади́чице моя́ Богоро́дице, святи́ми Твої́ми і всеси́льними мольба́ми отжени́ от мене́, смире́ннаго і окая́ннаго раба́ Твоєго́, уни́ніє, забве́ніє, неразу́міє, нераді́ніє, і вся скве́рная, лука́вая і ху́льная помишле́нія от окая́ннаго моєго́ се́рдця і от помраче́ннаго ума́ моєго́, і погаси́ пла́мень страсте́й мої́х, я́ко нищ єсьм і окая́нен; і ізба́ви м'я от мно́гих і лю́тих воспомина́ній і предприя́тій, і от всіх дійств злих свободи́ м'я; я́ко Благослове́нна єси́ от всіх родо́в, і сла́виться пречестно́є і́м'я Твоє́ во ві́ки віко́в. Амі́нь."]}],"notes":["бачачи","Тимѣ́нїе - багно, трясовина. Тимі́нія ізима́ющая діл — Та, що від лихих вчинків відхиляє."]},{"u":"Акафіст святій великомучениці Варварі","e":"Akathist to the Holy Great Martyr Barbara","secs":[{"h":"Кондак 1","ps":["Ізбра́нной Бо́гом от ідолослужи́тельнаго ро́да і призва́нной во язи́к свят, в лю́ди обновле́нія, неві́сті Христо́ві, я́ко ізбавля́ющіїся тобо́ю от разли́чних зол і обстоя́нія, благода́рственная пі́нія і хвале́нія воспису́єм ті моли́твенници твої́, свята́я і всехва́льная великому́ченице, ти же іму́щи дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, да с ра́достію зове́м ті:","Ра́дуйся, Варва́ро, неві́сто Христо́ва прекра́сная."]},{"h":"Ікос 1","ps":["А́нгелов честну́ю і вселюбе́зную чистоту́ непоро́чно сохра́нши, честна́я Варва́ро, а́нгелом сожи́тельниця би́ти сподо́билася єси́, с ни́миже єгда́ поє́ши Тро́йчеськую піснь Бо́гу на Небесі́, усли́ши нас, пою́щих тебі́ на землі́ похва́льная пі́нія сія́:","Ра́дуйся, отрокови́це, Бо́гом Отце́м предуста́вленная би́ти сообра́зна в страда́нії о́бразу Си́на Єго́; ра́дуйся, Си́ном Бо́жиїм, Сві́том от Сві́та, призва́нная із тьми в чу́дний світ ві́ри і благода́ті Єго́.","Ра́дуйся, я́ко позва́вшему тя Свято́му Ду́ху, і сама́ ті́лом і ду́хом свята́ єси́; ра́дуйся, я́ко от скве́рни пло́ті і ду́ха непоро́чну тя соблюла́ єси́.","Ра́дуйся, рожде́нному от Ді́ви Жениху́ Христу́ ді́ву тя чи́стую обручи́вшая; ра́дуйся, земна́го обру́чника па́че Небе́снаго зна́ти не восхоті́вшая.","Ра́дуйся, кри́не ді́вства, посреді́ те́рнія і́дольськаго прора́стший до́лі; ра́дуйся, цві́те чистоти́, в неув'яда́ємой сла́ві цвіту́щий горі́.","Ра́дуйся, в небе́сном вертогра́ді Христо́ва благоуха́нія наслажда́ющаяся; ра́дуйся, красні́йшаго па́че сино́в челові́чеських зрі́нієм та́мо утіша́ющаяся.","Ра́дуйся, убіли́вшая ри́зи твоя́ в Кро́ві А́гнчей на землі́; ра́дуйся, в ли́ці ді́вственном послі́дующая Бо́жиєму А́гнцю на Небесі́.","Ра́дуйся, Варва́ро, неві́сто Христо́ва прекра́сная."]},{"h":"Кондак 2","ps":["Ви́дящи свята́я Варва́ра себе́ на висо́ком столпі́ от отця́ поста́влену, помишля́ше себе́ ма́нієм Бо́жиїм к Небесі́ би́ти возводи́му. Разу́мная у́бо восхожде́нія в се́рдці своє́м поло́жши, ті́ми от тьми ко сві́ту і от преле́стних і́долов ко і́стинному Бо́гу у́мні восхожда́ше, пою́щи Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум неуразумі́нний о Єди́ном всея́ тва́рі Творці́ разумі́ти, ді́ва свята́я Варва́ра, і́щущи, бесі́доваше со свої́м сі ра́зумом, глаго́ля: от те́мних куми́ров чу́дним світи́лам небе́сним ка́ко бі созда́тися мо́щно, рци мі. К не́йже он со Псало́мником рече́: всі бо́зі язи́к, бі́сове, єди́н же єсть Бог і Госпо́дь, І́же небеса́ і вся світи́ла їх сотвори́. Таково́му твоєму́, му́драя ді́во, ра́зуму див'я́щеся, глаго́лем:","Ра́дуйся, па́че ста́рець ідолослужи́тельних разу́мнійшая; ра́дуйся, па́че мудреце́в ми́ра сего́ мудрі́йшая.","Ра́дуйся, я́ко тебі́ безві́стная і та́йная прему́дрости своєя́ Бог яви́л єсть; ра́дуйся, я́ко тебе́ і́стиннаго богосло́вія Сам Бог Сло́во научи́л єсть.","Ра́дуйся, всіх звіздоче́тцев умо́м Христо́вим превозше́дшая; ра́дуйся, я́вственніє па́че о́ніх небе́сний круг прозрі́вшая.","Ра́дуйся, я́ко в тва́рі, а́ки в зерца́лі, Самаго́ Творця́ усмотрі́ла єси́; ра́дуйся, я́ко в созда́нних світи́лах Несозда́нний Світ узрі́ла єси́.","Ра́дуйся, ни́ні уже́ кромі́ зерца́ла світ лиця́ Бо́жия на Небесі́ зря́щая; ра́дуйся, тім сві́том неізрече́нно веселя́щаяся.","Ра́дуйся, у́мная звіздо́, єя́же озаре́нієм лице́ Бо́жиє, я́ко со́лнце, сві́тло нам явля́ється; ра́дуйся, ми́сленная луно́, є́юже нощ заблужде́нія я́ко день просвіща́ється.","Ра́дуйся, Варва́ро, неві́сто Христо́ва прекра́сная."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго даде́ тогда́ святі́й Варва́рі, я́коже дре́влі проро́ку Ієзекі́їлю, лице́ адама́нтово, си́льно пред всі́ми ідолослужи́тельми, во є́же не убоя́тися єй от зві́рськаго лиця́ їх, ні ужаса́тися лю́таго преще́нія. Ті́мже со дерзнове́нієм мужему́дренная ді́ва взива́ше: Тро́йцю чту, Єди́но Бо́жество́, і Той ві́рою покланя́ющися, велегла́сно пою́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи свята́я Варва́ра сви́ше да́нную себі́ му́дрость, востече́ к ді́лателем ба́ні оте́чеськия, і о́нім проявля́я та́йну Святи́я Тро́йці, повелі́ три о́кна в ба́ні устро́їти. А́ще, рече́, ідолослужи́теліє уста́ і́муть і не глаго́лють сла́ви і́стиннаго Бо́га, то ка́менния в сей ба́ні сті́ни треми́ о́кнами, а́ки треми́ устна́ми, да свиді́тельствують, я́ко Єди́н єсть Бог, в Тро́йці Святі́й от всея́ тва́рі сла́вимий і покланя́ємий. За таково́є у́бо мудрова́ніє, свята́я Варва́ро, прийми́ похвалу́ сію́:","Ра́дуйся, в трео́конной ба́ні купі́ль свята́го креще́нія, во і́м'я Тро́йці Пресвяти́я, ізобрази́вшая; ра́дуйся, в купі́лі води́ і Ду́ха, к сим же і кро́ве твоєя́ му́ченичеськия, тебе́ ізми́вшая.","Ра́дуйся, я́ко треми́ о́кнами тьму многобо́жія, Тро́йці Святі́й проти́внаго, прогна́ла єси́; ра́дуйся, я́ко о́кнами треми́ світ Тро́їчеський я́сно узрі́ла єси́.","Ра́дуйся, я́ко ті́ми треми́ о́кнами призрі́ на тя Со́лнце Пра́вди, тридне́вно возсія́вшеє от гро́ба; ра́дуйся, я́ко ті́ми тебі́ возсія́ день Тро́їчеськаго спасе́нія.","Ра́дуйся, се́рдце твоє́ Єди́ному в Тро́йці Бо́гу всегда́ отве́рсто імі́вшая; ра́дуйся, чу́вства твоя́ пред бра́нію тріє́х враго́в, пло́ті, ми́ра і дия́вола, крі́пко заключи́вшая.","Ра́дуйся, я́ко в душі́ твоє́й три ми́сленная о́кна, ві́ри, наде́жди і любве́, устро́їла єси́; ра́дуйся, я́ко ті́ми треми́ о́кнами при Тро́їчеськом Бо́жестві́ треми́ де́ньми воздви́женную Ті́ла Христо́ва Це́рков усмотрі́ла єси́.","Ра́дуйся, я́ко тебі́ Небеса́ от тріє́х ієра́рхій а́нгельських отверзо́шася; ра́дуйся, я́ко тебе́ го́рнія оби́телі Тро́їчеськія ра́достно прия́ша.","Ра́дуйся, Варва́ро, неві́сто Христо́ва прекра́сная."]},{"h":"Кондак 4","ps":["Бу́ря я́рости ве́лія отця́ твоєго́, ди́шущаго преще́нієм і уби́йством, возшуме́ на храм душі́ твоєя́, свята́я Варва́ро, но того́ не возмо́же поколеба́ти, основа́н бо бі на тве́рдом ві́ри Христо́ви ка́мені, на не́мже ти, му́драя ді́во, неподви́жимо стоя́щи, укріпля́ющему тя Ісу́су Христу́ піснь воспіва́ла єси́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав от тебе́, му́дрия дще́рі, оте́ць твой Діоско́р несли́шанная о Святі́й Тро́йці словеса́, я́ко а́спід глухи́й затка́ у́ші своя́ і по подо́бію змії́ну с жа́лом ядоно́сним, устреми́ся со о́стрієм меча́ на твоє́ уби́йство; но ти, неві́сто Христо́ва Варва́ро, подража́ющи Жениха́ Твоєго́ Ісу́са, біжа́вшаго от меча́ І́родова, бі́гала єси́ от меча́ Діоско́рова, жела́ющи се́рдце єго́ от зві́рськия я́рости в любо́в оте́чеськую обрати́ти. Ми же разу́мноє твоє́ бі́гство зва́нії почита́єм си́ми:","Ра́дуйся, блаже́нная, ізгна́нная із до́му земна́го пра́вди ра́ди; ра́дуйся, бога́тая в Бо́га, лише́нная оте́чеських бога́тств Христа́ ра́ди.","Ра́дуйся, я́ко твоєго́ обнища́нія єсть Ца́рствіє Небе́сноє; ра́дуйся, я́ко тебі́ угото́вася ві́чних благ сокро́вище.","Ра́дуйся, слове́сная а́гнице, от зла́го во́лка мучи́теля к до́брому Па́стирю Христу́ прибі́гшая; ра́дуйся, во двор пра́ведних ове́ць Єго́, одесну́ю стоя́щих, вше́дшая.","Ра́дуйся, незло́бивая голуби́це, от земна́го вра́на в покро́в Небе́снаго Орла́ прелеті́вшая; ра́дуйся, в кро́ві крилу́ Єго́ до́брий тебі́ покро́в обрі́тшая.","Ра́дуйся, Небе́снаго Отця́ дщи честна́я, я́ко от земна́го роди́теля с безче́стієм на смерть гони́ма била́ єси́; ра́дуйся, я́ко от Безсме́ртнаго Го́спода Сла́ви в жизнь ві́чную со сла́вою прия́та єси́.","Ра́дуйся, тоя́жде і нам жи́зні присножела́ющая хода́тайце; ра́дуйся, прилі́жная о нас к Бо́гу моли́твеннице.","Ра́дуйся, Варва́ро, неві́сто Христо́ва прекра́сная."]},{"h":"Кондак 5","ps":["Боготе́чной звізді́ била́ єси́ подо́бна, свята́я великому́ченице Варва́ро; біжа́щи бо пред отце́м твої́м, наставля́ла єси́ того́ та́їнственні на путь, веду́щий ко Пра́ведному Солнцю, от Ді́ви возсія́вшему, Христу́ Бо́гу. Оба́че он душе́внима осліпле́н очи́ма, а́біє і тіле́снима не узрі́ тя пред собо́ю біжа́щую; ти бо сквозі́ ка́менную, тебі́ велі́нієм Бо́жиїм разступи́вшуюся го́ру проше́дши, скри́лася єси́ от о́чію єго́ в ка́менній пеще́рі, да от среди́ ка́менія, я́ко пти́ця, да́си глас Бо́гу, воспіва́ющи: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше тя па́стиріє, верху́ гори́ о́вці пасу́щії, в ка́мені кри́ющуюся, дивля́хуся, глаго́люще: что сія́ слове́сная а́гниця? Ко́єго во́лка бі́гаєть? І се Діоско́р, па́че во́лка люті́йший, востече́ на го́ру, і тебе́ та́мо кри́ющуюся обрі́ть, і похи́тив за діви́чеськія твоя́ власи́, влеча́ше ко своєму́ до́му по жесто́кому путі́, на не́мже тя ві́рнії сріта́єм приві́тствії си́ми:","Ра́дуйся, младо́му єле́ню на гора́х арома́тських уподо́бившаяся; ра́дуйся, го́рняя, па́че до́льних восхожде́нія в се́рдці твоє́м полага́ющи, возлюби́вшая.","Ра́дуйся, ізби́вшая поги́бельнаго ідолослуже́нія ро́ва; ра́дуйся, на го́ру Тро́їчеськаго поклоне́нія восте́кшая.","Ра́дуйся, сквозі́ ка́меніє проше́дшая, от каменносе́рдаго бі́гающи гоне́нія; ра́дуйся, среді́ ка́менія Ка́мень Христа́, утвержда́ющаго тя, обрі́тшая.","Ра́дуйся, в пеще́ру ка́менную вше́дшая, ви́діти Ісу́са во гро́бі ка́менном би́вша положе́нна; ра́дуйся, уже́ Того́ ви́дящая на Престо́лі Сла́ви сідя́ща.","Ра́дуйся, я́ко власи́ глави́ твоєя́, за Христа́ храня́щаго, да і влас глави́ челові́чеськия не поги́бнеть, істо́ргани суть на землі́; ра́дуйся, я́ко ті́ї от Христа́ ізочте́ні суть ко увінча́нію на Небесі́.","Ра́дуйся, власи́ твоя́ кро́вію до́лі, я́ко цвіта́ми, обагри́вшая; ра́дуйся, заплете́ніє власо́в твої́х окровавле́нних в віне́ць тебі́ злати́й обрати́вшая.","Ра́дуйся, Варва́ро, неві́сто Христо́ва прекра́сная."]},{"h":"Кондак 6","ps":["Пропові́дником богоно́сним, апо́столом Христо́вим, поревнова́вши дерзнове́нно, пред лице́м мучи́телей пропові́дала єси́ Христа́, і́стиннаго Бо́га; і Єго́ ра́ди лю́тия ра́ни, власяни́ми ру́би і о́стрим чре́пієм болі́зненно потира́ємия, му́жественно претерпі́ла єси́, свята́я Варва́ро. Та́же в темни́цю всажде́на, в ней а́ки в черто́зі о Христі́ Ісу́сі ликова́ла єси́, пою́щи Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́вий в се́рдці твоє́м просвіще́ніє і́стиннаго Богоразу́мія, возсія́ і во очесі́х твої́х світ Боже́ственнаго лиця́ Своєго́ Христо́с Госпо́дь; Той бо, я́ко возлю́бленний твой жени́х, в полу́нощі к тебі́, непоро́чній Своє́й неві́сті, в темни́цю прише́д, любе́зно тя посіти́, от ран ісціли́ і сві́тлостію лиця́ Своєго́ неізрече́нно ду́шу твою́ возвесели́, нас же, ві́рних, научи́ пі́ти тебі́ сицева́я:","Ра́дуйся, за страда́вшаго біє́ніє Христа́ неща́дно біє́нная; ра́дуйся, біє́нія терпі́нієм неви́димаго врага́ уби́вшая.","Ра́дуйся, я́зви Го́спода твоєго́ на ті́лі твоє́м носи́вшая; ра́дуйся, от всіх язв, ті́мжде Го́сподем, на ті́лі твоє́м ісціле́вшая.","Ра́дуйся, я́ко Сам Госпо́дь, Світ ми́ра, тебі́, в темни́ці би́вшей, Себе́ яви́л єсть; ра́дуйся, я́ко Сам душі́ і ті́ла Врач, тебе́, больну́ю, посіти́л єсть.","Ра́дуйся, чрез земну́ю темни́цю в Небе́сний черто́г сві́тло вше́дшая; ра́дуйся, от крове́й твої́х бра́чную тебі́ оде́жду істка́вшая.","Ра́дуйся, я́ко тобо́ю от мно́гих ран грі́шнії ісціля́ються; ра́дуйся, я́ко тобо́ю от всіх болі́зней с ві́рою тя призива́ющії уздравля́ються.","Ра́дуйся, уз гріхо́вних ско́рая ріши́тельнице; ра́дуйся, язв многозло́бних до́брая ціле́бнице.","Ра́дуйся, Варва́ро, неві́сто Христо́ва прекра́сная."]},{"h":"Кондак 7","ps":["Хотя́щу безу́мному мучи́телю жела́ніє своє́ улучи́ти, і єще́ покуша́ющемуся ласка́тельними словеси́ тебе́, свята́я Варва́ро, от і́стиннаго Бо́га отврати́ти ко преле́стним і́долом, ти, я́ко му́драя ді́ва, отвіща́ла єси́ тому́: пе́рвіє тве́рдий адама́нт в м'я́гкий воск претвори́ши, не́жели мене́ отврати́ши от Христа́, Бо́га моєго́; Того́ бо, со Отце́м і Святи́м Ду́хом, Єди́наго і́стиннаго Бо́га іспові́дую, сла́влю, хвалю́, і пою́ Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую показа́ безчелові́чія я́рость звірообра́зний мучи́тель, єгда́ тебе́, свята́я великому́ченице Варва́ро, повелі́ на дре́ві пові́сити, і ногтьми́ желі́зними ті́ло твоє́ строга́ти, і свіща́ми горя́щими твоя́ опаля́ти ре́бра, єще́ же і мла́том во главу́ тя́жко би́ти. Сіє́ пачеєсте́ственноє терпі́ніє твоє́ благогові́йно воспомина́юще, похвала́ми блажи́м тя си́ми:","Ра́дуйся, я́ко пові́шена била́ єси́ на дре́ві, Христа́ ра́ди на Кресті́ расп'я́таго; ра́дуйся, стро́гана по ре́бром, Ісу́са ра́ди, копіє́м в ре́бра прободе́ннаго.","Ра́дуйся, я́ко огнь любве́ к Бо́гу в се́рдці твоє́м возжегла́ єси́; ра́дуйся, я́ко за Того́ о́гненними свіща́ми пали́ма била́ єси́.","Ра́дуйся, тверді́йшая адама́нта в терпі́нії невреди́мом; ра́дуйся, кріпча́йшая ка́меннаго столпа́ в му́жестві непоколеби́мом.","Ра́дуйся, я́ко мла́том би́вшим тя по главі́, віне́ць Ца́рствія тебі́ іскова́ся; ра́дуйся, я́ко ті́мже мла́том глава́ врага́ твоєго́ сокруши́ся.","Ра́дуйся, я́ко со Христо́м, Єго́ ра́ди, на землі́ страда́ла єси́; ра́дуйся, я́ко с Ним і о Нем на Небесі́ прославля́єшися.","Ра́дуйся, всіх враго́в на́ших крі́пкая побіди́тельнице; ра́дуйся, во всіх біда́х на́ших ско́рая помо́щнице.","Ра́дуйся, Варва́ро, неві́сто Христо́ва прекра́сная."]},{"h":"Кондак 8","ps":["Стра́нноє і стра́шноє святи́я Варва́ри страда́ніє ви́дящи, благові́рная в жена́х Іюлія́нія удиви́ся зіло́; ка́ко млада́ отрокови́ця в ю́ностнім тілесі́ такови́я му́жественно за Христа́ терпи́ть му́ки? Та́же, сле́знаго іспо́лнившися умиле́нія, благода́рственно і та возопи́ Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь Сладча́йший Ісу́с сла́дость, весь жела́ніє тебі́ бисть, свята́я Варва́ро; сла́дці бо Єго́ ра́ди го́ркія терпі́ла єси́ му́ки, глаго́лющи: ча́шу страда́ній, ю́же даде́ мі возлю́бленний мой Жени́х, не і́мам ли пи́ти? Ті́мже і сама́ показа́лася єси́ ча́ша, сла́дость чуде́сних ісціле́ній ізлива́ющая всім вопію́щим к тебі́ сицева́я:","Ра́дуйся, отве́ргшая во а́дськоє го́ре і́дольськую го́ресть; ра́дуйся, возлюби́вшая небе́сную Ісу́сову сла́дость.","Ра́дуйся, ми́сленная ста́мно⁽1⁾, ма́нну бра́шна творе́нія во́лі Бо́жия в себі́ іму́щая; ра́дуйся, ві́рних во благи́х жела́ніє ісполня́ющая.","Ра́дуйся, ріко́, іспо́лненная благода́ті Бо́жия вода́ми; ра́дуйся, істо́чниче, кип'я́щий чуде́с ізлія́нії.","Ра́дуйся, я́ко пчела́, от злово́ннаго і́дольських жертв ди́ма отлеті́вшая; ра́дуйся, во благоуха́нную ми́ра Христо́ва воню́ сла́дці прите́кшая.","Ра́дуйся, я́ко твої́ми во всем ті́лі я́звами била́ єси́ подо́бна со́ту; ра́дуйся, я́ко кро́ві твоєя́ ка́плі сладча́йшія па́че ме́да би́ша пресла́дкому Ісу́су.","Ра́дуйся, я́ко всім ві́рним воспомина́ніє твоє́ пресла́дко; ра́дуйся, я́ко всій Це́ркві Христо́вой і́м'я твоє́ прече́cтно.","Ра́дуйся, Варва́ро, неві́сто Христо́ва прекра́сная."]},{"h":"Кондак 9","ps":["Все єстество́ а́нгельськоє ве́лією возра́довася ра́достію, узрі́вши му́жественную крі́пость твою́, свята́я і непобіди́мая му́ченице Варва́ро; ви́дівше бо а́нгельстії чи́нове ве́тхаго врага́, прего́рдаго кня́зя тьми, со всім єго́ бісо́вським і і́дольським по́лчищем от тебе́, єди́ния млади́я ді́ви, посра́мленнаго, побіжде́ннаго же і под но́зі твої́ пове́рженнаго, ве́ліїм гла́сом возопи́ша Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тiії многовіща́ннії ри́торськими свої́ми язи́ки не возмо́гуть ізрещи́ вели́чества твої́х болі́зненних страда́ній, о Варва́ро; кто бо ска́жеть болі́знь твою́, коли́ка бі, єгда́ сосця́ твоя́ урі́зана би́ша? Кто ізрече́ть студ лиця́ діви́чеськаго, єгда́ обнаже́на по всему́ гра́ду от беззако́нних мучи́телей води́ма била́ єси́? Сицеву́ю болі́знь і безче́стіє твоє́ ми то́чію воспом'яну́вше, содрога́ємся і со умиле́нієм глаго́лем си́це:","Ра́дуйся, до́брая лі́торасле са́да Ісу́сова; ра́дуйся, і́стинная лозо́ виногра́да Христо́ва.","Ра́дуйся, два сосця́ твоя́ отрі́занная, а́ки два гре́зна, в честь Го́сподеві твоєму́ прине́сшая; ра́дуйся, кров твою́, а́ки вино́ умиле́нія, от тіх істочи́вшая.","Ра́дуйся, я́ко Христа́ ра́ди обнаже́ннаго і ти риз твої́х совлече́на била́ єси́; ра́дуйся, я́ко Єго́ ра́ди, во Ієрусали́мі руга́тельні води́маго, і ти по гра́ду на поруга́ніє води́ма била́ єси́.","Ра́дуйся, от а́нгела сві́тлою оде́ждою в наготі́ твоє́й оді́янная; ра́дуйся, то́ю от сту́дних оче́с неви́димо покрові́нная.","Ра́дуйся, чу́дний а́нгелом і челові́ком позо́р би́вшая; ра́дуйся, і самі́х мучи́телей терпі́нієм твої́м удиви́вшая.","Ра́дуйся, я́ко Сам Госпо́дь сви́ше призрі́ на твоя́ страда́нія; ра́дуйся, я́ко Сам Той Подвигополо́жник похвали́ по́двиги твоя́.","Ра́дуйся, Варва́ро, неві́сто Христо́ва прекра́сная."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ ду́шу твою́, о ті́лі твоє́м вся́чеськи неради́ла єси́, свята́я Варва́ро; єгда́ бо на тя ме́чноє на смерть осужде́ніє ізи́де, ти под меч о́стрий, а́ки под віне́ць кра́сний, ра́достно іду́щи, Бо́гу, в му́ченичеськом по́двизі тебе́ укріпля́ющему, воспіва́ла єси́ піснь: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіни́ ка́менния тве́рдіє окамене́нний се́рдцем бисть Діоско́р, твой, свята́я Варва́ро, не уже́ роди́тель, но лю́тий мучи́тель; той бо, я́ко усли́ша твоє́ ме́чноє на смерть осужде́ніє, не то́чію о сме́рті твоє́й не поболі́, но і сам свої́м мече́м на мі́сті осужде́нія твою́ святу́ю усіче́ главу́, і та́ко, по предрече́нію Госпо́дню, окая́нний оте́ць предаде́ на смерть своє́ ча́до. В той у́бо блаже́нній твоє́й кончи́ні, прийми́ от нас пі́нія сія́:","Ра́дуйся, за главу́ Це́ркве Христа́ под меч главу́ твою́ прекло́ншая; ра́дуйся, за любо́в к Небе́сному человіколюби́вому Отцю́ Безсме́ртному на смерть от земна́го безчелові́чнаго отця́ тлі́ннаго пре́данная.","Ра́дуйся, тече́ніє му́ченичеськаго путі́ сконча́вшая до́брі; ра́дуйся, ві́ру Безсме́ртному Обру́чнику Христу́ до сме́рти сохра́ншая бо́дрі.","Ра́дуйся, си́лою сви́ше на брань проти́ву сил преіспо́дніх препоя́санная; ра́дуйся, побідоно́сною сла́вою в ви́шніх от Христа́ Побіди́теля оді́янная.","Ра́дуйся, ору́жієм благоволе́нія Бо́жия вінча́нная на землі́; ра́дуйся, цві́том нетлі́нія украше́нная на Небесі́.","Ра́дуйся, ді́вам добро́то і похвале́ніє; ра́дуйся, му́чеником красото́ і ра́дованіє.","Ра́дуйся, христия́ном крі́пкоє прибі́жище; ра́дуйся, ві́рним тве́рдоє заступле́ніє.","Ра́дуйся, Варва́ро, неві́сто Христо́ва прекра́сная."]},{"h":"Кондак 11","ps":["Пі́ніє на́ше похва́льноє, а́ще би і тьмочи́сленноє, ві́ми, я́ко ність дово́льно по достоя́нію восхвали́ти тя, свята́я і всехва́льная му́ченице Варва́ро; оба́че ми, Бо́жиїх тобо́ю нам оби́льно подава́ємих дарова́ній благода́рні су́ще, Бо́гу, в тебі́ свої́ми благодія́нії прославля́ємому, благода́рственними усти́ поє́м: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мную свіщу́, на небе́сном сві́щниці, пред престо́лом Святи́я Тро́йці поста́вленную, зрим у́мнима очи́ма тебе́, свята́я ді́во Варва́ро; отону́дуже, єгда́ нощни́й гріхо́в на́ших мрак, луча́ми моли́тв твої́х просвіща́єши, і нас на сві́тлую спасе́нія стезю́ наставля́єши, по до́лгу досто́йна єси́ от нас зва́нієм би́ти почита́єма сим:","Ра́дуйся, світоу́мная луче́, во сві́тлость немерца́ющую прилуче́нная; ра́дуйся, ми́сленная денни́це, день невече́рній озаря́ти возше́дшая.","Ра́дуйся, благово́нная сми́рно, Це́рков Христо́ву благоуха́ющая; ра́дуйся, злата́я кади́льнице, фиміа́м моли́тви о нас к Бо́гу принося́щая.","Ра́дуйся, мирополо́жнице ісціле́ній неоску́дная; ра́дуйся, сокро́вище Бо́жиїх даро́в неіждиви́тельноє.","Ра́дуйся, ча́ше, от оби́лія до́му Бо́жия че́рплющая ра́дость; ра́дуйся, сосу́де, от ісполне́нія Христо́ва приє́млющий всіх благ Небе́сних сла́дость.","Ра́дуйся, адама́нте, пе́рстень безсме́ртнаго со Христо́м обруче́нія, украси́вий; ра́дуйся, ві́нче добро́ти, в руці́ Госпо́дній держи́мий.","Ра́дуйся, я́ко на тя Цар Сла́ви, Госпо́дь Сил, сла́ву і велелі́піє возложи́л єсть; ра́дуйся, я́ко тебі́ Цар ца́рствующих і Госпо́дь госпо́дствующих Ца́рство своє́ і Госпо́дствіє дарова́л єсть.","Ра́дуйся, Варва́ро, неві́сто Христо́ва прекра́сная."]},{"h":"Кондак 12","ps":["Благода́ть от Бо́га дана́ ті єсть храни́ти і соблюда́ти от внеза́пния болі́зні і на́глия сме́рти вся́каго челові́ка, ві́рою, любо́вію і благогове́нієм чеcтна́я твоя́ страда́нія воспомина́ющаго і почита́ющаго; тоя́ благода́ті не лиши́ і нас, до́брая ді́во Варва́ро, да і ми, здра́ві су́ще ті́лом і ду́хом в ни́нішней і бу́дущей жи́зні о тебі́ поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Поє́м твоя́ крі́пкия по́двиги, почита́єм страда́нія, хва́лим долготерпі́ніє, ублажа́єм святу́ю твою́ кончи́ну, сла́вим твоє́ в немощно́м ті́лі показа́вшеєся непобіди́моє му́жество, і́мже на землі́ і на Небесі́ просла́вилася єси́, свята́я і добропобі́дная великому́ченице Варва́ро, і в честь твої́х побідоно́сних по́двигов і страда́ній похва́льная воспису́єм ті сія́:","Ра́дуйся, от а́нгельських чино́в в сожи́тельство їх любе́зно прия́тая; ра́дуйся, от ді́вственних лико́в в черто́г Небе́сний ра́достно введе́нная.","Ра́дуйся, от му́ченичеських полко́в под віне́ць сла́ви провожда́ємая во гла́сі ра́дованія; ра́дуйся, от всіх жи́телей небе́сних приє́мшая о Го́споді цілова́ніє.","Ра́дуйся, я́ко мзда твоя́ мно́га єсть на Небесі́х; ра́дуйся, я́ко ра́дость твоя́ ві́чна єсть во сві́тлості святи́х.","Ра́дуйся, от враг ви́димих і неви́димих крі́пкая нам засту́пнице; ра́дуйся, ра́дости нам, благода́ті же і сла́ви ві́чния хода́тайце.","Ра́дуйся, душе́вних і тіле́сних неду́гов на́ших ціли́тельнице; ра́дуйся, спаси́тельних благ земни́х і Небе́сних пода́тельнице.","Ра́дуйся, я́ко тобо́ю от неча́янния і ві́чния сме́рти сохране́ні би́ти упова́єм; ра́дуйся, я́ко тобо́ю ві́чную жизнь улучи́ти благонаде́жно ча́єм.","Ра́дуйся, Варва́ро, неві́сто Христо́ва прекра́сная."]},{"h":"Кондак 13","ps":["О многострада́льная і всехва́льная свята́я великому́ченице Варва́ро, ни́нішнєє на́ше моле́ніє приє́мши, от вся́ких болі́зней душе́вних і тіле́сних і враг ви́димих і неви́димих нас ізба́ви, і от ві́чнаго муче́нія твої́м Богоприя́тним хода́тайством сохрани́, да с тобо́ю на землі́ живи́х во ві́ки поє́м Бо́гу: Аллилу́я.","Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов честну́ю і вселюбе́зную чистоту́ непоро́чно сохра́нши, честна́я Варва́ро, а́нгелом сожи́тельниця би́ти сподо́билася єси́, с ни́миже єгда́ поє́ши Тро́їчеськую піснь Бо́гу на Небесі́, усли́ши нас, пою́щих тебі́ на землі́ похва́льная пі́нія сія́:","Ра́дуйся, отрокови́це, Бо́гом Отце́м предуста́вленная би́ти сообра́зна в страда́нії о́бразу Си́на Єго́; ра́дуйся, Си́ном Бо́жиїм, Сві́том от Сві́та, призва́нная із тьми в чу́дний світ ві́ри і благода́ті Єго́.","Ра́дуйся, я́ко позва́вшему тя Свято́му Ду́ху, і сама́ ті́лом і ду́хом свята́ єси́; ра́дуйся, я́ко от скве́рни пло́ті і ду́ха непоро́чну тя соблюла́ єси́.","Ра́дуйся, рожде́нному от Ді́ви Жениху́ Христу́ ді́ву тя чи́стую обручи́вшая; ра́дуйся, земна́го обру́чника па́че Небе́снаго зна́ти не восхоті́вшая.","Ра́дуйся, кри́не ді́вства, посреді́ те́рнія і́дольськаго прора́стший до́лі; ра́дуйся, цві́те чистоти́, в неув'яда́ємой сла́ві цвіту́щий горі́.","Ра́дуйся, в небе́сном вертогра́ді Христо́ва благоуха́нія наслажда́ющаяся; ра́дуйся, красні́йшаго па́че сино́в челові́чеських зрі́нієм та́мо утіша́ющаяся.","Ра́дуйся, убіли́вшая ри́зи твоя́ в Кро́ві А́гнчей на землі́; ра́дуйся, в ли́ці ді́вственном послі́дующая Бо́жиєму А́гнцю на Небесі́.","Ра́дуйся, Варва́ро, неві́сто Христо́ва прекра́сная."]},{"h":"Кондак 1","ps":["Ізбра́нной Бо́гом от ідолослужи́тельнаго ро́да і призва́нной во язи́к свят, в лю́ди обновле́нія, неві́сті Христо́ві, я́ко ізбавля́ющіїся тобо́ю от разли́чних зол і обстоя́нія, благода́рственная пі́нія і хвале́нія воспису́єм ті моли́твенници твої́, свята́я і всехва́льная великому́ченице, ти же іму́щи дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, да с ра́достію зове́м ті:","Ра́дуйся, Варва́ро, неві́сто Христо́ва прекра́сная."]},{"h":"Молитва до святої великомучениці Варвари","ps":["Свята́я сла́вная і всехва́льная великому́ченице Христо́ва Варва́ро, со́браннії днесь в хра́мі твоє́м Бо́же́ственнім лю́ди і ра́ці моще́й твої́х покланя́ющіїся, і любо́вію цілу́ющії; страда́нія же твоя́ му́ченичеськая, і в них Сама́го Стра́стополо́жника Христа́, да́вшаго тебі́, не то́чію є́же в Него́ ві́ровати, но і є́же по Нем страда́ти, похвала́ми ублажа́ющії, мо́лим тя, ізві́стная жела́нія на́шего хода́тайце: моли́ с на́ми і о нас умоля́ємаго от своєго́ благоутро́бія Бо́га, да ми́лостивно усли́шить нас, прося́щих Єго́ благости́ню, і не отста́вить от нас вся ко спасе́нію і житію́ ну́ждная проше́нія, і да́руєть христия́нськую кончи́ну животу́ на́шему безболі́зненну, непости́дну, ми́рну, Боже́ственних Та́їн прича́стну, і всім на вся́ком мі́сті, во вся́кой ско́рбі і обстоя́нії тре́бующим Єго́ человіколю́бія і по́мощі, вели́кую Свою́ пода́сть ми́лость. Да благода́тію Божиєю, і твої́м те́плим предста́тельством, душе́ю і ті́лом всегда́ здра́ві пребива́юще, сла́вим ди́внаго во святи́х Свої́х Бо́га Ізра́їлева, не удаля́ющаго по́мощі Своєя́ от нас всегда́, ни́ні, і при́сно, і во ві́ки віко́в, амі́нь."]},{"h":"Молитва друга до святої великомучениці Варвари","ps":["Прему́драя і всекра́сная свята́я великому́ченице Христо́ва Варва́ро, блаже́нна єси́, я́ко преми́рная⁽2⁾ му́дрости Бо́жия плоть і кров не яви́ тебі́, но Сам Бог Оте́ць Небе́сний, І́же тебе́ ві́ри ра́ди от неві́рнаго отця́ оста́вленную, ізгна́нную і умерщвле́нную, в дщер себі́ возлю́бленную прия́т; за тлі́нноє земна́го імі́нія наслі́діє, пло́ті нетлі́ніє дарова́; труди́ му́ченичеськія упокоє́нієм Небе́снаго ізміни́ Ца́рствія; вре́менноє твоє́ житіє́, сме́ртію єго́ ра́ди пресіче́нноє, сицево́ю возпросла́ви по́честію, я́ко ду́шу с ли́ки Небе́сних вчини́ духо́в, ті́ло же на землі́ в хра́мі їх а́нгельськом положе́нноє, а́нгелом запові́да сохрани́ти ці́ло, че́cтно і многочуде́сно. Блаже́нна єси́ Христу́, Си́ну Бо́жию, Жениху́ Небе́сному, уневіще́нная ді́во, Єго́же, добро́ти твоєя́ рачи́теля імі́ти жела́ющи, всю себе́ страда́нієм, ра́нами, у́дов рі́занієм і са́мия глави́ усіче́нієм, а́ки у́тварми дража́йшими потща́лася єси́ украси́ти; да та́ко, я́ко жена́ ві́рна главі́ своє́й, му́жу Христу́, ду́хом і ті́лом соєдини́шися неразлу́чно, глаго́лющи: обріто́х, Єго́же возлюби́ душа́ моя́, і удіржа́х Єго́, і не оста́вих Єго́. Блаже́нна єси́, я́ко Святи́й Дух на тебі́ почи́л єсть, І́мже духо́вними духо́вная разсужда́ти науче́на, вся ду́хи лука́вствія во і́долах, я́ко па́губния отри́нула єси́, і Єди́наго Бо́га Ду́ха позна́вши, я́ко і́стинная покло́нниця ду́хом і і́стиною кла́нятися ізво́лила єси́, пропові́дничеськи глаго́лющи: Тро́йцю чту, Єди́но Бо́жество́. Сію́ святу́ю Тро́йцю, Ю́же в животі́ і сме́рті іспові́данієм і страда́нієм свої́м просла́вила єси́, умоли́ о мні, предста́тельнице моя́, я́ко да і аз всегда́ тро́йственною, ві́ри, любве́ і наде́жди, Ту́южде Святу́ю Тро́йцю почита́ю доброді́телію. І́мам світи́льник ві́ри, но пра́зден благи́х діл єле́я; ти, му́драя ді́во, страда́льчеськую плоть твою́ кро́ве іспо́лненну, і ра́нами прелива́ющуся а́ки світи́льник іму́щая, даждь от єле́я твоєго́, да тім душе́вную мою́ свіщу́ украси́вши, сподо́блюся по тебі́ вни́ти в черто́г Небе́сний. Пресе́льник аз єсьм на землі́ і пришле́ць, я́коже всі отці́ мої́; благ ві́чних наслі́днице, і блаже́нная, обі́да в Ца́рствії Небе́сном прича́стнице, я́ко в стра́нствії житія́, трапе́зи Бо́же́ственния угоще́нія, си́це і во ісхо́ді от ми́ра, жела́ємаго сподо́би м'я напу́тствованія; і єгда́ в коне́ць сном сме́рти начну́ усипа́ти, косни́ся тогда́ ізнемога́ющия пло́ті моєя́, я́ко іногда́ а́нгел Ілії́, глаго́лющи: воста́ни, яждь і пий; я́ко да благода́тію Боже́ственних Ті́ла і Кро́ве Та́їн укріпле́н, прейду́ в крі́пості Я́ді Тоя́ дале́кий путь сме́рти, да́же до Гори́ Небе́сния; і та́мо, Єго́же ти чрез три о́кна ба́нния пре́жде ві́рою Бо́га Тро́йцю узрі́ла єси́, Сего́ ку́пно с тобо́ю лице́м к лицю́ да удосто́юся ви́діти і сла́вити Єго́ в несконча́ємия ві́ки, амі́нь."]}],"notes":["посудино","надземна (понад світом)"]},{"u":"Акафіст Різдву Христовому","e":"Akathist to the Nativity of Christ","secs":[{"h":"Кондак 1","ps":["Ізбра́вий от всіх родо́в Пречи́стійшую А́нгел Ді́ву і от нея́ роди́вийся пло́тію, Христе́ Бо́же наш; благода́рственная прино́сим Ті, раби́ Твої́, Влади́ко. Ти же, я́ко імі́яй милосе́рдіє неізрече́нноє, от вся́ких нас бід свободи́, зову́щих:","Ісу́се, Си́не Бо́жий, воплоти́вийся нас ра́ди, сла́ва Тебі́."]},{"h":"Ікос 1","ps":["А́нгел мно́жество собра́ся в Вифлеє́мі ви́діти непости́жноє Рождество́; і, ви́дівше своєго́ Творця́ во я́слех, я́ко младе́нця лежа́ща, удиви́шася! І, стра́хом благогові́юще, Ро́ждшагося і Ро́ждшую боголі́пні почита́ху, пою́ще такова́я:","Сла́ва Тебі́, Си́не Бо́жий, пре́жде вік от Отця́ рожде́нний; сла́ва Тебі́, со Отце́м і Ду́хом вся сотвори́вий.","Сла́ва Тебі́, спасти́ поги́бшія прише́дий; сла́ва Тебі́, да́же до ра́бія зра́ка снизше́дий.","Сла́ва Тебі́, Взиска́телю заблу́ждших; сла́ва Тебі́, Спаси́телю поги́бших.","Сла́ва Тебі́, средості́ніє вражди́ разруши́вшу; сла́ва Тебі́, рай, преслуша́нієм затворе́нний, па́ки отве́рзшу.","Сла́ва Тебі́, род челові́чеський неізрече́нно возлюби́вшу; сла́ва Тебі́, на землі́ верте́п Не́бо яви́вшу.","Сла́ва Тебі́, ро́ждшую Тя Ді́ву, Престо́л херуви́мський, показа́вшу.","Ісу́се, Си́не Бо́жий, воплоти́вийся нас ра́ди, сла́ва Тебі́."]},{"h":"Кондак 2","ps":["Ви́дяще безпло́тнії А́нгели своєго́ Влади́ку, от Чи́стия Ді́ви плоть приє́мша, ужасо́шася! І друг ко дру́гу рі́ша: пресла́вноє сіє́ Та́їнство непостижи́мо нам явля́ється би́ти: оба́че див'я́щеся неізрече́нному того́ снизхожде́нію, со стра́хом поя́ху: Аллилу́я."]},{"h":"Ікос 2","ps":["Разу́мная вся твар ужаса́ющися і, благодаря́щи, поє́ть Твоєго́ Рождества́, Влади́ко, та́їнство. Си́ли небе́сния ра́дуються, пою́ще: сла́ва во ви́шніх Бо́гу, і земля́ с челові́ки весели́ться, ми же непреста́нно вопіє́м:","Сла́ва Тебі́, во ви́шніх сла́вимому Бо́гу; сла́ва Тебі́, мир на землі́ сотвори́вшему.","Сла́ва Тебі́, нас Собо́ю примири́вшему; сла́ва Тебі́, на землі́ нам яви́вшемуся.","Сла́ва Тебі́, от Ді́ви неізрече́нно воплоти́вшемуся; сла́ва Тебі́, звізду́ возсія́вшему.","Сла́ва Тебі́, то́ю волхви́ на поклоне́ніє Тебі́ призва́вшему; сла́ва Тебі́, да́ри от них ми́лостивно прия́вшему.","Сла́ва Тебі́, всю твар Тебі́ служи́ти научи́вшему; сла́ва Тебі́, і нас Тебі́ пі́ти наста́вившему.","Сла́ва Тебі́, Себе́ нам соєдини́вшему; сла́ва Тебі́, нас Собо́ю спа́сшему.","Ісу́се, Си́не Бо́жий, воплоти́вийся нас ра́ди, сла́ва Тебі́."]},{"h":"Кондак 3","ps":["Си́льний в крі́пості Бог ми́ра і Оте́ць щедро́т при́йде на зе́млю спасти́ мир погиба́ющий: ни́ні во Вифлеє́мі, я́ко младе́нець, ражда́ється от Ді́ви: Ю́же Ма́тер і Хода́таїцю спасе́нія показа́, всім Того́ воплоще́ніє сла́в'ящим і пою́щим: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще, Тебе́ пречи́сто ро́ждшую, о нас непреста́нно моля́щуюся: ра́дующеся, поє́м Твоєго́ вочелові́ченія, Влади́ко, Та́їнство! І Рождество́ от Ді́ви Богоприя́тния, славосло́в'яще, вопіє́м:","Сла́ва Тебі́, Си́не Бо́жий, нас ра́ди воплоти́вийся; сла́ва Тебі́, Си́не Ді́ви, от Ді́ви несказа́нно роди́вийся.","Сла́ва Тебі́, человіколю́бія бе́здну на нас показа́вшему; сла́ва Тебі́, нас неізрече́нно возлюби́вшему.","Сла́ва Тебі́, заблу́ждшеє овча́ взиска́вшему; сла́ва Тебі́, об обрі́тенії того́ сра́доватися А́нгелом ре́кшему.","Сла́ва Тебі́, на ра́мо сію́ восприє́мшему; сла́ва Тебі́, ко Отцю́ то́є приве́дшему.","Сла́ва Тебі́, челові́ки со А́нгели во єди́но ста́до совоку́пльшему; сла́ва Тебі́, мир от пре́лести ізба́вльшему.","Сла́ва Тебі́, вели́кую і неізрече́нную ми́лость нам яви́вшему. Сла́ва Тебі́, нас па́че всіх тва́рей просла́вльшему.","Ісу́се, Си́не Бо́жий, воплоти́вийся нас ра́ди, сла́ва Тебі́."]},{"h":"Кондак 4","ps":["Бу́рю внутр помишле́ній сумни́тельних пре́жде імі́вий, цілому́дренний Іо́сиф ни́ні внутр Боже́ственнаго верте́па ви́дить пресла́вния. А́ще бо і я́ко челові́ка ви́дяще от Ді́ви ражда́ємаго, но разуміва́ше от веще́й Бо́га би́ти і́стиннаго: тім і боголі́пні поклони́вся, ра́достно поя́ше: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша па́стиріє А́нгела, возвіща́юща їм ро́ждшагося Спа́са ми́ру, во гра́ді Дави́дові: і, ско́ро те́кше, ви́діша Сего́, я́ко а́гнця, непоро́чна, во чре́ві Ді́вия упа́сшася, во я́слех лежа́ща, і Ро́ждшую благогові́йно служа́щу, і Іо́сифа со стра́хом предстоя́ща; сказа́ша о глаго́ланних к ним, і, поклони́вшеся Ро́ждшемуся, рі́ша:","Сла́ва Тебі́, А́гнче Бо́жий, Спа́се ми́ра; сла́ва Тебі́, Си́не Бо́жий, неізрече́нноє чу́до нам показа́вий.","Сла́ва Тебі́, А́нгельських пі́ній сли́шателі нас би́ти яви́вий; сла́ва Тебі́, с ни́ми і нас славосло́вити Тя научи́вий.","Сла́ва Тебі́, А́нгели і челові́ки пі́ти Тя вразуми́вий; сла́ва Тебі́, на землі́ і на небесі́ ра́дость сотвори́вий.","Сла́ва Тебі́, я́ко о Тебі́ небе́сная сра́дуються земни́м; сла́ва Тебі́, я́ко Тобо́ю земна́я совокупля́ються небе́сним.","Сла́ва Тебі́, крі́пость дия́волю не́мощну показа́вшему; сла́ва Тебі́, от того́ мучи́тельства нас ізба́вльшему.","Сла́ва Тебі́, в Тя ві́рующим неізрече́нная ра́досте; сла́ва Тебі́, лю́б’ящим Тя неізглаго́ланная сла́досте.","Ісу́се, Си́не Бо́жий, воплоти́вийся нас ра́ди, сла́ва Тебі́."]},{"h":"Кондак 5","ps":["Боготе́чную звізду́, Христо́во Рождество́ пред’явля́ющую, узрі́вше звіздоблюсти́телі волсви́; і тоя́ вожде́нієм Непостижи́маго достиго́ша і Неви́димаго ви́діша, возра́довашася же, Тому́ вопію́ще: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще ца́ріє перси́дстії, на руку́ Діви́чу, Царя́ ца́рствующих, я́ко на престо́лі херуви́мстім сідя́ща, і Влади́ку того́ разуміва́юще, а́ще ра́бій прия́т зрак, потща́шася да́ри Єму́ принести́: зла́то, я́ко Царю́ всіх, лива́н же, я́ко Бо́гу, сми́рну, я́ко Безсме́ртному, і, поклони́вшеся, поя́ху:","Сла́ва Тебі́, Світ всім возсія́вий; сла́ва Тебі́, нас звіздо́ю на поклоне́ніє Тебі́ призва́вий.","Сла́ва Тебі́, зло́бу лю́таго І́рода обличи́вшему; сла́ва Тебі́, су́єтно того́ умишле́ніє показа́вшему.","Сла́ва Тебі́, нас от того́ пре́лести ізба́вльшему; сла́ва Тебі́, покланя́тися Тебі́, Со́лнцю пра́вди, научи́вшему.","Сла́ва Тебі́, вся сві́том ра́зума просвіти́вшему; сла́ва Тебі́, Твої́м Рождество́м многобо́жия пре́лесть упраздни́вшему.","Сла́ва Тебі́, вра́жиє влади́чество до конця́ низложи́вшему; сла́ва Тебі́, со Отце́м і Ду́хом Тебі́ покланя́тися нас научи́вшему.","Сла́ва Тебі́, прельсти́вшаго нас змі́я главу́ сокруши́вшему; сла́ва Тебі́, от ві́чния сме́рти нас ізба́вльшему.","Ісу́се, Си́не Бо́жий, воплоти́вийся нас ра́ди, сла́ва Тебі́."]},{"h":"Кондак 6","ps":["Пропові́дник богоно́сних віща́нія, я́же от Тебі́ ісполня́я, на землі́ яви́л єси́ Себе́, Спа́се, во убо́зім ни́ні верте́пі, ро́ждся от Чи́стия Ді́ви: і, бога́т сий, нас ра́ди обнища́л єси́ во́лею, да челові́ки обогати́ши, ві́рою Тебі́ пою́щия: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ от Ді́ви і неіскусому́жния Твоєя́ Ма́тере, Ісу́се, я́ко со́лнце, просвіща́я і прогоня́я лжі тьму: де́мони бо, Спа́се, нетерп'я́ще Твоєя́ крі́пости, всі вострепета́ша, і ад, ви́дів чу́до, убоя́ся: ми же, благодаря́ще, вопіє́м Ті:","Сла́ва Тебі́, челові́к Спаси́телю; сла́ва Тебі́, бісо́в Потреби́телю.","Сла́ва Тебі́, пре́лести нача́льника Твої́м Рождество́м устраши́вшему; сла́ва Тебі́, і́дольськую пре́лесть упраздни́вшему.","Сла́ва Тебі́, сві́том Богопозна́нія вся осія́вшему; сла́ва Тебі́, тьму неві́дінія отгна́вшему.","Сла́ва Тебі́, Ка́меню, во́ду спасе́нія всім істочи́вий; сла́ва Тебі́, жа́жду Ада́мову і Дави́дову утоли́вий.","Сла́ва Тебі́, я́ко со́лнцем, Твої́м Рождество́м вся просвіти́вшему; сла́ва Тебі́, лучі́ благода́ті вселе́нній облиста́вшему.","Сла́ва Тебі́, зе́млю обітова́нія нам показа́вшему; сла́ва Тебі́, от всеро́дния кля́тви нас Ізба́вльшему.","Ісу́се, Си́не Бо́жий, воплоти́вийся нас ра́ди, сла́ва Тебі́."]},{"h":"Кондак 7","ps":["Хотя́ от ві́ка сокрове́нную та́йну нам яви́ти, от всея́ тва́рі служи́телі та́їнству показа́л єси́, Спа́се. От А́нгел – Гавриї́ла, от челові́к – Ді́ву, от небе́с – звізду́, от землі́ – верте́п, в не́мже роди́тися благоволи́л єси́: ті́мже, див'я́щеся Твоє́й неізрече́нній прему́дрості, зове́м: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую показа́л єси́ твар, я́влься пло́тію всіх Зижди́тель, із безсі́менния прозя́б утро́би, і, сохрани́в ю, я́коже бі нетлі́нну, і Хода́таїцю спасе́нія показа́л єси́ пою́щим:","Сла́ва Тебі́, Си́не Бо́жий, Тя ро́ждшую Ма́тер милосе́рдія показа́вий; сла́ва Тебі́, Ту́ю і по Рождестві́ Ді́ву сохрани́вий.","Сла́ва Тебі́, спасти́ Ада́ма прише́дшему; сла́ва Тебі́, сле́зи Є́вини утоли́вшему.","Сла́ва Тебі́, вся спасти́ возжела́вшему; сла́ва Тебі́, Воскресе́нія о́браз облиста́вий.","Сла́ва Тебі́, гріхо́в на́ших рукописа́ніє раздра́вшему; сла́ва Тебі́, Собо́ю смире́нія о́браз нам показа́вий.","Сла́ва Тебі́, нас ра́ди обнища́вшему; сла́ва Тебі́, Твоє́ю нището́ю нас обогати́вшему.","Сла́ва Тебі́, оде́ждою спасе́нія нас оді́явшему; сла́ва Тебі́, Твоє́ю любо́вію нас услади́вшему.","Ісу́се, Си́не Бо́жий, воплоти́вийся нас ра́ди, сла́ва Тебі́."]},{"h":"Кондак 8","ps":["Стра́нноє і пресла́вноє Рождество́ Твоє́ ви́дівше, в верте́пі соверша́ющеєся, устрані́мся су́єтнаго ми́ра, ум на Боже́ственная прело́жше. Сего́ бо ра́ди Бог на землі́ яви́ся смире́нний челові́к, да на небеса́ возведе́ть, Тому́ вопію́щия: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь єси́ жела́ніє, весь сла́дость лю́б’ящим Тя, Христе́ Бо́же, і Твоє́ Боже́ственноє снизхожде́ніє сла́в’ящим: от Ді́ви бо Чи́стия ро́ждшся на землі́, нас на Небеса́ возво́диши, пою́щих:","Сла́ва Тебі́, Си́не Бо́жий, на землі́ роди́вийся; сла́ва Тебі́, от Ді́ви неізрече́нно воплоти́вийся.","Сла́ва Тебі́, Себе́ нам показа́вшу; сла́ва Тебі́, нас от Тебе́ дале́че су́щих призва́вшу.","Сла́ва Тебі́, неізрече́нная на́ша Ра́досте; сла́ва Тебі́, серде́ць на́ших Сла́досте.","Сла́ва Тебі́, в Рождестві́ Твоє́м світ спасе́нія возсія́вий; сла́ва Тебі́, сле́зи ра́ди на́шего спасе́нія пролия́вий.","Сла́ва Тебі́, ті́ми пла́мень страсте́й на́ших угаси́вий; сла́ва Тебі́, нас от скве́рни гріхо́вния оми́вий.","Сла́ва Тебі́, преступле́ніє разруши́вшему; сла́ва Тебі́, от тлі́нія нас ізба́вльшему.","Ісу́се, Си́не Бо́жий, воплоти́вийся нас ра́ди, сла́ва Тебі́."]},{"h":"Кондак 9","ps":["Вся́коє разумі́ніє і всяк ум А́нгельський і челові́чеський не постига́єть Твоєго́ непости́жнаго Рождества́ Та́їнства разумі́ти; оба́че, Влади́ко Благи́й, на́шу любо́в і ві́ру прийми́; і спаси́ нас, Тебі́ пою́щих: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я многовіща́нния, я́ко ри́би безгла́сния, ви́дим о Твоє́м воплоще́нії, Влади́ко, недоумі́ють бо глаго́лати, ка́ко Бог сий соверше́н, челові́к соверше́нний яви́ся, і от Ді́ви неіскусобра́чния ка́ко роди́ся; ми же, Та́йни не іспиту́юще, ві́рою єди́ною сла́вим Тя, вопію́ще:","Сла́ва Тебі́, Іпоста́сная Бо́жия Прему́дросте; сла́ва Тебі́, неізглаго́ланная всіх Ра́досте.","Сла́ва Тебі́, любому́дри нему́дрия яви́вий; сла́ва Тебі́, о Тебі́ іспиту́ющих посрами́вий.","Сла́ва Тебі́, вся баснотво́рная плете́нія растерза́вий; сла́ва Тебі́, світ Богові́дінія всім возсія́вий.","Сла́ва Тебі́, му́дрость во Твої́х ді́ліх пролія́вшему; сла́ва Тебі́, мно́гим ра́зум просвіти́вшему.","Сла́ва Тебі́, путь спасе́нія нам показа́вшему; сла́ва Тебі́, неізче́тная бе́здно милосе́рдія.","Сла́ва Тебі́, пучи́но щедро́т і человіколю́бія.","Ісу́се, Си́не Бо́жий, воплоти́вийся нас ра́ди, сла́ва Тебі́."]},{"h":"Кондак 10","ps":["Спасти́ восхоті́в мир погиба́ющий, І́же всіх Украси́тель, от Ді́ви, я́ко младе́нець, ражда́ється, і во я́слех пелена́ми повива́ється, разріша́яй многоплете́нния плени́ці прегріше́ній. І Син сий Бо́жий, Ді́вия Син бива́єть! І вся му́дре устроя́єть, да спасе́ть Тому́ пою́щия: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і столп зло́би богопроти́вния, І́род пребеззако́нний, показа́ся, жизнь всім подаю́щаго уби́ти, богобо́рець, тща́шеся, і незло́бивия младе́нці, я́ко кла́си незрі́ли, мече́м пожина́хуся: ті́мже і ми, зло́бу вся́кую от серде́ць на́ших отри́нувше, нас спасти́ прише́дшаго просла́вим вопію́ще:","Сла́ва Тебі́, І́родово умишле́ніє тще́тно показа́вий; сла́ва Тебі́, от того́ ізбіє́нния младе́нці со А́нгели сопричти́й.","Сла́ва Тебі́, зло́би потреби́телю; сла́ва Тебі́, смире́нія Наста́вниче і сме́ртних Люби́телю.","Сла́ва Тебі́, рог го́рдости сломи́вшему; сла́ва Тебі́, світ пра́вди всім возсія́вшему.","Сла́ва Тебі́, кро́тости і смире́нію всіх собо́ю научи́вшему; сла́ва Тебі́, вся в Твоє́ позна́ніє приве́дшему.","Сла́ва Тебі́, Тя Ро́ждшия утро́бу, Твої́м Рождество́м освяти́вий; сла́ва Тебі́, от па́стирей чу́до і от волхво́в да́ри прия́вий.","Сла́ва Тебі́, і безслове́сния Тебі́ служи́ти научи́вий; сла́ва Тебі́, всю твар освяти́вий.","Ісу́се, Си́не Бо́жий, воплоти́вийся нас ра́ди, сла́ва Тебі́."]},{"h":"Кондак 11","ps":["Пі́ніє вся́коє побіжда́ється, Твоєму́ є́же нас ра́ди воплоще́нію, досто́йно принести́ хотя́щих: ті́мже і нам удо́біє єсть люби́ти молча́ніє, і́бо а́ще і равночи́сленния песка́ морська́го пі́сні прино́сим Ті, Царю́ Пресвяти́й, нічто́же соверша́єм досто́йно: ті́мже со стра́хом пої́м: Аллилу́я."]},{"h":"Ікос 11","ps":["Світ Тя незаходи́мий, су́щії во тьмі і сі́ні сме́ртній сідя́щії, Спа́се наш, узрі́вше от Ді́ви возсія́вша: просвіти́шася огне́м Твоєго́ Божества́; і Тебі́, прему́дрости і сми́сла Пода́телю поя́ху, сицева́я:","Сла́ва Тебі́, Си́не Бо́жий, Сві́те неізрече́нний; сла́ва Тебі́, Со́лнце пра́вди, Твої́м Рождество́м вся просвіти́вий.","Сла́ва Тебі́, многосві́тлоє просвіще́ніє возсія́вшему; сла́ва Тебі́, многотеку́щую благода́ті ріку́ нам істочи́вшему.","Сла́ва Тебі́, жа́ждущих водо́ю спасе́нія бога́тно напої́вшему; сла́ва Тебі́, лю́б’ящим Тя і́го бла́го і бре́м’я Твоє́ легко́ показа́вшему.","Сла́ва Тебі́, от бре́мене гріхо́внаго нас облегчи́вшему; сла́ва Тебі́, нас от рабо́ти вра́жия ізба́вльшему.","Сла́ва Тебі́, Твої́м на землі́ явле́нієм вся возвесели́вий; сла́ва Тебі́, утіша́тися нам наде́ждею пакибитія́ дарова́вий.","Сла́ва Тебі́, нам жела́ній на́ших край Себе́ яви́вий; сла́ва Тебі́, нас, враго́в су́щих, со Отце́м примири́вий.","Ісу́се, Си́не Бо́жий, воплоти́вийся нас ра́ди, сла́ва Тебі́."]},{"h":"Кондак 12","ps":["Благода́ть всім пода́ти і долги́ челові́ков разріши́ти прише́дий, Спа́се наш, Твої́м Воплоще́нієм: тім і на́ша долги́ разріши́ і гріхо́в рукописа́ніє раздери́: Твоє́ несказа́нноє Рождество́ сла́в’ящим і непреста́нно пою́щим: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоє́ вочелові́ченіє, хва́лим, благослови́м і покланя́ємся Тебі́, Спа́се наш; і ві́руєм, я́ко Госпо́дь і Бог єси́, спаса́яй всіх, на Тя упова́ющих, і Твоє́, є́же от Ді́ви неізрече́нноє Рождество́ славосло́в’ящих і пою́щих такова́я:","Сла́ва Тебі́, Си́не Бо́жий, в ви́шніх со Отце́м і Ду́хом покланя́ємий; сла́ва Тебі́, от всіх колі́н небе́сних і земни́х сла́вимий.","Сла́ва Тебі́, сокрове́нноє от ві́ка та́їнство откри́вий; сла́ва Тебі́, Твою́ к нам неізрече́нную любо́в яви́вий.","Сла́ва Тебі́, всея́ тва́рі Украси́телю; сла́ва Тебі́, нам всеми́лостивий Спаси́телю.","Сла́ва Тебі́, благоче́стно ца́рствующих на землі́ скі́петри утвержда́яй; сла́ва Тебі́, святи́телі благогові́йния і ієре́ї прему́дростію і благолі́пієм украша́яй.","Сла́ва Тебі́, Це́ркве основа́ніє і утвержде́ніє; сла́ва Тебі́, всім ві́рним спасе́ніє і украше́ніє.","Сла́ва Тебі́, тіле́с на́ших Врачу́ і Ісціле́ніє; сла́ва Тебі́, душ на́ших Украси́телю і Спаси́телю.","Ісу́се, Си́не Бо́жий, воплоти́вийся нас ра́ди, сла́ва Тебі́."]},{"h":"Кондак 13","ps":["О Пресла́дкий і Всеще́дрий Ісу́се, Спаси́телю наш, Тво́рче і Влади́ко! Прийми́ ни́ні ма́лоє сіє́ моле́бноє благодаре́ніє і славосло́віє на́ше, я́коже прия́л єси́ от волхво́в поклоне́ніє і да́ри; і сохрани́ нас, Твої́х рабо́в, от вся́кия напа́сти, і гріхо́в проще́ніє да́руй; і ві́чния му́ки ізба́ви ві́рно сла́в’ящих Твоє́, от чи́стия Ді́ви, Рождество́, і вопію́щих Ті: Аллилу́я.","§Цей кондак читається тричі, а потім ікос 1 і кондак 1."]},{"h":"Ікос 1","ps":["А́нгел мно́жество собра́ся в Вифлеє́мі ви́діти непости́жноє Рождество́; і, ви́дівше своєго́ Творця́ во я́слех, я́ко младе́нця́ лежа́ща, удиви́шася! І, стра́хом благогові́юще, Ро́ждшагося і Ро́ждшую боголі́пні почита́ху, пою́ще такова́я:","Сла́ва Тебі́, Си́не Бо́жий, пре́жде вік от Отця́ рожде́нний; сла́ва Тебі́, со Отце́м і Ду́хом вся сотвори́вий.","Сла́ва Тебі́, спасти́ поги́бшія прише́дий; сла́ва Тебі́, да́же до ра́бія зра́ка снизше́дий.","Сла́ва Тебі́, Взиска́телю заблу́ждших; сла́ва Тебі́, Спаси́телю поги́бших.","Сла́ва Тебі́, средості́ніє вражди́ разруши́вшу; сла́ва Тебі́, рай, преслуша́нієм затворе́нний, па́ки отве́рзшу.","Сла́ва Тебі́, род челові́чеський неізрече́нно возлюби́вшу; сла́ва Тебі́, на землі́ верте́п Не́бо яви́вшу.","Сла́ва Тебі́, ро́ждшую Тя Ді́ву, Престо́л херуви́мський, показа́вшу.","Ісу́се, Си́не Бо́жий, воплоти́вийся нас ра́ди, сла́ва Тебі́."]},{"h":"Кондак 1","ps":["Ізбра́вий от всіх родо́в Пречи́стійшую А́нгел Ді́ву і от нея́ роди́вийся пло́тію, Христе́ Бо́же наш; благода́рственная прино́сим Ті, раби́ Твої́, Влади́ко. Ти же, я́ко імі́яй милосе́рдіє неізрече́нноє, от вся́ких нас бід свободи́, зову́щих:","Ісу́се, Си́не Бо́жий, воплоти́вийся нас ра́ди, сла́ва Тебі́."]},{"h":"Молитва","ps":["Пребезнача́льноє Нача́ло, Бо́же Святи́й і Ві́чний і всея́ тва́рі Соді́телю! Ки́їми словеси́ возблагодари́м і ки́їми пі́сньми возвели́чим Твоє́ нас ра́ди, челові́к, неізрече́нноє снизхожде́ніє, во́лею Божества́ Своєго́ не отсту́пльше, і недр О́тчих не разлуча́яся, Бог сий, я́ко челові́к, в верте́пі безслове́снім ни́ні положи́лся єси́, Христе́ Бо́же наш! Кто іспові́сть неізглаго́ланнаго сего́ та́їнства вели́чіє і пресла́внаго сбитія́ та́їнство: Син Бо́жий – Син Ді́ви явля́ється, да свободи́ть мир от кля́тви зако́нния, і си́ни гріха́ і беззако́нія – ча́дами Бо́жиїми, наслі́дниками ві́чних благ соді́лаєть, Себе́ же, я́ко же́ртву непоро́чную і всесвяту́ю, в зало́г спасе́нія па́дшаго челові́ка да принесе́ть. Ісу́се Сладча́йший, Влади́ко Всеми́лостивий! Твої́м Пребоже́ственним снизхожде́нієм юдо́ль земна́я в храм Боже́ственния Сла́ви Твоєя́ освяти́ся, і всі, живу́щії на ней, небе́сним весе́лієм іспо́лнишася. Сподо́би у́бо і нас в день пресла́внаго Рождества́ Твоєго́ чи́стим се́рдцем і отве́рстою душе́ю іспові́дати Тя, і́стиннаго А́гнця Бо́жия, услажда́ющаго і укріпля́ющаго нас наде́ждою гряду́щих благ в неме́ркнущім Сві́ті Трисія́тельнаго Божества́, І́мже вся живе́ть і дви́жеться, І́мже обновле́ніє на́шего первообра́знаго битія́ да усоверши́ться. Єй, Го́споди, вся́каго благодія́нія бога́тий Да́телю і Пода́телю Благи́й, за є́же та́ко возлюби́л єси́ мир, я́ко вся ско́рбі і болі́зні на́ша на Себі́ понести́ ізво́лил єси́, не оста́ви нас, до́ндеже суєта́ земна́я скорбми́ і напа́стьми не ізсуши́ла душі́ на́ша, і не поги́бе путь спасе́нія под нога́ма на́шима, да не посмію́ться о нас вразі́ на́ші, но да́руй нам в сві́ті Твоєго́ Боже́ственнаго Открове́нія позна́ти путь ми́ра, добра́ і і́стини, і воззови́ ненаси́тною жа́ждою по Тебі́, Спаси́телі на́шем, во є́же твори́ти во́лю Твою́ преблагу́ю во стра́сі Твоє́м, і в похвалу́ неізрече́нному снизхожде́нію Твоєму́, я́ко кади́ло благово́нноє, приноси́ти Тебі́ житіє́ нескве́рноє і любо́в нелицемі́рную, да в ді́ліх на́ших і во упова́нії ві́ри на́шея непреста́нно соверша́ється во́ля Твоя́ свята́я, і во ві́ки не умо́лкнеть под небесе́м сла́ва Твоя́, сла́ва, я́ко Єдиноро́днаго от Отця́, іспо́лнь благода́ті і і́стини. Я́ко о Тебі́, ни́ні пло́тію от Безневі́стния і Пречи́стия Ді́ви Марі́ї Ро́ждшемся, вся колі́на небе́сная і земна́я, ра́дости ісполня́ющеся, велегла́сно іспові́дують: с на́ми Бог, Єму́же честь і поклоне́ніє подоба́єть – Отцю́, і Си́ну, і Свято́му Ду́ху, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Акафіст Успінню Пресвятої Владичиці нашої Богородиці","e":"Akathist to the Dormition of the Theotokos","secs":[{"h":"Кондак 1","ps":["Ізбра́нной от всіх родо́в Бо́жієй Ма́тері і Цари́ці, восходя́щей от землі́ к небесі́, благогові́йная пі́нія о пречеcтні́м Твоє́м Успе́нії прино́сим, раби́ Твої́, Богоро́дице. Ти же, я́ко іму́щая побі́ду над сме́ртію, от вся́ких нас смертоно́сних бід свободи́, да зове́м Ті:","Ра́дуйся, Обра́дованная, во успе́нії Твоє́м нас не оставля́ющая."]},{"h":"Ікос 1","ps":["А́нгел предста́тель по́слан бисть, рещи́ Богоро́диці ко преми́рним Єя́ возше́ствіє; і прийти́ пред'явля́ше к Ней Си́ну Єя́ і Бо́гу, сві́тло о Ней блиста́яся, і стоя́, зови́й такова́я;","Ра́дуйся, прера́дованная Ма́ти Царе́ва; ра́дуйся, Небе́сная Цари́це, Ма́ти Бо́га і Го́спода Небесе́ і землі́.","Ра́дуйся, предпочте́нная превели́чеством прише́ствія к Тебі́ Си́на Твоєго́ і Бо́га; ра́дуйся, возвели́ченная ізвіще́нієм Твоєго́ к Си́ну отше́ствія.","Ра́дуйся, от всіх родо́в Бо́гом ізбра́нная; ра́дуйся, свято́є Вмісти́лище Сло́ва Бо́жия.","Ра́дуйся, проро́чеськаго прорече́нія Ісполне́ніє; ра́дуйся, Апо́столом пречестни́й Ві́нче.","Ра́дуйся, святи́телєм украше́ніє, і свяще́нником добро́то; ра́дуйся, прави́телєм удобре́ніє і держа́во.","Ра́дуйся, Богому́дрих і́ноков возведе́ніє к го́рнему Ца́рствію; ра́дуйся, отверза́ющая ра́йськия две́рі христия́нському ро́ду, при́сно Тя блажа́щему.","Ра́дуйся, Обра́дованная, во успе́нії Твоє́м нас не оставля́ющая."]},{"h":"Кондак 2","ps":["Ви́дяще апо́столов лик, всеси́льним манове́нієм от коне́ць землі́ на о́блаціх предста́вших ко пречестно́му Твоєму́, Пренепоро́чная, успе́нію, священнонача́льниці, Діони́сій Небе́сний Таї́нник, Ієрофе́й ди́вний і Тимофе́й, с Боголі́пною че́стію свяще́нства, поя́ху Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Разу́мная вся твар, старі́йшая чинонача́лія А́нгельськая, прийдо́ша со свої́м Царе́м, І́же во Своя́ живонача́льнійшия ру́ці ду́шу Ма́тере Своєя́ прия́ть; те́плий же ві́рою Петр со слеза́ми мно́гая к Ней ізрече́, зови́й:","Ра́дуйся, ко преми́рним, Ма́ти Творця́ ми́ру, Восходя́щая; ра́дуйся, к пренебе́сним, Простра́ннійшая небе́с, Взе́млющаяся.","Ра́дуйся, четвероча́стноє стихі́й освяти́вшая Твої́м восхожде́нієм; ра́дуйся, небе́сних возвесели́вшая Твої́м прехожде́нієм.","Ра́дуйся, во Ієрусали́м го́рній прекра́сний Прия́тая; ра́дуйся, в нерукотворе́нния хра́ми прера́достно Вше́дшая.","Ра́дуйся, херуви́мов і серафи́мов Цари́це; ра́дуйся, арха́нгелов і а́нгелов Влади́чице.","Ра́дуйся, Прибі́жище ві́рним, і Ізбавле́ніє; ра́дуйся, достоя́нію Твоєму́ По́мощ і Защище́ніє.","Ра́дуйся, о всем ми́рі христия́нстім к Бо́гу Хода́тайце; ра́дуйся, благ вся́чеських Всеблага́я Пода́тельнице.","Ра́дуйся, Обра́дованная, во успе́нії Твоє́м нас не оставля́ющая."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго восхи́ти от Інді́ї Фому́, за ні́коє ізволе́ніє Бо́жиє не прилу́чшуся єму́ в пречестно́є успе́ніє Богома́тере, і предпоста́ви живоприє́мному Єя́ гро́бу, І́же Преста́вльшуюся прини́к ви́діти, уразумі́ Вознесе́нную на Небеса́ с ті́лом, і ві́ровав о сем, возопи́: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я в себі́ помишле́ніє учени́к, я́ко Бо́жиїм смотре́нієм бі єму́, не обрісти́ся ко провожде́нію Богома́тере с про́чими вку́пі, обра́дован бив о безсме́ртнім Єя́ успе́нії, сія́ вопія́ше к Ней:","Ра́дуйся, Восприє́млемая от землі́ дла́ньма Си́на Твоєго́; ра́дуйся, ко преви́шнім Возше́дшая наслажда́тися сла́ви Єго́.","Ра́дуйся, Провожда́ємая от всіх чинонача́лій а́нгельських в го́рняя; ра́дуйся, Под'ємлемая Херуви́ми в Небе́сная і Наднебеcная.","Ра́дуйся, в Небе́сних враті́х от старі́йших сил велелі́пно пі́сньми Возноси́мая; ра́дуйся, от всіх небе́сних гра́ждан Окружа́ємая і Блажи́мая.","Ра́дуйся, Не́бо Земно́є, к го́рнему селе́нію Возви́шенноє; ра́дуйся, Престо́ле Госпо́день, от землі́ Вознесе́нний в Ца́рствіє Небе́сноє.","Ра́дуйся, Предста́тельство на́ше і крі́пкоє Заступле́ніє; ра́дуйся, грі́шником Спору́чнице во спасе́ніє.","Ра́дуйся, христия́ном Цари́це, і по Бо́зі Наде́ждо Небе́снаго Ца́рствія; ра́дуйся, Ма́ти Живота́, і по Го́споді нам Упова́ніє жи́зні ві́чния.","Ра́дуйся, Обра́дованная, во успе́нії Твоє́м нас не оставля́ющая."]},{"h":"Кондак 4","ps":["Бу́рю внутр імі́я помишле́ній неві́рних євре́їн Аффо́ній, і зря богоно́сними апо́столи Богома́тере Пречестно́є Ті́ло всечестні ко гро́бу несе́нноє, ко опроверже́нію устреми́ся; внеза́пу же, єгда́ со осліпле́нієм о́чію, ру́ці єго́ от'я́ті ко одру́ приліпле́ні ви́сясті, ві́рою Ма́тер Бо́жию іспові́даше, вопія́ Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше таїнниці і самови́дці Сло́ва А́нгелов пою́щих преви́шними пі́сньми, при погребе́нії Богоприя́тнаго Ті́ла Бо́жия Ма́тере, і честь пода́ти хотя́ще Богоуго́дную, потща́шася согла́сно пі́ти, глаго́люще:","Ра́дуйся, благові́стіє Приє́мшая о преше́ствії Твоє́м в го́рнеє Ца́рствіє; ра́дуйся, от благовісти́вшаго Гавриї́ла Приє́мшая ра́достнаго рая́ вра́віє.","Ра́дуйся, пречестно́є херуві́мськоє мно́жество Просвіти́вшая; ра́дуйся, пресла́вноє серафі́мськоє єстество́ Возра́довавшая.","Ра́дуйся, от патріа́рхов Прообразова́нная; ра́дуйся, от проро́ков Предвозвіще́нная.","Ра́дуйся, злу́ю де́рзость іуде́єву ско́ро Отмсти́вшая; ра́дуйся, ісціле́ніє тому́жде Пода́вшая.","Ра́дуйся, Обрати́вшая в ві́ру аффо́нієво неві́ріє; ра́дуйся, ві́рноє того́ Приє́мшая іспові́даніє.","Ра́дуйся, Возводя́щая к Небесі́, любо́в і ві́ру к Тебі́ іму́щих; ра́дуйся, Спаса́ющая ві́рою і́м'я Твоє́ призива́ющих.","Ра́дуйся, Обра́дованная, во успе́нії Твоє́м нас не оставля́ющая."]},{"h":"Кондак 5","ps":["Боготе́чния зві́зди, апо́столи святі́ї, в поднебе́сній разсі́яннії ра́ди Єва́нгелія, восхище́ні би́ша на о́блаціх, по широті́ возду́шній, ко погребе́нію Ма́тере Госпо́дні: Ю́же пі́ньми і пі́сньми провожда́юще, с невеще́ственними взива́ху: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше Богови́дці своєго́ Влади́ку, в ру́ці Ма́тере Своєя́ ду́шу приє́мша, і Го́спода Того́ разумі́вше, потща́шася священносло́вія пі́сньми благосло́вні воспі́ти Ю:","Ра́дуйся, Цари́це, над всі́ми Ца́рствующаго Носи́вшая; ра́дуйся, і Сама́ рука́ма Єго́ Си́но́внима носи́мая.","Ра́дуйся, Ски́птре Царський в Христо́вой десни́ці; ра́дуйся, в руці́ Но́я, Ві́тве Голуби́ці.","Ра́дуйся, Же́зле Ааро́нов, Прозя́бший нетлі́ніє; ра́дуйся, Кри́не Неув'яда́ємий, Процві́тшій безсме́ртіє.","Ра́дуйся, Богоотця́ Дави́да Цівни́це Богодохнове́нная; ра́дуйся, проро́чествія Єго́ Воста́вшая Сла́во, Псалти́рю і Гу́слі Прекра́сния.","Ра́дуйся, Одушевле́нний святи́ні Госпо́дні Киво́те; ра́дуйся, в поко́й Госпо́день Воскре́сший Наш Животе́.","Ра́дуйся, Ски́ніє, от херуви́мов Осіня́ємая; ра́дуйся, Свята́я Святи́х, от серафи́мов Глаго́лемая.","Ра́дуйся, Обра́дованная, во успе́нії Твоє́м нас не оставля́ющая."]},{"h":"Кондак 6","ps":["Пропові́дници Богоно́снії апо́столи, по отше́ствії ко преми́рним Бо́жия Ма́тере, во о́бщем сіді́нії оби́чния трапе́зи би́вше, і Предложе́ніє ча́сті Хлі́ба, во і́м'я Госпо́днє вознося́ще, внеза́пу сви́ше Богоро́дицю Цари́цю прише́дшую со світоно́сними а́нгели зря́ху, і мир тім от Си́на і Бо́га Пода́вшую сли́шавше, возгласи́ша о сем: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ нам Со́лнце Пра́вди Христо́с Бог, от Твої́х Пречи́стих ложе́сн во́лею, і благоразу́мієм пропові́данія чрез апо́столи мир просвіти́, і Тя Богома́тер от ро́да і в род просла́ви. Ті́мже і ми всі ублажа́єм Тя, вопію́ще Ті:","Ра́дуйся, Присноблаже́нная от всіх родо́в во ві́ки; ра́дуйся, Благоутро́бная і Ми́лостивая на челові́ки.","Ра́дуйся, учени́ческому ли́ку обіща́ніє Іспо́лнившая; ра́дуйся, присіще́нієм Твої́м от Си́на Твоєго́ і Бо́га, мир тому́ Пода́вшая.","Ра́дуйся, Всежела́тельноє святи́х Сла́дкоє Зрі́ніє; ра́дуйся, преподо́бних ма́терей і дів святи́х Всевеселя́щеє Ра́дованіє.","Ра́дуйся, Преходя́щая ра́йськоє селе́ніє пра́ведних; ра́дуйся, Посіща́ющая всіх во сла́ві небе́сній су́щих.","Ра́дуйся, Нача́ло челові́чеськаго спасе́нія; ра́дуйся, Ісполне́ніє всіх благи́х жела́нія.","Ра́дуйся, по Бо́зі Царі́ ца́рствующих Богоро́дице Цари́це; ра́дуйся, по Го́споді госпо́дствующих, Влади́ці на́шем, Госпоже́ і Влади́чице.","Ра́дуйся, Обра́дованная, во успе́нії Твоє́м нас не оставля́ющая."]},{"h":"Кондак 7","ps":["Хотя́щих всіх с ві́рою входи́ти в храм Твой Святи́й, Богоро́дице, при́сно спаса́єши, і сла́в’ящих Тя, от вся́ких напа́стей і бід свобожда́єши; Ті́мже і правосла́вним христия́ном, присноблажа́щим Тя, побі́ди на сопроти́вния да́руй і вся ко спасе́нію проше́нія нам подава́й, о сем моля́щимся Тебі́, і пою́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую показа́ твар, я́влься нам всіх Творе́ць Госпо́дь Тобо́ю, Богоро́дице. Ти же сро́дноє промишле́ніє о нас к Нему́ іму́щи, Честні почита́ющих пречестно́є Твоє́ успе́ніє, прийми́ сицева́я Тебі́ вопію́щих:","Ра́дуйся, Ма́ти Бо́гу Ізбра́нная от земни́х; ра́дуйся, Преви́шшая земни́х і небе́сних.","Ра́дуйся, херуви́мов і серафи́мов горі́ Превозше́дшая; ра́дуйся, лик учени́ческий о́блаком ко погребе́нію Ті до́лі Совоку́пльшая.","Ра́дуйся, Фому́ по погребе́нії Твоє́м си́лою Божиєю предпоста́вившая ізря́дніє; ра́дуйся, чрез Него́ уві́рившая Твоє́ на не́бо с пло́тію преселе́ніє.","Ра́дуйся, красото́ю всіх доброді́телей Укра́шенная; ра́дуйся, красні́йшему па́че сино́в челові́чеських Си́нові своєму́ Сопричте́нная.","Ра́дуйся, я́ко фі́нікс пло́тію воскре́сшею Процві́тшая; ра́дуйся, я́ко кедр в Лива́ні небе́сном Умно́жившаяся.","Ра́дуйся, Дре́во Живота́ насажде́нноє посреді́ рая́ преви́шняго; ра́дуйся, Ковче́же ми́сленний, Возви́шенний в го́рняя от пото́па сме́ртнаго.","Ра́дуйся, Обра́дованная, во успе́нії Твоє́м нас не оставля́ющая."]},{"h":"Кондак 8","ps":["Стра́нно в преви́шних ві́дуще Тя ізбра́нная, я́ко Со́лнце, Влади́чице, внутр пренебеcних недоми́слимих красо́т і неізрече́нних добро́т, уми́льно к Си́ну і Бо́гу дла́ньма Єго́ Держи́му Возше́дшую, і прера́достно Прекло́ншуюся живонача́льній Єго́ десни́ці, о сем ви́ну вопіє́м: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся би́вши горі́ к небе́сним взята́, і земни́х не оставля́я, Богома́ти, рука́ма Си́но́внима Носи́ма, в незаходи́мая вни́де, во о́ний град всесвітя́щий і прекра́сний Ієрусали́м Ви́шній, херуви́ми Обстої́ма, со всі́ми небе́сними си́лами, іді́же сли́шить пою́щих сія́;","Ра́дуйся, Єя́же Пресвята́я душа́ в ви́шнем всесві́тлом Сіо́ні вселя́ється; ра́дуйся, Єя́же і нетлі́нноє ті́ло та́можде с душе́ю ку́пно прославля́ється.","Ра́дуйся, Вше́дшая в престо́льний град Самаго́ Вседержи́теля; ра́дуйся, Возне́сшаяся в прекра́сний рай Ви́шняго Насади́теля.","Ра́дуйся, Пренесе́нная во Град основа́нний от ка́меней всесвітя́щих; ра́дуйся, Введе́нная во огра́ду обстої́мую во́ї сил преви́шних.","Ра́дуйся, преви́шше небе́с во благолі́піє Бо́жиє Взя́тая; ра́дуйся, па́че всіх невеще́ственних умо́в Почте́ная.","Ра́дуйся, принося́щая к Си́ну Своєму́ і Бо́гу моле́ніє ві́рних; ра́дуйся, і Сама́ непреста́нно у Престо́ла Си́на Твоєго́ і Бо́га моля́щаяся о всіх.","Ра́дуйся, Предста́тельнице к Бо́гу мир спаса́ющая; ра́дуйся, Засту́пнице ро́ду христия́нському от Бо́га дарова́нная.","Ра́дуйся, Обра́дованная, во успе́нії Твоє́м нас не оставля́ющая."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє превозно́сить Тя, Богоро́дице, челові́честії же ро́ди всі Ма́тер Тя Бо́жию сла́вим, і почита́єм пречестно́є Твоє́ успе́ніє, Цари́це; Тебе́ бо ра́ди земні́ї небе́сним совокупля́ються, согла́сно пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Віти́йства Боговіща́нних проро́ческих рече́ній, ни́ні зрим о Тебі́ сби́вшаяся Богоро́дице, я́ко воі́стину Бо́га пло́тію родила́ єси́ нам. Ті́мже та́їнству словесе́ Бо́жия ві́рующе, вопіє́м:","Ра́дуйся, Зако́на і проро́ков Глави́зно Соверше́нная; ра́дуйся, Звіздо́ Іа́ковля, Валаа́мом Пророкова́нная.","Ра́дуйся, О́дре Царя́ вели́каго, Віща́нний Соломо́ном; ра́дуйся, Руно́ Ороше́нноє Ісу́сом, Образова́нноє Гедео́ном.","Ра́дуйся, Неопали́мая Купино́, законополо́жником Предзри́мая; ра́дуйся, Горо́ Свята́я, му́жем жела́нія усмотре́нная.","Ра́дуйся, Лі́ствице Небе́сная, Іа́ковом предви́димая; ра́дуйся, Две́ре Непроходи́мая, Єзеки́їлем Предзри́мая.","Ра́дуйся, Со́лнце селе́нія Христо́ва, псалмопі́вцем Пред'явле́нноє; ра́дуйся, Та́їнство, многообра́зні проро́ки Пронарече́нноє.","Ра́дуйся, проро́чеських глаго́л всіх предрече́нних о Тебі́, коне́ць Прине́сшая; ра́дуйся, Ви́шняго смотре́нія вся за спасе́ніє ми́ра Соверши́вшая.","Ра́дуйся, Обра́дованная, во успе́нії Твоє́м нас не оставля́ющая."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ мир, І́же всіх Госпо́дь, от земна́го Тя ро́да ізбра́ в Ма́тер Себі́, і нас ді́ля бив челові́к, взи́де, отню́дуже сни́де, к Небесі́ от землі́, і Тебе́ с Собо́ю возведе́ ко пребива́нію во сла́ві ві́чній, і соца́рствованію с Собо́ю конця́ не іму́щему. Ті́мже я́ко Бог сли́шить от всіх: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ ві́рним, Богоро́дице Ді́во, і Заступле́ніє всім к Тебі́ прибіга́ющим; і́бо небесе́ і землі́ Творе́ць от Тебе́ пло́тію проше́д, Пречи́стая, ду́хом і ті́лом в небе́сная Тя пресели́ ко ближа́йшему предста́тельству о всіх, ї́хже приглаша́ти научи́:","Ра́дуйся, Гра́де Царя́ Вели́каго верху́ гори́ небе́сния; ра́дуйся, Стіно́ і Покро́ве, не Кри́ющийся от на́шего притека́нія.","Ра́дуйся, ві́рним царе́м на враги́ Посо́бствующая; ра́дуйся, наше́ствія ага́рянськая Побіжда́ющая.","Ра́дуйся, ві́ри благочести́вия Недви́жимоє Сохране́ніє; ра́дуйся, єрети́чествующих полко́в Разоре́ніє.","Ра́дуйся, Ра́дость і Умире́ніє ми́ру Су́щая; ра́дуйся, всегуби́тельнаго а́да Попра́вшая.","Ра́дуйся, во́їнствующих на плоть цілому́дрієм, Ізря́дноє Вінча́ніє; ра́дуйся, му́ченичеських по́двигов всечестно́є Прославле́ніє.","Ра́дуйся, преподо́бних трудо́м Хода́тайце блаже́ннаго упокоє́нія; ра́дуйся, і́ноком благоскорб'я́щим Пода́тельнице ві́чнаго ра́дованія.","Ра́дуйся, Обра́дованная, во успе́нії Твоє́м нас не оставля́ющая."]},{"h":"Кондак 11","ps":["Пі́ніє вся́коє Богодухнове́нних пі́сней, не довлі́єть от нас к похвалі́ всечи́стна́го успе́нія Твоєго́, Всехва́льная Влади́чице, Цари́це, Богоро́дице; но усе́рдно Тебі́ прино́сим, я́ко Ма́тері Царя́ всіх, смире́нноє моле́ніє на́ше, с небе́сними чи́ньми пою́ще Єди́ному досто́йно Прославля́ющему Тя Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мная Свіща́ І́стиннаго Сві́та, су́щим нам на землі́ я́вльшися, ду́ші просвіща́єши, і чту́щих Твоє́ всечестно́є преставле́ніє к ра́зуму Бо́же́ственному наставля́єши, да поє́м Ті сицева́я;","Ра́дуйся, Свіще́ Неугаси́мая огня́ невеще́ственнаго; ра́дуйся, Заре́ Незаходи́мая Сві́та невече́рняго.","Ра́дуйся, луно́ от Со́лнця пра́вди облистава́ємая; ра́дуйся, Сві́тлосте во тьмі світя́щая.","Ра́дуйся, Світи́льниче на сві́щниці преви́шнем поста́вленний; ра́дуйся, Істо́чниче жи́зні, із гро́ба во світ ізведе́нний.","Ра́дуйся, Ма́ти Сві́та у́мнаго, благочести́вих ду́ші просвіща́ющаго; ра́дуйся, Ма́ти всіх Бо́га, озло́бленних ду́ші утіша́ющаго.","Ра́дуйся, упова́ющим на Тя живота́ коне́ць непости́дний Да́рующая; ра́дуйся, достоя́ніє Бо́жиїм і Свої́м рабо́м, на суді́ Си́на Твоєго́, одесну́ю Єго́ устроя́ющая.","Ра́дуйся, Преблаже́нная, я́ко Тобо́ю блаже́нні єсьми́ і ми, І́же помо́щницю Тя і́мами; ра́дуйся, Преблагоcлове́нная в род і род, я́ко Госпо́дь с Тобо́ю, і Тобо́ю с на́ми.","Ра́дуйся, Обра́дованная, во успе́нії Твоє́м нас не оставля́ющая."]},{"h":"Кондак 12","ps":["Благода́ть високопресто́льния сла́ви, на небе́сі́х дарова́нную Богома́тері, почте́ной сіді́нієм одесну́ю Си́на Єя́ і Бо́га, ви́дяще го́рнії уми́, под'я́ша Ю престо́ли і си́ли, окружи́ша нача́ла і вла́сті, припадо́ша стра́шнії Херуви́ми, Серафи́ми і Госпо́дьства, со Арха́нгели і А́нгели вопію́ще: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще всечестно́є Твоє́ успе́ніє, восхваля́єм всі ко пренебе́сним возше́ствіє Твоє́, Цари́це Богома́ти; Ти же освяти́, просла́ви і спаси́ всіх любо́вію пою́щих Тебі́:","Ра́дуйся, Очи́стившая зе́млю пречи́стими ног Твої́х стопа́ми; ра́дуйся, Освяти́вшая возду́х восхожде́нієм Твої́м к Небесі́.","Ра́дуйся, на небе́сний круг Возступи́вшая; ра́дуйся, вся добро́ти неізрече́нния Зря́щая.","Ра́дуйся, во сла́ві присідя́щая Престо́лу Си́на Твоєго́ і Бо́га; ра́дуйся, с Си́ном і Бо́гом ві́чно Ца́рствующая.","Ра́дуйся, Красото́ в десни́ці Госпо́дній, Украша́ющая блажа́щих Тя всіх небе́сних; ра́дуйся, Обра́довавшая наді́янієм на Тя всіх земни́х.","Ра́дуйся, Облече́нная в со́лнце, Сія́ющая благода́тію і сла́вою всей вселе́нній; ра́дуйся, Обіща́вшая сохраня́ти і спаса́ти призива́ющих Тя всіх в поднебеcній.","Ра́дуйся, от христия́нских родо́в Ма́ти Бо́жия Почита́ємая, і Богоро́диця Імену́ємая; ра́дуйся, от восто́к Со́лнця до за́пад, пресла́вно і правосла́вно от всіх благочести́вих Сла́вимая.","Ра́дуйся, Обра́дованная, во успе́нії Твоє́м нас не оставля́ющая."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти Безсме́ртнаго Царя́ небесе́ і землі́, Христа́ Бо́га на́шего, живу́щая і по сме́рті, ни́нішняя приноше́нія о всечестні́м Твоє́м успе́нії от нас приє́мши, в жи́зні сей і в сме́ртнім успе́нії на́шем, от вся́кия напа́сти, бід і му́ки ізба́ви, і Небе́снаго Ца́рствія нас, Цари́це, сподо́би, о Тебі́ вопію́щих: Аллилу́я."]},{"h":"Молитва","ps":["О Пресвята́я Богоро́дице Ді́во, Влади́чице, ви́шшая а́нгел і арха́нгел і всея́ тва́рі честні́йшая, а́нгельськоє вели́коє Удивле́ніє, проро́чеськая висо́кая Про́повідь, апо́стольськая пресла́вная Похвало́, святи́телей ізря́дноє Украше́ніє, му́чеников крі́пкоє Утвержде́ніє, і́ноков спаси́тельноє Наставле́ніє, по́стников неізнемога́ющеє Воздержа́ніє, ді́вствующих Чистото́ і Сла́во, ма́терей ти́хоє Весе́ліє, младе́нцев Му́дросте і Наказа́ніє, вдови́ць і си́рих Корми́тельнице, наги́х Одія́ніє, боля́щих Здра́віє, плі́нников Ізбавле́ніє, по мо́рю пла́вающих Тишино́, обурева́ємих небу́рноє Приста́нище, блужда́ющих нетру́дная Наста́внице, путеше́ствующих ле́гкоє Прохожде́ніє, тружда́ющихся благо́є Поко́їще, в біда́х су́щих ско́рая Засту́пнице, оби́димих Покро́ве і Прибі́жище, ненаді́ющихся Наді́яніє, тре́бующих Помо́щнице, печа́льних при́сноє Утіше́ніє, ненави́димих любо́вноє Смире́ніє, грі́шников Спасе́ніє і к Бо́гу Присвоє́ніє, правові́рних всіх тве́рдоє Огражде́ніє, непобіди́моє Поможе́ніє і Заступле́ніє! Тобо́ю нам, Влади́чице, Неви́димий Ви́дим бисть, і Тебі́ мольбу́ прино́сим, Госпоже́, грі́шнії раби́ Твої́: о преми́лостивая і пречу́дная Сві́та у́мнаго Цари́це, ро́ждшая Царя́ Христа́, Бо́га на́шего, Живода́вця всіх, от Небе́сних сла́вимая і от земни́х хвали́мая, а́нгельський У́ме, світоза́рная Звіздо́, святи́х пресвяті́йшая, Влади́чице всіх тва́рей, Боголі́пная Діви́це, нескве́рная Неві́сто, Пала́то Ду́ха Пресвята́го, о́гненний Престо́ле Неви́димаго Царя́, небе́сний Киво́те, Носи́ло Сло́ва Бо́жия, огнеобра́зная Колесни́це, Поко́їще Жива́го Бо́га, неізрече́нноє Составле́ніє пло́ті Христо́ви, гніздо́ Орла́ Небе́снаго, Го́рлице Богогла́сная, Голуби́це кро́ткая, ти́хая і незло́бивая, Ма́ти чадолюби́вая, ми́лостей Бе́здно, разверга́ющая ту́чу гні́ва Бо́жия, неізмі́римая Глубино́, неізрече́нная Та́йно, несві́домоє Чу́до, нерукотворе́нная Це́ркве Єди́наго Царя́ всіх вік, благоуха́нноє Кади́ло, честна́я Багряни́це, Боготка́нная Порфи́ро, душе́вний Раю́, живоно́снаго са́да О́трасле, Цві́те прекра́сний, процві́тшій нам небе́сноє весе́ліє, Гро́зде спасе́нія на́шего, Ча́ше Царя́ Небе́снаго, в Не́йже раствори́ся от Ду́ха Свята́го Вино́ неісчерпа́ємия благода́ті, Хода́тайце Зако́на, Зача́ло і́стинния ві́ри Христо́ви, непоколеби́мий Сто́лпе, Мечу́ я́рости Бо́жия на богопроти́вних, бісо́в Устраше́ніє, во бра́нех Побіжде́ніє, христия́н всіх нело́жная Храни́тельнице і ми́ра всего́ ізві́стноє Спасе́ніє! О Всеми́лостивая Госпоже́, Ді́во Влади́чице, Богоро́дице, усли́ши нас, моля́щихся Тебі́, і яви́ ми́лость Твою́ на лю́дех Твої́х, моли́ Си́на Своєго́ ізба́витися нам от вся́каго зла і сохрани́ оби́тель на́шу і вся́ку оби́тель, і град, і страну́ ві́рних, і лю́ди, благоче́стно прибіга́ющия і призива́ющия і́м'я Твоє́ свято́є, от вся́кия напа́сти, губи́тельства, гла́да, тру́са, пото́па, огня́, меча́, наше́ствія іноплеме́нников і междоусо́бния бра́ні, от вся́кия болі́зні і вся́каго обстоя́нія, да ні ра́нами, ні преще́нієм, ні мо́ром, ні вся́ким пра́ведним гні́вом Бо́жиїм ума́ляться раби́ Твої́. Но соблюда́й і спаса́й ми́лостію Своє́ю, Госпоже́, за ни моля́щися, і поле́зноє благорастворе́ніє возду́ха во вре́мені пло́днаго приноше́нія нам да́руй. Облегчи́, возста́ви і поми́луй, преми́лостивая Влади́чице, Богоро́дице препі́тая, во вся́кой біді́ і ну́жді су́щия. Пом'яни́ раби́ Твоя́ і не пре́зри слез і воздиха́нія на́шего, і обнови́ нас бла́гостію Своєя́ ми́лості, да со благодаре́нієм утіша́ємся, обрі́тше Тя Помо́щницю. Умилосе́рдися, Госпоже́ Пречи́стая, на немощни́я лю́ди Твоя́, Наде́ждо на́ша. Разсі́янния собери́, заблу́ждшия на путь Пра́вий наста́ви, отпа́дшия от благочести́вия оте́чеськия ві́ри па́ки возврати́, ста́рость поддержи́, ю́ния вразуми́, младе́нці воспита́й і просла́ви сла́в'ящия Тя, ізря́дніє же, Це́рков Си́на Твоєго́ соблюди́ і сохрани́ в долготу́ дній."]},{"h":"Молитва 2","ps":["О Ми́лостивая і преми́лостивая Цари́це небесе́ і землі́, Богоро́дице Присноді́во! Хода́тайством Твої́м поми́луй вся правосла́вния христия́ни, сохраня́ющи їх под кро́вом ми́лості Твоєя́, ри́зою Твоє́ю честно́ю защити́ і моли́ із Тебі́ вопло́щшагося без сі́мене Христа́, Бо́га на́шего, да препоя́шеть ни сви́ше си́лою на вся ви́димия і неви́димия враги́ на́ша. Спаси́ же і поми́луй, Госпоже́, вели́каго господи́на і отця́ на́шего (ім'я), Блаженнійшаго Митрополита Ки́євськаго і всея́ Украї́ни, преосвяще́нния митрополи́ти, архієпи́скопи і єпи́скопи правосла́вния, ієре́ї же і дия́кони і весь при́чет церко́вний, і весь мона́шеський чин, і вся правові́рния лю́ди, покланя́ющияся і моля́щияся пред честно́ю Твоє́ю іко́ною. При́зри на всіх нас призрі́нієм ми́лостивнаго Твоєго́ заступле́нія, воздви́гни нас із глубини́ гріхо́вния і просвіти́ о́чі серде́чния ко зрі́нію спасе́нія, ми́лостива нам бу́ди зді і на Стра́шнім суді́ Си́на Твоєго́ о нас умоли́, преста́вльшияся во благоче́стії от житія́ сего́ раби́ Твоя́ в ві́чній жи́зні со а́нгели і арха́нгели і со всі́ми святи́ми причти́, да одесну́ю Си́на Твоєго́ Бо́га предста́нуть, і моли́твою Твоє́ю сподо́би вся правосла́вния христия́ни со Христо́м жи́ти і ра́дості а́нгельськия в Небе́сних селе́ніїх наслажда́тися. Ти бо єси́, Госпоже́, Сла́ва Небе́сних і Упова́ніє земни́х, Ти на́ша Наде́жда і Засту́пниця всіх притека́ющих к Тебі́ і Твоєя́ святи́я по́мощі прося́щих. Ти Моле́бниця на́ша те́плая к Си́ну Твоєму́ і Бо́гу на́шему; Твоя́ ма́терняя моли́тва мно́го мо́жеть на умоле́ніє Влади́ки, і Твої́м предста́тельством ко Престо́лу благода́ті Пресвяти́х і Животворя́щих Єго́ та́їн приступа́ти дерза́єм, а́ще і недосто́йнії. Ті́мже всечестни́й о́браз Твой і руко́ю Твоє́ю держи́маго Вседержи́теля ви́дяще на іко́ні, ра́дуємся, грі́шнії, со умиле́нієм припа́дающе, і любо́вію сей цілу́єм, ча́юще, Госпоже́, Твої́ми святи́ми Богоприя́тними моли́твами дойти́ небе́сния безконе́чния жи́зні і непости́дно ста́ти в день су́дний одесну́ю Си́на Твоєго́ і Бо́га на́шего, сла́в’яще Єго́ ку́пно со Безнача́льним Отце́м і Пресвяти́м, Благи́м, Животворя́щим і Єдиносу́щним Ду́хом, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед Її чудотворною іконою «Неопалима Купина»","e":"Akathist to the Theotokos before her icon “The Unburnt Bush”","secs":[{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді, Пречи́стой і Богообра́дованной Ді́ві Богоро́диці, огнезра́чния іко́ни своєя́ явле́нієм обра́довавшей Це́рков Христо́ву і є́ю от о́гненнаго запале́нія защища́ющей ві̑рния, похва́льноє возглаша́єм пі́ніє. Ти же, о Богома́ти, Купино́ Неопали́мая імену́ємая на́ми, я́ко іму́щая держа́ву непобіди́мую і милосе́рдіє мно́гоє, ускори́ на по́мощ к нам, тре́бующим Твоєго́ заступле́нія, і от вся́ких бід свободи́ зову́щих Ті:","Ра́дуйся, Благода́тная, Купино́ Неопали́мая, о́гненнаго запале́нія нас ізбавля́ющая."]},{"h":"Ікос 1","ps":["А́нгелов Цари́це і всея́ тва́рі Влади́чице, Госпоже́ Богоро́дице, от А́нгельських лико́в горі́ приє́млющая хвале́бноє пі́ніє, сподо́би і нас, земни́х і пе́рстних⁽1⁾, возноси́ти к Тебі́ гла́си хвали́ благодаре́нія за премно́гую ми́лость Твою́ к ро́ду челові́чеському. І а́ще недосто́йни єсьми́ пі́ти Тя по достоя́нію, оба́че Ти, я́ко блага́я, не возгнуша́йся на́ших недовлі́ющих похва́л, і я́ко Син Твой дві ле́пті вдови́ці ми́лостивно прия́т, та́ко любоблагоутро́бно усли́ши нас, со умиле́нієм к Тебі́ вопію́щих:","Ра́дуйся, огнь Божества́ во чре́ві Твоє́м неопа́льно носи́вшая; ра́дуйся, Спаси́теля па́дшему челові́честву ро́ждшая.","Ра́дуйся, си́лу а́дову пречеcтни́м Рождество́м Твої́м упраздни́вшая; ра́дуйся, Ада́ма і Є́ву дре́вняго прокля́тія свободи́вшая.","Ра́дуйся, вочелові́ченію Єди́наго от Тро́йці непоро́чно послужи́вшая; ра́дуйся, Творця́ Небесе́ і землі́ безсі́менно воплоти́вшая.","Ра́дуйся, Благода́тная, Купино́ Неопали́мая, о́гненнаго запале́нія нас ізбавля́ющая."]},{"h":"Кондак 2","ps":["Ви́дя Моїсе́й на Сина́ї купину́ огне́м горі́вшую і не сгора́вшую, ужасе́ся, і се бисть глас к нему́ Боже́ственний от купини́: іззу́й сапо́г от ногу́ твоє́ю, мі́сто бо, на не́мже ти стої́ши, земля́ свята́я єсть. Сего́ послу́шая, і ми смире́ннії та́їнство воплоще́нія Бо́га Сло́ва от Пречи́стия Ді́ви, чу́дом Неопали́мия Купини́ прообразова́нноє, іспові́дуєм і со стра́хом покланяємся мі́сту явле́нія Бо́жия, зову́ще Зижди́телю вся́чеських: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум челові́чеський не мо́жеть пости́гнути та́їнство смотре́нія Бо́жия, от сложе́нія ми́ра іскупле́ніє па́дшаго челові́чества предопреділи́вшаго в сові́ті Предві́чнім Триіпоста́снаго Божества́, оба́че Ду́хом Святи́м вдохнове́ннії святі́ї Бо́жії проро́ци іздале́че предзря́ще чу́до чуде́с, я́ко Творе́ць ра́бій зрак восприї́меть, спасти́ хотя́ ді́ло рук Свої́х от поги́белі ві́чния, возвіща́ху проо́брази і проро́честви нело́жними, іму́щеє соверши́тися іскупле́ніє ро́да челові́ча обітова́нним Іскупи́телем. Єму́же Ти, Всечи́стая, плоть взаймода́вши, сподо́билася єси́ би́ти Ма́терію Го́спода Твоєго́, внуша́ющаго нам вопи́ти к Тебі́:","Ра́дуйся, Огнезра́чная Пала́то на херуви́міх Сідя́щаго; ра́дуйся, Світоно́сная Ло́жнице серафи́ми Повеліва́ющаго.","Ра́дуйся, О́дре Царя́ вели́каго верху́ гори́ небе́сния; ра́дуйся, Престо́ле Одушевле́нний Облада́ющаго го́рними і до́льними.","Ра́дуйся, Киво́те Освяще́нний Божества́, Свята́я святи́х бо́льший; ра́дуйся, Ста́мно Всезлата́я, в Не́йже ма́нна спаси́тельная угото́вася Плоть і Кров Боже́ственнаго А́гнця.","Ра́дуйся, Благода́тная, Купино́ Неопали́мая, о́гненнаго запале́нія нас ізбавля́ющая."]},{"h":"Кондак 3","ps":["Си́лою Всеви́шняго ді́йствуя, Влади́чице Преблага́я, си́лу єстества́ о́гненнаго укроща́єши свято́ю іко́ною Твоє́ю і мно́га чудеса́ є́ю содіва́єши во вселе́нній. Ті́мже род христия́нський ублажа́єть Тя гла́си хвале́бними і в біда́х внеза́пних, найпа́че же во вре́м'я о́гненнаго запале́нія к Тебі́ моли́твенно притека́єть, приє́мля по́мощ от Тебе́ благовре́менну. Сего́ ра́ди благода́рственно вопіє́м просла́вльшему Тя Царю́ Сла́ви, Христу́: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я любо́в ве́лію к лю́дем іскупле́нним Чеcтно́ю Кро́вію Си́на Твоєго́ і Бо́га, Богома́ти Пречи́стая, прия́ла єси́ от Него́ власть стро́їти і покрива́ти род христия́нський. Ти бо грі́шником єси́ спору́чниця покая́нія їх пред Творце́м, ненаде́жним Наде́ждо спасе́нія, бі́дствующим По́моще ско́рая, поги́бшим Взиска́ніє держа́вноє і всему́ ми́ру Покро́в. Тебі́, Милос́ердой і Благолюби́вой засту́пниці на́шей, за любо́в любо́вію воздава́я, смиренному́дренно глаго́лем:","Ра́дуйся, Ра́досте Всеми́рная, є́юже сле́зи оте́млються от оче́с стра́ждущих і скорб’я́щих; ра́дуйся, Прибі́жище Благооти́шноє, в не́мже спаса́ються обурева́ємії бу́рею страсте́й жите́йськаго мо́ря.","Ра́дуйся, Утоли́тельнице Всемогу́щая пра́ведно дви́жимаго на нас гні́ва Бо́жия; ра́дуйся, пла́мень огня́ угаша́ющая росо́ю моли́тв Твої́х у Престо́ла Вседержи́теля.","Ра́дуйся, от гро́ма і мо́лнії соблюда́ющая предста́тельством Твої́м Небе́сним; ра́дуйся, по́мощ Твою́ святу́ю благовре́менно подаю́щая вся́кой душі́, ві́рно Тебі́ моля́щейся.","Ра́дуйся, Благода́тная, Купино́ Неопали́мая, о́гненнаго запале́нія нас ізбавля́ющая."]},{"h":"Кондак 4","ps":["Бу́ря о́гненная єгда́ на́йдеть на нас внеза́пно і пла́мень гра́ди і ве́сі на́ша оби́меть, тогда́, Госпоже́ Всеми́лостивая, ускори́ на по́мощ к нам безпомо́щним і іко́ною Твоє́ю честно́ю защити́ і ізба́ви нас от о́гненнаго наказа́нія, єго́же сотвори́хомся досто́йнії гріх на́ших ра́ди. Тебе́ бо грі́шнії і́мами Засту́пницю непости́дную, на Тя упова́ніє на́ше возлага́єм і, прославля́я си́лу моли́тв Твої́х, Ро́ждшемуся от Тебе́ Спа́су ми́ра зове́м: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шим і ви́дим чудеса́ ве́лія от іко́ни Твоєя́ бива́ємия, Цари́це на́ша Всеблага́я, ю́же дарова́ла єси́ нам во утіше́ніє і защи́ту в несча́стіях: се бо і всепояда́ющий огнь ізнемога́єть в си́лі своє́й пред си́лою благода́тною Твоєго́ Пречи́стаго о́браза, я́коже мно́гажди ви́діхом і іспита́хом, неопали́мою купино́ю Тя імену́я в ізображе́нії сего́ Твоєго́ о́браза, і пред ним Тебі́ воспіва́я гла́си хвале́бними си́це:","Ра́дуйся, Моли́твеннице Неусипа́ющая ко Христу́ Бо́гу, на ми́лость к нам Єго́ преклоня́ющая; ра́дуйся, ка́ру Бо́жию за беззако́нія на́ша от глав на́ших отводя́щая.","Ра́дуйся, ри́зою Твоє́ю честно́ю от вся́ких несча́стій нас сохраня́ющая; ра́дуйся, Ма́терним покро́вом щедро́т Твої́х жили́ща на́ша от огня́ і гро́ма соблюда́ющая.","Ра́дуйся, Всеми́лостивая Усли́шательнице гла́сов на́ших моле́бних в ско́рбі і обстоя́нії; ра́дуйся, Держа́вная Скоропомо́щнице на́ша во дні тя́жких іспита́ній.","Ра́дуйся, Благода́тная, Купино́ Неопали́мая, о́гненнаго запале́нія нас ізбавля́ющая."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́, іко́на Твоя́ всечестна́я, Богоро́дице Ді́во, во всім ми́рі чуде́с мно́жеством благода́тно сія́єть і просвіща́єть ду́ші і сердця́ челові́чеськія к позна́нію ве́лія Твоєго́ милосе́рдія, і́мже род христия́нський покрива́єши і заступа́єши, я́ко Ма́ти благосе́рдая. О сем ра́дующеся, благодари́м Христа́ Бо́га, Тебе́, Ма́тер Свою́ по пло́ті, і нам в Ма́тер по ду́ху дарова́вшаго і зове́м Єму́ во умиле́нії глубо́цім: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дим іко́ну Твою́, Влади́чице, я́ко воі́стинну Купину́ Неопали́мую, во огні́ несгора́ющую, і прису́тствієм свої́м жили́ща челові́чеськия в пла́мені несгора́ємими соді́ловающую: Тебі́ бо даде́ся благода́ть сви́ше, си́лу єстества́ о́гненнаго укроща́ти, огнь Божества́ во чре́ві Твоє́м неопа́льно вмісти́вшей. Сея́ же благода́ті і о́браз подо́бія Твоєго́ прича́стен показа́ся, ті́мже от ві́рних Неопали́мою Купино́ю найменова́ся, єго́же ми честву́єм благолі́пно, і Тебі́ хвале́бно вопіє́м:","Ра́дуйся, Свіще́ Неугаси́мая, в моли́твах за нас у Престо́ла Госпо́дня присногоря́щая; ра́дуйся, огне́м любве́ Бо́жия і на́ша хла́дная сердця́ воспламеня́ющая.","Ра́дуйся, сі́нію моли́тв Твої́х зной страсте́й на́ших прохлажда́ющая; ра́дуйся, в час ско́рби і недоумі́нія по́мисли душеполе́зния нам низпосила́ющая.","Ра́дуйся, во вре́м'я безпомо́щія на́шего, єгда́ бі́дствуєм і не і́мами помога́ющаго, на по́мощ к нам ускоря́ющая; ра́дуйся, в годи́ну несча́стій внеза́пних держа́вною руко́ю Твоє́ю от поги́белі нас ісхища́ющая.","Ра́дуйся, Благода́тная, Купино́ Неопали́мая, о́гненнаго запале́нія нас ізбавля́ющая."]},{"h":"Кондак 6","ps":["Пропові́дуєть Це́рков Христо́ва чудеса́ Твоя́, Богороди́тельнице, я́же па́че піска́ морська́го і звізд небе́сних мно́жає суть: от восто́ка бо і до за́пада хва́льно і́м'я Твоє́ чудеси́, і ність гра́да іли́ страни́, іді́же не соверши́ся Тобо́ю ді́йство си́ли Бо́жия во ізбавле́ніє і спасе́ніє, просвіще́ніє і ісціле́ніє люде́й христоімени́тих. Найпа́че же чрез іко́ни Твоя́ святи́я оби́кла єси́ чудотвори́ти, ізлива́я от них струї́ ми́лости і щедро́т бі́дствующему і боля́щему челові́честву. Сего́ ра́ди славосло́вим Тя гла́си пі́сней духо́вних і вопіє́м Си́ну Твоєму́ і Бо́гу на́шему: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ла єси́ в світоли́тії Боже́ственния сла́ви, Ді́во Богоотрокови́це, Младе́нця Предві́чнаго, Го́спода Ісу́са Христа́ на руку́ Твоє́ю держа́щи, і лико́м сил а́нгельських окружа́єма, я́коже Тя ви́дим на іко́ні ізображе́нную, Моїсе́йськую Неопали́мую Купину́ та́їнственно пронарече́нную, от нея́же да́ри благода́тния ві́рним да́руєши, от огня́ і гро́ма спаса́єши, неду́жния врачу́єши, скорб'я́щия утіша́єши і всім вся блага́я і душеполе́зная низпосила́єши, во є́же пі́ти Тебі́ гла́си немо́лчними си́це:","Ра́дуйся, о Не́йже ра́дується і торжеству́єть А́нгельський собо́р і челові́чеський род; ра́дуйся, єя́же сла́ва превосхо́дить похвали́ земни́я і небе́сния.","Ра́дуйся, от го́рних висо́т всю вселе́нную Ма́тернею любо́вію Твоє́ю назира́ющая; ра́дуйся, юдо́ль земну́ю многоско́рбную благодія́нії Твої́ми посіща́ющая.","Ра́дуйся, неісче́тною благости́нею Твоє́ю не оставля́ющая са́мих презрі́нних і отве́рженних; ра́дуйся, сердобо́лієм Твої́м от ро́ва поги́бельнаго ісхища́ющая безнаде́жних.","Ра́дуйся, Благода́тная, Купино́ Неопали́мая, о́гненнаго запале́нія нас ізбавля́ющая."]},{"h":"Кондак 7","ps":["Хотя́ Госпо́дь яви́ти любо́в Свою́ к лю́дем, іскупле́нним Єго́ Кро́вію, дарова́ нам в покро́в і защи́ту Ма́тер Свою́ Пренепоро́чную, і Сію́ сотвори́ прибі́жище благооти́шноє вся́кой душі́ христия́нстій, скорб'я́щей і озло́бленній, по́мощі і ми́лости тре́бующей. Ві́дуще у́бо о такові́м милосе́рдом служе́нії Твоє́м ро́ду челові́чеському, Влади́чице Всеблага́я, к Тебі́ о́чі на́ші в ско́рбіх возво́дим, і ру́ці моле́бно простира́єм, утіше́нія от Тебе́ єди́ния прося́ще, да спасе́ши нас предста́тельством Твої́м от скорбе́й вре́менних і ві́чних і сподо́биши на землі́ живи́х, в ра́дості святи́х пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вно просла́вила єси́ чудеси́ іко́ну Твою́ святу́ю Неопали́мою Купино́ю імену́ємую, Богоро́дице Ді́во, є́юже гра́ди і ве́сі от запале́нія о́гненнаго і молнієно́снаго гро́ма соблюда́єши і до́ми ві́рних благословля́єши, в ни́хже честву́ється благогові́йно пречи́стаго ли́ка Твоєго́ подо́біє. Сего́ ра́ди я́ко дар многоці́нен, о́браз Твой благода́тний ра́достно приє́млем, достодо́лжним поклоне́нієм почита́єм, і Тя по до́лгу ублажа́єм благохвале́нії си́ми:","Ра́дуйся, Алава́стре врачева́нія, на всяк неду́г врачевство́ содержа́щий; ра́дуйся, Мирополо́жнице благоуха́нія Христо́ва, облагоуха́вшая па́дшеє челові́чество.","Ра́дуйся, у́зи гріхо́вния разріша́ющая ка́ющимся грі́шником; ра́дуйся, плени́ці страсте́й сокруша́ющая подвиза́ющимся о чистоті́.","Ра́дуйся, дів Младопита́тельнице і ма́терей ти́хоє Весе́ліє; ра́дуйся, вдов Засту́пнице і сиро́т благосе́рдоє Призрі́ніє.","Ра́дуйся, Благода́тная, Купино́ Неопали́мая, о́гненнаго запале́нія нас ізбавля́ющая."]},{"h":"Кондак 8","ps":["Стра́нно єсть ви́діти, я́ко іко́на Твоя́, Влади́чице, на дсці напи́санная і по єстеству́ своєму́ о́гненному ді́йству подве́рженная, си́лу пачеєсте́ственную явля́єть і прису́тствієм свої́м си́лу огня́ укроща́єть. В сем познава́я си́лу Бо́жию і Твої́х моли́тв ді́йство, велича́єм возвели́чившаго Тя Зижди́теля, вся́чеських Бо́га, во отра́ду і утіше́ніє нам дарова́вшаго о́браз Твой чудотво́рний і сим спаса́ющаго нас от о́гненнаго запале́нія, да при́сно зове́м Єму́ благода́рственно і хвале́бно: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь мир христия́нський сла́вить і́м'я Твоє́, Преблагослове́нная Марі́є Богоро́дице, і вся́кому ві́рному сла́достно і уті́шительно єсть взира́ти на Пречи́стаго ли́ка Твоєго́ подо́біє, і́мже оби́кла єси́ явля́ти мно́гая і пресла́вная чудеса́. Се і ми, смире́ннії, Твою́ святу́ю іко́ну ви́дяще, благолі́пно єй покланя́ємся і с любо́вію ю лобиза́єм, ча́юще от нея́ по́мощі і заступле́нія Твоєго́ держа́внаго, найпа́че же во вре́м'я безпомо́щія на́шего, єгда́ гріх ра́ди на́ших о́гненноє запале́ніє на ни на́йдеть внеза́пно, да спаса́ємі Тобо́ю от поги́бельнаго пла́мене благода́рними усти́ Тебі́ вопіє́м:","Ра́дуйся, нерукотворе́нная ски́ніє Бо́га Сло́ва, Херуви́ми превиша́ющая і Серафи́ми превосходя́щая святи́нею і чистото́ю; ра́дуйся, О́блаче ле́гкий Со́лнця Пра́вди, І́мже Небе́сний к земни́м при́йде, да на не́бо с Собо́ю нас возведе́ть.","Ра́дуйся, ра́йськія две́рі отве́рзшая па́дшему челові́честву Рождество́м Твої́м Святи́м; ра́дуйся, не́бо і зе́млю воєди́но совоку́пльшая, во є́же пі́ти Тебі́ і Ро́ждшемуся от Тебе́ немо́лчния хвали́.","Ра́дуйся, Боже́ственний Істо́чниче, во́ду жи́зні істочи́вий, от него́же пію́щії ктому́ не умира́ють; ра́дуйся, гро́здіє спасе́нія возрасти́вшая Благослове́нная Лозо́, вино́ безсме́ртія іска́пающий челові́ком.","Ра́дуйся, Благода́тная, Купино́ Неопали́мая, о́гненнаго запале́нія нас ізбавля́ющая."]},{"h":"Кондак 9","ps":["Вся́ку похвалу́ превосхо́дить сла́ва Твоя́, Преблагослове́нная і Препросла́вленная Ма́ти Го́спода на́шего: недоуміва́ють бо і у́ми безпло́тнії пі́ти Тя по достоя́нію, па́че же нам, земни́м і пе́рстним, сіє́ неудо́бно єсть, оба́че любо́вію к Тебі́ побіжда́ємі, дерза́єм приноси́ти Тебі́ поси́льноє пі́ніє хвали́ і благодаре́нія, за премно́гую ми́лость Твою́ к ро́ду челові́чеському, єго́же возлюби́ла єси́ і єму́же благотвори́ти не престає́ши, подвиза́я всяк во́зраст ві́рних взива́ти ро́ждшемуся от Тебе́ Спа́су Христу́: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тiії⁽2⁾ челові́честії ізнемога́ють пости́гнути ве́лію та́йну Твоєго́ Присноді́вства, Богороди́тельнице, ю́же утаї́ Госпо́дь от прему́дрих ві́ка сего́, і ві́рою откри́ смире́нним і благогові́йним, питли́ваго іспита́нія чу́ждим, от ни́хже правосла́вно і несумні́нно до Рождества́, і в Рождестві́, і по Рождестві́ Ді́ва пропові́дуєшися. Прийми́ у́бо, о Ма́ти і Ді́во, і на́ше о сем іспові́даніє вседуше́вноє і укріпи́ нас послі́довати Тебі́ житіє́м непоро́чним і серде́чною чистото́ю, да возмо́жем благоуго́дно воспіва́ти Тебі́ пі́сні сицеви́я:","Ра́дуйся, Кри́не⁽3⁾ Білосні́жний ді́вства і чистоти́, неув'яда́ємо цвіту́щий горі́; ра́дуйся, к ді́вству і чи́стоті́ неви́димо руково́дствующая живу́щих до́лі.","Ра́дуйся, ма́терство і ді́вство в Себі́ чу́дно сочета́вшая; ра́дуйся, во обою́ непоро́чно і свято себе́ соблю́дшая.","Ра́дуйся, і́ночеських лико́в предводи́тельнице в ді́встві Богоуго́днім; ра́дуйся, ді́вственних полко́в нача́льнице в чи́стоті́ душі́ і ті́ла.","Ра́дуйся, Благода́тная, Купино́ Неопали́мая, о́гненнаго запале́нія нас ізбавля́ющая."]},{"h":"Кондак 10","ps":["Спасе́ніє челові́чеськоє устроя́я Єди́н от Тро́йці воплоти́тися от Тебе́ ізво́ли, Богоневі́сто Влади́чице, єстество́ челові́чеськоє просла́вив сіді́нієм одесну́ю Отця́ на престо́лі Божества́, я́ко Син Єдиноро́дний, Тойже і Син Твой по пло́ті бисть, і Тебе́ с Собо́ю просла́ви сла́вою преви́шшею вся́кия сла́ви, єя́же добро́тою осіня́єма, не забива́єши ми́лостивно род челові́чеський, но моли́твенно предста́тельствуєши пред Творце́м в Тро́йці Єди́ним, о всіх ві́рно пою́щих Єму́ славосло́вія піснь: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ ді́вственним лико́м і і́ночеським собо́ром, Богоро́дице Ді́во, і всім усе́рдно к Тебі́ в моли́твах притека́ющим, іко́ну же Твою́ святу́ю благогові́йно честву́ющим; Тебі́ бо єди́ній дарова́ся от Го́спода благода́ть всеми́рнаго заступле́нія, і ві́рних в ді́встві і чи́стоті́ утвержде́нія. Ті́мже непоро́чнаго житія́ рачи́теліє под Ма́терній покро́в Твой от бу́рі страсте́й прибіга́ють і благооти́шіє душе́вноє нахо́дять, согла́сно Тебі́ взива́я:","Ра́дуйся, і́ноков і і́нокинь благочести́вих ізря́дная Покрови́тельнице і те́плая к Бо́гу о них хода́тайце; ра́дуйся, та́йних среди́ ми́ра рабо́в Бо́жиїх всегда́шняя помо́щнице і в по́двизіх духо́вних руководи́тельнице.","Ра́дуйся, ю́них наста́внице цілому́дрія і воздержа́нія; ра́дуйся, ста́рцев благогові́йних упокоє́ніє і отра́до.","Ра́дуйся, до́ми і семе́йства християнськия осіня́ющая благи́м Твої́м покро́вом; ра́дуйся, всяк во́зраст ві́рних сподобля́ющая Твоєго́ благосе́рдаго попече́нія.","Ра́дуйся, Благода́тная, Купино́ Неопали́мая, о́гненнаго запале́нія нас ізбавля́ющая."]},{"h":"Кондак 11","ps":["Пі́ніє хвале́бноє прино́сить Тебі́ немо́лчно Свята́я Христо́ва Це́рков, Всепі́тая Влади́чице, возвіща́я ми́лості Твоя́ і чудеса́, ї́миже обогати́ся вся вселе́нная. Воі́стину, кто бо я́коже Ти скоропослушли́ва єсть к моли́твенним проше́ніям на́шим? Но і са́мия проше́нія оби́кла єси́ предваря́ти, ми́луя і ущедря́я тре́бующих по́мощі Твоєя́ святи́я, єя́же не лиши́ і нас, смире́нних, в час сей пою́щих во сла́ву і́мене Твоєго́, і вопію́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рная Твоя́ іко́на, Богома́ти Пречи́стая, просвіща́єть потемне́нния гріхми́ ду́ші на́ша сія́нієм Боже́ственних чуде́с, в ни́хже познае́м Бо́жия всемогу́щества си́лу і Твоє́ милосе́рдіє неісче́тноє, при́сно гото́воє спосо́бствовати нам в покая́нії і обраще́нії от злих діл на путь спасе́нія. Мо́лим у́бо Тебе́, Всеблага́я, не оста́ви нас заблужда́ти в де́бріх гріхо́в і страсте́й, но приведи́ к ти́хому приста́нищу благоче́стнаго і Богоуго́днаго житія́, да возмо́жем досто́йно приноси́ти Тебі́ сія́ пі́сненния да́ри:","Ра́дуйся, враги́ на́ша неви́димия запина́ющая бо́дренною Твоє́ю моли́твою; ра́дуйся, сим не попуска́ющая облада́ти на́ми наси́лієм сме́ртнаго сего́ тілесе́.","Ра́дуйся, я́ко бі́си і́мені Твоєго́ свята́го боя́ться і трепе́щуть; ра́дуйся, я́ко іко́на Твоя́ честна́я вся́ку си́лу дия́волю прису́тствієм свої́м прогоня́єть.","Ра́дуйся, подви́жников благоче́стія укріпля́ющая в бра́ні духо́вной со врага́ми спасе́нія челові́чеськаго; ра́дуйся, в час кончи́ни помога́ющая любо́в і ві́ру к Тебі́ іму́щим.","Ра́дуйся, Благода́тная, Купино́ Неопали́мая, о́гненнаго запале́нія нас ізбавля́ющая."]},{"h":"Кондак 12","ps":["Благода́ті Бо́жия прича́стну іспові́дуєм Твою́ святу́ю іко́ну, Богоблагода́тная Ді́во, і сві́тло торжеству́єм пра́здник єя́ явле́нія; во о́бразі бо Неопали́мия Купини́ сія́ я́вльшися, то́жде і ді́йство показу́єть свої́ми чудеси́, от о́гненнаго пла́мене сохраня́я і соблюда́я жили́ща на́ша свої́м прису́тствієм. Сію́ у́бо, я́ко щит і забра́ло, іму́ще, Тебе́, помо́щницю на́шу держа́вную хвала́ми пі́сненними ублажа́єм і Ро́ждшемуся от Тебе́ Спаси́телю на́шему вопіє́м: Аллилу́я."]},{"h":"Ікос 12","ps":["Поє́м Тя, Богороди́тельнице, єди́ну Наде́жду і Упова́ніє на́ше, іспові́дуєм ми́лості Твоя́ і не таї́м чуде́с Твої́х, прославля́єм неісче́тную бла́гость Твою́ к ро́ду христия́нському, благословля́єм і́м'я Твоє́ свято́є, є́же воі́стину ми́ро ізлія́нноє єсть лю́б’ящим Тя, благоуха́нієм духо́вним ісполня́ющеє благочести́вия ду́ші. Облагоуха́й у́бо і нас, Влади́чице, смердя́щих страстьми́ гріхо́вними, і сподо́би чи́стим се́рдцем і нескве́рними усти́ взива́ти к Тебі́:","Ра́дуйся, ми́ро істоча́ющая сла́достноє і душеспаси́тельноє, і́мже умаща́ються сердця́ боголюби́вая; ра́дуйся, неду́ги душе́вния і тіле́сния врачу́ющая єди́ним прикоснове́нієм к іко́ні Твоє́й святі́й.","Ра́дуйся, Води́тельнице Блага́я, на путь богоугожде́нія і спасе́нія направля́ющая ка́ющихся грі́шников; ра́дуйся, лі́ствицею доброді́телей возводя́щая подви́жников Христо́вих ко врата́м Ца́рствія Небе́снаго.","Ра́дуйся, смире́нних і терпіли́вих страда́льцев вінча́ющая утіше́нієм благода́тним; ра́дуйся, ізгна́нних і гони́мих безви́нно, услажда́ющая предвкуше́нієм блаже́нства ра́йськаго.","Ра́дуйся, Благода́тная, Купино́ Неопали́мая, о́гненнаго запале́нія нас ізбавля́ющая."]},{"h":"Кондак 13","ps":["О, Всепі́тая Ма́ти, ро́ждшая всіх святи́х Святі́йшеє Сло́во і Неопали́мою Купино́ю імену́ємая от нас недосто́йних, воньми́ гла́су моле́ній і пі́ній на́ших, пред свято́ю іко́ною Твоє́ю усе́рдно Тебі́ возноси́мому, і те́плою моли́твою Твоє́ю ко Го́споду огня́ вре́меннаго і ві́чнаго ізба́ви нас, хва́лящих і́м'я Твоє́ і прославля́ющих чудеса́ Твоя́, Си́ну же Твоєму́ і Бо́гу на́шему вопію́щих: Аллилу́я.","§Цей кондак читається тричі. Після цього знову читаються 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Цари́це і всея́ тва́рі Влади́чице, Госпоже́ Богоро́дице, от А́нгельських лико́в горі́ приє́млющая хвале́бноє пі́ніє, сподо́би і нас, земни́х і пе́рстних, возноси́ти к Тебі́ гла́си хвали́ благодаре́нія за премно́гую ми́лость Твою́ к ро́ду челові́чеському. І а́ще недосто́йни єсьми́ пі́ти Тя по достоя́нію, оба́че Ти, я́ко блага́я, не возгнуша́йся на́ших недовлі́ющих похва́л, і я́ко Син Твой дві ле́пті вдови́ці ми́лостивно прия́т, та́ко любоблагоутро́бно усли́ши нас, со умиле́нієм к Тебі́ вопію́щих:","Ра́дуйся, огнь Божества́ во чре́ві Твоє́м неопа́льно носи́вшая; ра́дуйся, Спаси́теля па́дшему челові́честву ро́ждшая.","Ра́дуйся, си́лу а́дову пречеcтни́м Рождество́м Твої́м упраздни́вшая; ра́дуйся, Ада́ма і Є́ву дре́вняго прокля́тія свободи́вшая.","Ра́дуйся, вочелові́ченію Єди́наго от Тро́йці непоро́чно послужи́вшая; ра́дуйся, Творця́ Небесе́ і землі́ безсі́менно воплоти́вшая.","Ра́дуйся, Благода́тная, Купино́ Неопали́мая, о́гненнаго запале́нія нас ізбавля́ющая."]},{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді, Пречи́стой і Богообра́дованной Ді́ві Богоро́диці, огнезра́чния іко́ни своєя́ явле́нієм обра́довавшей Це́рков Христо́ву і є́ю от о́гненнаго запале́нія защища́ющей ві̑рния, похва́льноє возглаша́єм пі́ніє. Ти же, о Богома́ти, Купино́ Неопали́мая імену́ємая на́ми, я́ко іму́щая держа́ву непобіди́мую і милосе́рдіє мно́гоє, ускори́ на по́мощ к нам, тре́бующим Твоєго́ заступле́нія, і от вся́ких бід свободи́ зову́щих Ті:","Ра́дуйся, Благода́тная, Купино́ Неопали́мая, о́гненнаго запале́нія нас ізбавля́ющая."]},{"h":"Молитва","ps":["О, Пресвята́я і Преблагослове́нная Ма́ти сладча́йшаго Го́спода на́шего Ісу́са Христа́, припа́даєм і покланя́ємся Тебі́ пред свято́ю і пречестно́ю іко́ною Твоє́ю, є́юже ди́вная і пресла́вная чудеса́ содіва́єши, от о́гненнаго запале́нія і молнієно́снаго гро́ма жили́ща на́ша спаса́єши, неду́жния ісціля́єши і вся́ко благо́є проше́ніє на́ше во бла́го ісполня́єши. Смире́нно мо́лим Тя, всеси́льная ро́да на́шего Засту́пнице: сподо́би нас, немощни́х і грі́шних, Твоєго́ Ма́терняго уча́стія і благопопече́нія. Спаси́ і сохрани́, Влади́чице, под кро́вом ми́лости Твоєя́ богохрани́мую страну́ на́шу, вла́сті і во́їнство єя́, Це́рков святу́ю, храм сей, [або: оби́тель сію́], і вся ни припа́дающия к Тебі́ с ві́рою і любо́вію, і умиле́нно прося́щия со слеза́ми Твоєго́ заступле́нія. Єй, Госпоже́ Всеми́лостивая, умилосе́рдися на нас, обурева́ємих гріха́ми мно́гими і не іму́щих дерзнове́нія ко Христу́ Бо́гу проси́ти Єго́ о поми́лованії і проще́нії, но Тебі́ предлага́єм к Нему́ на умоле́ніє, Ма́тер Єго́ по пло́ті. Ти же, Всеблага́я, простри́ к Нему́ Богопри́їмнії ру́ці Твої́ і предста́тельствуй за нас пред бла́гостію Єго́, прося́ нам проще́нія прегріше́ній на́ших, благоче́стнаго ми́рнаго житія́, благи́я христия́нськия кончи́ни і до́браго отві́та на Стра́шнім Суді́ Єго́. Найпа́че же в час гро́знаго посіще́нія Бо́жия, єгда́ огне́м возгоря́ться до́ми на́ша іли́ молнієно́сним гро́мом устраша́ємі бу́дем, яви́ нам ми́лостивноє Твоє́ заступле́ніє і держа́вноє вспоможе́ніє, да спаса́ємі всеси́льними Твої́ми ко Го́споду моли́твами, вре́меннаго наказа́нія Бо́жия зді ізбі́гнем і ві́чноє блаже́нство ра́йськоє та́мо унаслі́дуєм, і со всі́ми святи́ми воспоє́м пречестно́є і великолі́поє і́м'я покланя́ємия Тро́йці, Отця́, і Си́на, і Свята́го Ду́ха, і Твоє́ ве́ліє к нам милосе́рдіє, во ві́ки віко́в. Амі́нь."]}],"notes":["пе́рстних – смертних","Вѣ́тія — оратор, красномовець","крин — лілія"]},{"u":"Акафіст Пресвятій Богородиці перед Її чудотворною іконою «Ізбавительниця»","e":"Akathist to the Theotokos before her icon “The Deliverer”","secs":[{"h":"Кондак 1","ps":["Возбрани́ враго́м на́шим озлобля́ти нас і от Го́спода на́шего отлучи́ти коне́чні і научи́ нас пі́ти Тебі́ ве́село:","Ра́дуйся, Ізба́вительнице, от го́ря, бід і ги́белі спаса́ющая нас, бі́дствующих."]},{"h":"Ікос 1","ps":["А́нгелов мно́жество по Твоєму́, Ма́ти на́ша, повелі́нію ополча́ються на ізбавле́ніє на́ше гро́зно. Ти же прийми́ моли́тву сію́:","Ра́дуйся, а́нгелов на спасе́ніє на́ше посила́ющая; ра́дуйся, Цари́це го́рних чино́в, небе́сную їх по́мощ нам да́рующая.","Ра́дуйся, а́нгелом храни́ти нас повеліва́ющая; ра́дуйся, во́їнством а́нгельським враго́в на́ших поража́ющая.","Ра́дуйся, Ізба́вительнице, от го́ря, бід і ги́белі спаса́ющая нас, бі́дствующих."]},{"h":"Кондак 2","ps":["Ви́дять бі́дствующії толи́кую і мно́гую по́мощ Твою́ серде́чно Тя призива́ющим і наставля́ються тім пі́ти Си́ну Твоєму́ непреста́нно: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́ють мно́зі, я́ко ми́рові дарова́ Тя Син Твой Ізба́вительницю бі́дствующим, ті́мже поє́м Ті си́це:","Ра́дуйся, бі́дствующих Ма́ти; ра́дуйся, стра́ждущих утіше́ніє.","Ра́дуйся, боля́щих ісціле́ніє; ра́дуйся, ненаде́жних наде́ждо.","Ра́дуйся, Ізба́вительнице, от го́ря, бід і ги́белі спаса́ющая нас, бі́дствующих."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго дарова́ся Ті на по́мощ і спасе́ніє ми́ру і нас, в біда́х погиба́ющих. І кто же Тобо́ю не ізба́влен бисть? І кто же не поє́ть Си́ну Твоєму́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи непостижи́мую любо́в к ро́ду челові́чу, ка́я воздиха́нія не прия́ла єси́, кíя сле́зи не оте́рла єси́, і кого́ не прину́дила єси́ призива́ти Тя, вопію́ще:","Ра́дуйся, бі́дствующих ско́роє усли́шаніє; ра́дуйся, печа́льних і ско́рбних утіше́ніє.","Ра́дуйся, погиба́ющих би́строє спасе́ніє; ра́дуйся, пліне́нних свобожде́ніє.","Ра́дуйся, Ізба́вительнице, от го́ря, бід і ги́белі спаса́ющая нас, бі́дствующих."]},{"h":"Кондак 4","ps":["Бу́ря несча́стій налеті́ на ни, спаси́ у́бо нас, погиба́ющих, Ізба́вительнице на́ша, бу́рю поги́бельную на землі́ укроти́вшая і приє́млющая на́шу піснь: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша челові́честії ро́ди всю Твою́ к христия́ном ди́вную любо́в і Твоє́ мо́щноє ізбавле́ніє от вся́ких находя́щих на них лю́тих, научи́шася пі́ти Тебі́:","Ра́дуйся, челові́чеськаго ро́да от бід ізбавле́ніє; ра́дуйся, бур жите́йських прекраще́ніє.","Ра́дуйся, уни́нія Прогони́тельнице; ра́дуйся, ра́дости по ско́рбі нам Пода́тельнице.","Ра́дуйся, Ізба́вительнице, от го́ря, бід і ги́белі спаса́ющая нас, бі́дствующих."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ подо́б'ящася, мрак і темноту́ в грі́шних сердця́х разгоня́єши, да во сві́ті Твоєя́ любве́ у́зрять Го́спода і воспою́ть Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діша лю́діє украї́нстії Твоє́ неча́янноє от многоразли́чних бід ізбавле́ніє, ра́достно пою́ть Тебі́ си́це:","Ра́дуйся, в біда́х на́ша Помо́щнице; ра́дуйся, скорбе́й на́ших от'я́тіє.","Ра́дуйся, печа́лей на́ших Отгна́ніє; ра́дуйся, в ско́рбіх на́ших утіше́ніє.","Ра́дуйся, Ізба́вительнице, от го́ря, бід і ги́белі спаса́ющая нас, бі́дствующих."]},{"h":"Кондак 6","ps":["Пропові́дують по́мощ і любо́в Твою́, Ма́ти, ісціле́ннії, уті́шеннії, обра́дованнії і спасе́ннії Тобо́ю от бід, і пою́ть Твоєму́ високодержа́вному Си́ну: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ нам світ спасе́нія во мглі поги́белі, окружи́вшей нас, і наста́ви пі́ти Тебі́:","Ра́дуйся, мглу гріхо́в разгоня́ющая; ра́дуйся, тьму гріхо́вную потребля́ющая.","Ра́дуйся, мрак душі́ моєя́ просвіща́ющая; ра́дуйся, сві́том ра́дости ду́ші ободря́ющая.","Ра́дуйся, Ізба́вительнице, от го́ря, бід і ги́белі спаса́ющая нас, бі́дствующих."]},{"h":"Кондак 7","ps":["Хотя́щим нам коне́чному отча́янію преда́тися, отвсю́ду біда́м належа́щим, поми́слихом же о Тебі́, Ізба́вительнице, і ободри́хомся, і уті́шихомся, пою́ще Си́ну Твоєму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую і нежда́нную показа́ нам ми́лость Свою́, под держа́вную руку́ Твою́ нас восприя́вши, і отвсю́ду вопіє́м Ті, Богоро́дице:","Ра́дуйся, Цари́це Держа́вная; ра́дуйся, і нас под Твою́ держа́ву восприя́вшая.","Ра́дуйся, защи́ту Твою́ нам дарова́вшая; ра́дуйся, враго́в на́ших порази́вшая.","Ра́дуйся, Ізба́вительнице, от го́ря, бід і ги́белі спаса́ющая нас, бі́дствующих."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до: на поги́бель обрече́нних і в ну́ждах том'я́щихся безчи́сленних, внеза́пу спасе́ніє і ізбавле́ніє получа́ють от Тебе́, вселю́б'ящей, пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Всі су́щії во мра́ці скорбе́й, всі обурева́ємії несча́стій бу́рею, прийді́те к до́брому приста́нищу і на́шему поможе́нію, покро́ву Ді́ви Ізба́вительниці, вопію́ще Єй:","Ра́дуйся, ра́достей істо́чниче; ра́дуйся, печа́лей прогна́ніє.","Ра́дуйся, бід ізбавле́ніє; ра́дуйся, вся́чеськаго поко́я Пода́тельнице.","Ра́дуйся, Ізба́вительнице, от го́ря, бід і ги́белі спаса́ющая нас, бі́дствующих."]},{"h":"Кондак 9","ps":["Все существо́ челові́чеськоє хва́лить Тя, всі воспіва́ють Тя, многоразли́чноє ізбавле́ніє несу́щую, вмі́сто печа́лей ра́дость подаю́щую пою́щим Си́ну Твоєму́ і Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Вітíї⁽1⁾ многоу́мнії обезу́міша, ви́дяще Твоє́ ско́роє і чуде́сноє от бід стра́ждущих ізбавле́ніє, і умолко́ша нам, пою́щим Ті:","Ра́дуйся, чудеси́ мир удиви́вшая; ра́дуйся, чудеси́ нас укріпи́вшая.","Ра́дуйся, безбо́жіє чудеса́ми істреби́вшая; ра́дуйся, враго́в си́лою Божиєю посрами́вшая.","Ра́дуйся, Ізба́вительнице, от го́ря, бід і ги́белі спаса́ющая нас, бі́дствующих."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ вся́ку ду́шу челові́чу, все́ю любо́вію пече́шися о ней, до́ндеже научи́ши ю пі́ти Си́ну Твоєму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіно́ю, мир христия́нський храня́щей і вся́ку ду́шу от враго́в огражда́ющей, яви́ся іко́на Твоя́, Ізба́вительнице, в ми́рі правосла́внім і чудеси́ просла́вися. Тебі́ лю́дем Бо́жиїм воспіва́ющим:","Ра́дуйся, Наста́внице на́ша, святу́ю го́ру Афо́нськую в жре́бій Себе́ ізбра́вшая; ра́дуйся, Ізба́вительнице на́ша, Твої́м благослове́нієм но́вий Афо́н благослови́вшая.","Ра́дуйся, весе́ліє на́ше, зна́меніє сою́за неразри́внаго уді́лов Твої́х земни́х іко́ною Твоє́ю яви́вшая; ра́дуйся, ві́чная ра́досте на́ша, чуде́сним попече́нієм к ю́ной Новоафо́нськой оби́телі благоволи́вшая.","Ра́дуйся, Ізба́вительнице, от го́ря, бід і ги́белі спаса́ющая нас, бі́дствующих."]},{"h":"Кондак 11","ps":["Пі́ніє непреста́нноє прино́сять Ті, Влади́чице, Тобо́ю ізба́вленнії і Тобо́ю па́ки ра́дость обрі́тшії, і Бо́же́ственному Си́ну Твоєму́ пою́ть ра́достно: Аллилу́я."]},{"h":"Ікос 11","ps":["Світосія́ющим світи́лом лучеза́рним во мра́ці гріха́ яви́ся нам іко́на Твоя́, Ізба́вительнице, наставля́ющая нас пі́ти Тебі́:","Ра́дуйся, от гла́да нас ізбавля́ющая; ра́дуйся, вредонося́щеє єстество́ от расті́ній отгоня́ющая.","Ра́дуйся, посі́ви і ліса́, і вся расту́щая от поги́белі спаса́ющая; ра́дуйся, земледі́льцев скорб’я́щих утіше́ніє і труда́ їх благослове́ніє.","Ра́дуйся, Ізба́вительнице, от го́ря, бід і ги́белі спаса́ющая нас, бі́дствующих."]},{"h":"Кондак 12","ps":["Благода́ть, от іко́ни Твоєя́, Ізба́вительнице, теку́щая, ісціле́ній струї́ оби́льно подаю́щая і сердця́ весе́лієм оживля́ющая, побіжда́єть всіх во́лею пі́ти Тебі́, Ма́ти, і Си́ну Твоєму́ і Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Воспіва́єм ісціле́нія, от святи́я іко́ни Твоєя́ бива́ємая, воспіва́єм найпа́че воскреше́ніє Анаста́сія о́трока і воспіва́юще поє́м:","Ра́дуйся, ме́ртвих воскреша́ющая; ра́дуйся, уме́ршая сердця́ оживля́ющая.","Ра́дуйся, от сме́рти і ві́чнаго огня́ ізима́ющая; ра́дуйся, посме́ртноє на́ше упова́ніє і защи́то.","Ра́дуйся, Ізба́вительнице, от го́ря, бід і ги́белі спаса́ющая нас, бі́дствующих."]},{"h":"Кондак 13","ps":["О Всепі́тая і Вселюби́мая на́ша Ма́ти! Умилосе́рдися ни́ні і поми́луй, в лю́тих і безисходних су́щих нас ско́рбіх ізбавля́ющи, научи́ нас серде́чно воспіва́ти Бо́гу, проща́ющему нас: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов мно́жество по Твоєму́, Ма́ти на́ша, повелі́нію ополча́ються на ізбавле́ніє на́ше гро́зно. Ти же прийми́ моли́тву сію́:","Ра́дуйся, а́нгелов на спасе́ніє на́ше посила́ющая; ра́дуйся, Цари́це го́рних чино́в, небе́сную їх по́мощ нам да́рующая.","Ра́дуйся, а́нгелом храни́ти нас повеліва́ющая; ра́дуйся, во́їнством а́нгельським враго́в на́ших поража́ющая.","Ра́дуйся, Ізба́вительнице, от го́ря, бід і ги́белі спаса́ющая нас, бі́дствующих."]},{"h":"Кондак 1","ps":["Возбрани́ враго́м на́шим озлобля́ти нас і от Го́спода на́шего отлучи́ти коне́чні і научи́ нас пі́ти Тебі́ ве́село:","Ра́дуйся, Ізба́вительнице, от го́ря, бід і ги́белі спаса́ющая нас, бі́дствующих."]},{"h":"Молитва","ps":["О, Ма́ти Бо́жия, по́моще і защи́та на́ша, при́сно бу́ди нам Ізба́вительниця, на Тя бо упова́єм і всегда́ вседу́шно Тя призива́єм: умилосе́рдися і помози́, умили́ся і ізба́ви, приклони́ у́хо Твоє́ і на́ша ско́рбния і сле́зния моли́тви прийми́, і я́коже хо́щеши, успоко́й і обра́дуй нас, лю́б’ящих Твоєго́ Безнача́льнаго Си́на і Бо́га на́шего. Амі́нь."]}],"notes":["Ві́тія - оратор"]},{"u":"Акафіст Пресвятій Богородиці на честь Її чудотворної ікони «Неув'ядаємий Цвіт»","e":"Akathist to the Theotokos in honour of her icon “The Unfading Bloom”","secs":[{"h":"Кондак 1","ps":["О, Преблагослове́нная Богоро́дице Ді́во, Ра́дость і Прибі́жище всім христия́ном, покланя́яся Твоєму́ пречи́стому о́бразу, Тебі́ поє́м хвале́бную піснь, Тебі́ прино́сим свої́ ну́жди, го́ре і сле́зи. Ти же, о, кро́ткая Засту́пнице на́ша, Тебі́ бли́зькі вся на́ша земни́я ско́рбі і печа́лі, прийми́ же на́ша в моли́твах воздиха́нія, помози́ нам і от бід спаси́, неуста́нно бо і со умиле́нієм зове́м Ті:","Ра́дуйся, Ма́ти Бо́жия, Цві́те Неув'яда́ємий."]},{"h":"Ікос 1","ps":["Я́ко Бо́жиє благослове́ніє і я́ко дар небе́сний долгожда́нний, непреста́нною моли́твою іспроше́нная от Бо́га, ниспо́слана била́ єси́, Богоро́дице, пра́ведним і многообра́дованним роди́телем Твої́м Іоаки́му і А́нні. Ти же, о, Богоізбра́нная Отрокови́це, оста́вила єси́ роди́тельськоє ло́но і, я́ко світи́льник ві́ри неугаси́мий, я́ко кади́льниця благово́нная, во смире́нії предста́ла єси́ у поро́га Госпо́дня, і си́ла Ви́шняго вознесе́ Тя до са́маго вхо́да, введе́ во Свята́я Святи́х і отве́рзе вся сокрове́нная Не́ба. О, Премилосе́рдая Богоро́дице Ді́во! Отве́рзи і на́ша сердця́ к Твоєму́ славосло́вію і вознеси́ на́шу моли́тву к Си́ну Твоєму́ і Бо́гу на́шему, да зове́м Ті такова́я:","Ра́дуйся, Чистото́ недосяга́ємая і Красото́ неізрече́нная; ра́дуйся, во смире́нії Своє́м возвели́ченная.","Ра́дуйся, любве́ неісчерпа́ємий Істо́чниче; ра́дуйся, Сосу́де Бо́гом ізбра́нний.","Ра́дуйся, Засту́пнице на́ша усе́рдная.","Ра́дуйся, Ма́ти Бо́жия, Цві́те Неув'яда́ємий."]},{"h":"Кондак 2","ps":["О, Пресвята́я Ді́во Марі́є, по́мисли гріхо́вними і ді́ли сту́дними до́лу приклоне́ні єсьми́, се́рдце на́ше хо́лодом жи́зні об'я́то, о́чі отягще́ні гріхо́вним сном. Но Ти, о, Цві́те Неув'яда́ємий, оми́й нас росо́ю у́треннію, согрі́й нас со́лнцем любве́ і милосе́рдія. Подими́ нас, о, Влади́чице, от пра́ха земна́го ко Го́споду, да принесе́м Єму́ смире́нноє моле́ніє сіє́ на́ше і вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Арха́нгел Гавриї́л по́слан бисть от Бо́га во град Галиле́йський Назаре́т і принесе́ Ті, о Пречи́стая Ді́во, свято́є благові́стіє, глаго́ля: ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю! Ти бо обріла́ єси́ благода́ть у Бо́га. Ми же, недосто́йнії, зря́ще вели́чіє таково́є, во смире́нії се́рдця взива́єм:","Ра́дуйся, Благода́тная в жена́х; ра́дуйся, обрі́тшая благода́ть у Бо́га і па́че а́нгел возвели́ченная.","Ра́дуйся, я́ко зачала́ єси́ Си́на, І́же наслі́дить престо́л Дави́да отця́ Єго́; ра́дуйся, Сві́те неугаси́мий во тьмі сердця́м возже́гшая.","Ра́дуйся, сча́стія ві́чнаго две́рі нам отверза́ющая.","Ра́дуйся, Ма́ти Бо́жия, Цві́те Неув'яда́ємий."]},{"h":"Кондак 3","ps":["В ско́рбіх м'яте́мся, в суєті́ і печа́лі житія́ своєго́ дні прово́дим. Но Ти, о, Благослове́нная, освіти́ ду́ші на́ша Свої́м благові́стієм, напо́лни сердця́ на́ша смире́нієм. Да приклони́в глави́ на́ша, рече́м: се раби́ Госпо́дні, да бу́деть нам по во́лі Твоє́й! Тебі́ же, о, Цві́те Неув'яда́ємий, і от Тебе́ Рожде́нному всеча́сно поє́м: Аллилу́я."]},{"h":"Ікос 3","ps":["Во дні же ти́я текла́ єси́ Маріа́м во град Іу́дов і вни́де в дом Заха́ріїн, і цілова́ Єлисаве́т. І усли́ша Єлисаве́т цілова́ніє Марі́їно, і іспо́лнися Єлисаве́т Ду́ха Свя́та і возопи́ гла́сом ве́ліїм, глаго́ля: отку́да мні сіє́, да при́йде Ма́ти Го́спода Моєго́ ко мні! О, Пречи́стая Ді́во! Посіти́ і нас, немощни́х і убо́гих, і вознеси́ воздиха́нія на́ша, я́ко дим кади́льний, ко Престо́лу Всеви́шняго, да от полноти́ благода́рнаго се́рдця поє́м Тебі́ си́це:","Ра́дуйся, я́ко призрі́ Госпо́дь на смире́ніє раби́ Своєя́; ра́дуйся, я́ко ублажа́ть Тя всі ро́ди.","Ра́дуйся, я́ко сотвори́ Ті вели́чіє Си́льний; ра́дуйся, Істо́чниче жи́зні і безсме́ртія.","Ра́дуйся, Ма́ти Бо́жия, Цві́те Неув'яда́ємий."]},{"h":"Кондак 4","ps":["О, Цві́те Неув'яда́ємий! О, Красото́ благоуха́нная! Посіти́ нас в ско́рбній земно́й юдо́лі на́шей, умоли́ Си́на Твоєго́, да сохрани́ть нас от вся́кой біди́ і печа́лі, гні́ва і воздиха́нія, да ниспо́слеть нам мир в сердця́ на́ша; да да́руєть нам, єли́ко про́сим у Него́, коєму́ждо по своє́й потре́бі і покри́єть нас Своє́ю неісчерпа́ємою ми́лостію. Ми же, ча́юще Твоєго́ всеси́льнаго заступле́нія, велича́єм душе́ю на́шего Го́спода і вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Па́стирем, стрегу́щим стра́жу нощну́ю, А́нгел Госпо́день благовіствова́ ра́дость ве́лію: я́ко роди́ся Христо́с Госпо́дь во гра́ді Дави́дові, Вифлеє́мі, пови́т і в я́слех положе́н. О, Пречи́стая Ма́ти, ро́ждшая Си́на Твоєго́ Пе́рвенця, прийми́ от нас сицева́я:","Ра́дуйся, Ді́во Богоро́дице, я́ко Тобо́ю возсія́ ми́рові Світ ра́зума незаходи́мий; ра́дуйся, Звіздо́, путь нам во тьмі указу́ющая.","Ра́дуйся, Заре́ та́їнственнаго дне; ра́дуйся, душ на́ших Возрожде́ніє.","Ра́дуйся, в ско́рбіх ві́рноє Прибі́жище і ско́рая Помо́щнице; ра́дуйся, кри́не ра́йський.","Ра́дуйся, Ді́во Всепі́тая; ра́дуйся, Голуби́це кро́ткая, Ми́лостиваго ро́ждшая.","Ра́дуйся, Ма́ти Бо́жия, Цві́те Неув'яда́ємий."]},{"h":"Кондак 5","ps":["Се гряде́ть Цар ми́ра, Се Же́ртва та́йная соверша́ється; а́нгели пою́ть на небесі́х: сла́ва в ви́шніх Бо́гу! Ражда́ється Спаси́тель ми́ра. Христо́с прихо́дить, вели́кая Бо́же́ственная та́йна. Бог яви́лся во пло́ті, і ми, недосто́йнії раби́, отложи́в вся́коє жите́йськоє попече́ніє, со а́нгели Бо́га славосло́вим во стра́сі і ра́дості, я́ко па́стирі і я́ко волсви́, покланя́ємся Тебі́, о, Богома́ти, і Твоєму́ Бо́же́ственному Си́ну непреста́нно зове́м: Аллилу́я."]},{"h":"Ікос 5","ps":["Се пра́ведний Симео́н при́йде ду́хом в це́рков і приє́м Отроча́ Ісу́са на ру́ці свої́, і благослови́ Бо́га, і рече́: ни́ні отпуща́єши раба́ Твоєго́, Влади́ко, по глаго́лу Твоєму́, с ми́ром! А Тебі́, о, Ма́ти Марі́є, ору́жіє про́йдеть ду́шу, я́ко откро́ються от мно́гих серде́ць помишле́нія. Ми же, спасе́ннії Тобо́ю, вопіє́м:","Ра́дуйся, Преблагослове́нная, в ра́дость печа́ль ве́лію приводя́щая; ра́дуйся, любве́ і ні́жности Матери́нськия ві́чний кла́дезю.","Ра́дуйся, Ма́ти Бо́га на́шего, велича́йшія ра́дості і велича́йшую скорб о Си́ні Своє́м претерпі́вшая.","Ра́дуйся, Цари́це ми́ра; ра́дуйся, пла́чущим Наде́ждо і Утіше́ніє.","Ра́дуйся, Ма́ти Бо́жия, Цві́те Неув'яда́ємий."]},{"h":"Кондак 6","ps":["О, Преблага́я Ма́ти Марі́є! С бу́рей і гні́вом вздима́ється жите́йськоє мо́ре, глубо́кія бе́здни разверзо́шася і гото́ві нас поглоти́ти; се́рдце на́ше трепе́щеть, омраче́на на́ша ра́дость, но Ти, о, Кро́ткая і Ми́лостивая, умоли́ Си́на Твоєго́, да помо́жеть нам, ско́рбним і си́рим, в печа́лех на́ших; да укроти́ть м'яте́жния во́лни гріхо́вних страсте́й; да отврати́ть от нас вся́кую біду́ і опа́сность; да научи́ть нас, ка́ко соблюсти́ Єго́ ві́чную пра́вду. А при кончи́ні жи́зні на́шея укажи́ нам ти́хую при́стань і сподо́би нас с Симео́ном Богопри́їмцем возопи́ти: ни́ні отпуща́єши раба́ Твоєго́, Влади́ко! Помози́ же нам, о, Неув'яда́ємий Цві́те! Не оста́ви нас і спаси́ зову́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Отроча́ растя́ше і кріпля́шеся ду́хом і благода́тію, і Ти, о, Ма́ти Єго́, с любо́вію слага́ла вся глаго́ли о Си́ні в се́рдці Своє́м. Ско́рбна і печа́льна і́щуще Єго́, і в дружи́ні, і во сро́дниціх і зна́ємих, єгда́ возвраща́шеся с пра́зднества Ієрусали́мськаго, і с ра́достію ве́лією обрі́тши Єго́, в це́ркві сідя́ща посреді́ учи́телей, І́же дивля́хуся і ужаса́хуся о Боже́ственнім Єго́ ра́зумі. О, Пречи́стая Кро́тосте на́ша! О, сладча́йшеє Се́рдце, любо́вію весь мир согріва́ющеє! Усли́ши нас, вопію́щих Ті такова́я:","Ра́дуйся, Боже́ственнаго Си́на любо́вію возрасти́вшая; ра́дуйся, Се́рдце сладча́йшеє, любо́вію согріва́ющеє на́ша хла́дния ду́ші.","Ра́дуйся, Руководи́тельнице му́драя роди́тельских серде́ць; ра́дуйся, Стіно́ Неруши́мая на́шим ча́дом і отроко́м.","Ра́дуйся, си́рим і безпомо́щним Покро́в і Прибі́жище в ско́рбіх; ра́дуйся, цілому́дрія і ді́вства Храни́тельнице.","Ра́дуйся, муже́м кро́тким путь честни́й і пра́вий указу́ющая; ра́дуйся, Ум'ягче́ніє злих серде́ць.","Ра́дуйся, Умиле́ніє благи́х.","Ра́дуйся, Ма́ти Бо́жия, Цві́те Неув'яда́ємий."]},{"h":"Кондак 7","ps":["Ча́до! Что сотвори́ нам? Та́ко вопроша́ше Си́на Своєго́ Ісу́са і удивля́яся, зря́ще Єго́ сідя́щим во хра́мі посреді́ прего́рдих і суєму́дрих первосвяще́нников іуде́йських, Бо́же́ственний ра́зум, Боже́ственноє открове́ніє їм открива́ющаго. О, снизойди́ же, Всеблага́я Ма́ти, і к на́шим ча́дом; помоли́ся о них Си́ну Твоєму́ і Бо́гу на́шему, да откро́єть їм Світ і́стиннаго Богопозна́нія; покри́й їх кра́єм Твоєго́ благоуха́ннаго покро́ва; на́ша си́ни і дще́рі просвіти́ сві́том ра́зума; укріпи́ їх си́ли тіле́сния і душе́вния; соблюди́ їх в стра́сі Бо́жиєм, в послуша́нії роди́телем і в чистоті́ душе́вній; сподо́би їх возрасти́ на сла́ву Бо́гу і на сча́стіє землі́ отце́в на́ших. О, Світи́льниче любве́ неугаси́мий, ума́сти їх єле́єм ми́лости Твоєя́, согрі́й їх кро́тостію оче́й Твої́х, осіни́ їх ри́зою Своєго́ Ма́тери́нства. О, Цві́те Неув'яда́ємий! С крі́пкою ві́рою, непоколеби́мою наде́ждою і вели́ким сокруше́нієм се́рдця припа́дши к нога́м Твої́м, непреста́нно вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Хода́тайце те́плая за род прелюбоді́йний і грі́шний! По глаго́лу Твоєму́ на бра́ці в Ка́ні Галиле́йстій Син Твой і Бог наш сотвори́ нача́ток зна́менієм і претвори́ во́ду в вино́. Упроси́ же, о, Ма́тер Бо́жия, і ни́ні Си́на Твоєго́, да сотвори́ть і над на́ми чу́до, да претвори́ть ско́рбния дні на́ша, пови́тия ло́ж'ю, оби́дою і слеза́ми, в ра́дость возрожде́нія, в сча́стіє любве́ і пра́вди, да укріпи́ть в нас нача́ло Боже́ственнаго Сві́та, істо́чник чи́стий Ду́ха Бо́га Свята́го, Триєди́наго. Все же лука́воє і нечи́стоє да ізжене́ть із се́рдця на́шего. О, Чистоте́ недосяга́ємая і Милосе́рдіє неізрече́нноє! Приклони́ у́хо Твоє́ к моли́тві на́шей і сподо́би нас зва́ти си́це:","Ра́дуйся, лучеза́рний Сві́те любве́ і всепроще́нія; ра́дуйся, Сосу́де Бо́же́ственний ві́чнаго блаже́нства.","Ра́дуйся, за всіх нас усе́рдная пред Го́сподом Моли́твеннице; ра́дуйся, ну́жди на́ша ско́ро ко Престо́лу Бо́жию вознося́щая.","Ра́дуйся, я́ко по глаго́лу Твоєму́ Син Твой твори́ть зна́менія, да́руя ра́дость челові́ком.","Ра́дуйся, Ма́ти Бо́жия, Цві́те Неув'яда́ємий."]},{"h":"Кондак 8","ps":["Любве́ ність, пра́вда ісчезе́, лож і вражда́, гнів і не́нависть посі́яні в се́рдці людсько́є. Брат возстає́ть на бра́та, ча́да на роди́телей і роди́телі на ча́да. О, Милосе́рдий Бо́же! Кто оскверни́ ди́вную жа́тву Твою́, кто всі́я среді́ пшени́ці пле́вели і волчці́? Гнів Твой пра́веден, уже́ і сіки́ра при ко́рні, но се к Тебі́ припа́даєть Ма́тер Твоя́, усе́рдная Засту́пниця ми́ра. О, велича́йшая Любве́ і благоуха́ннійшеє се́рдце! Отврати́ от нас гнів Бо́жий, за гріхи́ на́ша пра́ведно на нас дви́жимий; укріпи́ лю́б'ящия нас, да не поколе́блеть їх ні гоне́ніє, ні вре́м'я лю́тоє; вразуми́ ненави́дящих нас і творя́щих нам напа́сть; прости́ враго́в на́ших, не ві́дущих что творя́ть, см'ягчи́ гні́вноє се́рдце їх і озари́ їх мрак сві́том любве́ Христо́вой, а зло́бу і не́нависть їх претвори́ в стид і раска́яніє. О, Цві́те благоуха́нний! Сосу́ди на́ші пу́сті, єле́я до́брих діл ність у нас і світи́льники ві́ри на́шея от бу́рі жите́йськой угаса́ють. Умилосе́рдися же над на́ми, напо́лни сердця́ на́ша весе́лієм чи́стих ра́достей, духо́вно обнови́ нас, да благода́рними уста́ми непреста́нно с умиле́нієм поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бив в ни́жніх і Ви́шніх ніка́коже не отступа́єши, Бо́же́ственний Учи́телю: боля́щия ісціля́єши, ме́ртвия воскреша́єши, прокаже́нния очища́єши, весь мир наполня́ющи любо́вію, кро́ткий Страда́льче! Се ви́сиши, пригвожде́нний ко Кресту́ среді́ злоді́єв, і всі лю́діє, стоя́ще, руга́хуся над Тобо́ю і с ни́ми кня́зі і во́їни. А Ти, о, ско́рбная Ма́ти, пони́кла главо́ю у Креста́ Си́на Твоєго́, і ору́жіє про́йде Твоє́ Ма́тернеє се́рдце. Ми же, почита́я ско́рбі матери́нськаго се́рдця Твоєго́, із глубини́ душі́ вопіє́м Ті си́це:","Ра́дуйся, сладча́йшая Ді́во Марі́є, я́ко печа́ль Твоя́ в ра́дость бу́деть і ра́дости сія́ нікто́же во́зьметь от Тебе́; ра́дуйся, велича́йшія му́ки позна́вшая, зря Си́на Твоєго́ Кро́вію істека́юща на Кресті́, унічиже́на, ра́сп'ята, оплева́на.","Ра́дуйся, я́ко Цари́ця ми́ра нарече́шися і возся́деши одесну́ю Престо́ла Си́на Твоєго́ і Бо́га, Го́спода на́шего Ісу́са Христа́; ра́дуйся, я́ко в ско́рбі се́рдця Твоєго́ Ти скорб всего́ ми́ра і гріхи́ всіх челові́ков оми́ла єси́ слеза́ми.","Ра́дуйся, Кро́ткая, Син Твой воскре́снеть, попра́в жа́ло сме́рти, і світ воскре́се́нія Єго́ возсія́єть во ві́ки; ра́дуйся, Богоро́дице, небе́сний о́бразе чистоти́ і бла́гости.","Ра́дуйся, Ма́ти Бо́жия, Цві́те Неув'яда́ємий."]},{"h":"Кондак 9","ps":["Та́ко возлюби́ Бог мир, что Си́на Своєго́ Єдиноро́днаго дал, да всяк ві́рующий в Него́ не поги́бнеть, но і́мать жизнь ві́чную. І се неблагода́рния і злонра́вния лю́ди я́ко злоді́я пригвозди́ша Єго́ ко Кресту́. Ми же, зря́ще такова́я, у́жасом об'я́ті би́вше, вопіє́м: Бо́же, ми́лостив бу́ди нам, грі́шним! За на́ша бо прегріше́нія терпи́ши стра́шния му́ки. О, ско́рбная Ма́ти, не отврати́ лиця́ Твоєго́ от нас, разорви́ у́зи на́ша гріхо́вния, очи́сти на́ша сердця́ от страсте́й і по́хотей лука́вих, да в горі́нії духо́внім, я́ко свіща́ покая́нія, возжже́мся пред Кресто́м Боже́ственнаго Твоєго́ Си́на, непреста́нно моля́ с благоразу́мним разбо́йником: пом'яни́ нас, Го́споди, во Ца́рствії Твоє́м! Моли́твами Твої́ми, Богоро́дице, іспра́ви стопи́ на́ша к ді́ланію за́повідей Госпо́дніх, оми́й нас от гріха́, соді́лай лу́чшими, подими́ к лучеза́рному Незаходи́мому Сві́ту, да зове́м Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Соверши́шася! О́тче, в ру́ці Твої́ предаю́ дух мой. о, Пречи́стая Ма́ти! Сли́шиши ли, я́ко земля́ от печа́лі содрога́ється, грудь єя́ распада́ється, гро́би отверза́ються, ме́ртвия возстаю́ть і церко́вная заві́са раздира́ється? Ви́диши ли, я́ко вели́кая тьма об'я́ла зе́млю і лю́діє в стра́сі і тре́петі, пе́рси своя́ бію́ще, глаго́лють: воі́стину Бо́жий Син бі Сей! Ми же таково́му чудеси́ удивля́яся і воі́стину Си́на Твоєго́ Си́на Бо́жия іспові́дающе, ві́рно вопіє́м Ті:","Ра́дуйся, Ма́ти Бо́жия, се бо всі глаго́ли, я́же слага́ла єси́ в се́рдці Твоє́м, соверши́шася; ра́дуйся, Благода́тная Ді́во, Заре́ неме́ркнущая, Дне незаходи́мий, Сві́те златоза́рний.","Ра́дуйся, Заре́ немерца́ющаго Сві́та невече́рняго; ра́дуйся, Святи́лище вели́кия Та́йни.","Ра́дуйся, Істо́чниче на́шего безсме́ртія; ра́дуйся, Пода́тельнице Бо́же́ственния бла́гости.","Ра́дуйся, Ма́ти Бо́жия, Цві́те Неув'яда́ємий."]},{"h":"Кондак 10","ps":["Да молчи́ть вся́кая плоть челові́ча і да стої́ть со стра́хом і тре́петом, і нічто́же земно́є в себі́ да помишля́єть. Се бо за гріхи́ ми́ра прино́ситься вели́кая же́ртва, се Спаси́тель ми́ра благообра́зним Іо́сифом во гро́бі но́вом полага́ється і повива́ється чи́стою плащани́цею. Душе́ю же Своє́ю восхо́дить во ад сокруши́ти вереї́ ві́чния і ізвісти́ на свобо́ду от ві́ка св'я́занния; із гро́ба же Своєго́ провіща́єть Ма́тері Своє́й: не рида́й Мене́, Ма́ти, зря́щи во гро́бі, Єго́же во чре́ві без сі́мене зачала́ єси́ Си́на; воста́ну бо і просла́влюся, і вознесу́ со сла́вою непреста́нно я́ко Бог, ві́рою і любо́вію Тя велича́ющия. Отложі́м все земно́є і су́єтноє і с чи́стим се́рдцем припаде́м ко Престо́лу Царя́ Сла́ви, непреста́нно вопія́: Свят, Свят, Свят Госпо́дь Савао́ф! О, Ма́ти на́шего спасе́нія! Сотвори́ і нас прича́стниками сві́тлаго воскре́се́нія Си́на Твоєго́ і ві́чнаго блаже́нства, да зове́м Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Во єди́ну от субо́т, зіло́ ра́но прийдо́ша жени́ на гроб, нося́ще арома́ти, і се, прише́дше, зрять: ка́мень отвале́н от гро́ба і ність тілесе́ Го́спода Ісу́са. А́нгел же к ним сві́тло блиста́яся, глаго́ля: о, жени́! Не бо́йтеся і не іщі́те жива́го с ме́ртвими; Христо́с бо воскре́се, я́коже і рече́! Тебі́ же, о, Влади́чице, научи́ вся приглаша́ти си́це:","Ра́дуйся, Благослове́нная Богоро́дице Ді́во, і па́ки реку́: ра́дуйся, Син бо Твой воскре́се тридне́вен от гро́ба; ра́дуйся, я́ко вся земля́ лику́єть і всі а́нгели пою́ть на небесі́: Христо́с воскре́се із ме́ртвих, сме́ртію смерть попра́в, і нам всім, і су́щим во гробі́х живо́т дарова́в!","Ра́дуйся, Пода́тельнице жи́зні ві́чния несконча́ємия; ра́дуйся, я́ко Твоє́ю любо́вію і Твої́ми моли́твами ізба́вихомся мра́ка ві́чнаго.","Ра́дуйся, я́ко Тобо́ю возсія́ нам сві́тлий пра́здников пра́здник; ра́дуйся, я́ко Тобо́ю наста́ нам сві́тлий день, во́ньже друг дру́га оби́мем, прості́м вся воскресе́нієм, возра́дуємся і возвеселі́мся ра́достію ві́чною.","Ра́дуйся, Ма́ти Бо́жия, Цві́те Неув'яда́ємий."]},{"h":"Кондак 11","ps":["О, Ієрусали́ме, Ієрусали́ме, ізби́вий проро́ки! Тя́жкоє твоє́ злодія́ніє прощено́ у Го́спода, і над ми́ром возсія́ло Со́лнце пра́вди незаходи́моє. Очи́сти же і на́ша ду́ші, кро́ткая Ді́во! Очи́сти на́ша чу́вствія, да у́зрим Христа́ із гро́ба ісходя́ща; оді́нь нас в бра́чния оде́жди, да с ра́достію вни́дем в украше́нний черто́г Христо́в, пою́ще Єму́ Воскре́сшему: Аллилу́я."]},{"h":"Ікос 11","ps":["Єгда́ прибли́зися час Твоєго́ к Бо́гу отше́ствія, о, Богома́ти Ді́во, па́ки а́нгел Госпо́день Гавриї́л, сві́тло блиста́яся, предста́ пред Тобо́ю, вручи́в Тебі́ сві́тлий, неув'яда́ємий рая́ крин, і се Ти со смире́нієм і ра́достію прия́ла єси́ во́лю Госпо́дню і ти́хо отошла́ к Бо́же́ственному Твоєму́ Си́ну. О, неуста́нная Моли́твеннице на́ша! О, Неув'яда́ємий Цві́те сві́тлаго рая́ Небе́снаго! Ниспосли́ і нам, Милосе́рдая, ти́хий і безболі́зненний ухо́д із сей юдо́лі пла́ча, воздиха́ній і скорбе́й, да вопіє́м Тебі́ такова́я:","Ра́дуйся, вознесе́нная на не́бо Си́ном Твої́м, Цари́це Небе́сная; ра́дуйся, ско́рая і ві́рная пред Ним на́ша Помо́щнице і Заступле́ніє.","Ра́дуйся, Всепі́тая Ді́во, і́бо і́м'я Твоє́ неув'яда́ємо красу́ється і ублажа́ється із ро́да в род; ра́дуйся, в бу́ріх жите́йських наде́жноє на́ше і ти́хоє Приста́нище.","Ра́дуйся, Обра́дованная, во успе́нії Твоє́м нас не оставля́ющая.","Ра́дуйся, Ма́ти Бо́жия, Цві́те Неув'яда́ємий."]},{"h":"Кондак 12","ps":["О, стра́шний послі́дній час наш! Се́рдце і всі у́ди трепе́щуть, єгда́ то́лько помишля́єм о нем! Ка́ко оста́вим си́рими на́ша сро́дники і люби́мия? Ка́ко по́йдем неуми́тнії посреді́ тьми і сі́ні сме́ртния к но́вой жи́зні? Ка́ко предста́нем на Стра́шний Суд Творця́ і Бо́га? О, на́ша Уті́шительнице! О, до́брая на́ша Помо́щнице! Помози́ нам, єгда́ наста́неть сіє́, руку́ лю́б'ящую Свою́ Ма́тери́нськую положи́ на чело́ на́ше, да ути́хнуть на́ша страда́нія і душа́ на́ша возроди́ться, умири́ тоску́ разлуче́нія на́шего с ми́ром сим, і світ ві́чной пра́вди да возсія́єть пред на́шими оча́ми. О, Пречи́стая Ма́ти! На Тебе́ наді́ємся, Тебі́ мо́лимся і вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["О, душе́ моя́, душе́ моя́! Возста́ни, что спи́ши? Коне́ць приближа́ється! Почто́ гріха́ми богаті́єши? Почто́ неради́ши, не гото́вишися? Госпо́дь при две́рех, в чесо́м наде́жду полага́єши? Кий отві́т проглаго́леши Го́сподеві, єгда́ при́йдеть Он, гро́зний Судія́, суди́ти зе́млю? Ні часа́, ні дне сего́ не ві́си, от кра́я земна́го і до кра́я звучи́ть труба́ арха́нгельськая, і ме́ртвії возстаю́ть, і собира́ються всі язи́ци. І се гряде́ть Син Челові́чеський на о́блаціх с си́лою Своє́ю, во всей сла́ві своє́й. Гді на́ша до́брия діла́? Гді милосе́рдіє? Гді любо́в? Прегріше́ній же на́ших неісчерпа́ємоє мно́гоє мно́жество закри́ша не́бо. О, Всеми́лостивая Богоро́дице! В сей стра́шний день предста́ни нам і бу́ди хода́тайця за нас пред Си́ном Твої́м. На Тебе́ єди́ну наді́ємся, не оста́ви нас грі́шних. Бу́ди нам защи́тою і укріпле́нієм, с те́плою ві́рою і несомні́нною наде́ждою припа́даєм к Пречи́стому Твоєму́ о́бразу і со слеза́ми зове́м такова́я:","Ра́дуйся, Мо́лніє, тьму на́шу освіща́ющая. Ра́дуйся, на Стра́шнім Суди́щі Христо́вом за нас заступа́ющая.","Ра́дуйся, Свої́м омофо́ром весь мир от бід і скорбе́й покрива́ющая; ра́дуйся, я́ко єси́ мир Тебі́ єди́ной Ма́тері усинови́ся.","Ра́дуйся, я́ко Тебі́ єди́ной неізрече́нная благода́ть моли́тися о нас даде́ся; ра́дуйся, всім ві́рним Свої́м ча́дом ві́чную ра́дость уготовля́ющая.","Ра́дуйся, Цві́том свої́м Неув'яда́ємим нас, грі́шних, на ві́ки благоуха́ющая.","Ра́дуйся, Ма́ти Бо́жия, Цві́те Неув'яда́ємий."]},{"h":"Кондак 13","ps":["О, Неув'яда́ємий Цві́те! О, Всепі́тая Ма́ти Марі́є, ро́ждшая всіх святи́х Святі́йшеє Сло́во! Ни́нішнєє прийми́ на́ше приноше́ніє, от вся́кия ізба́ви напа́сти всіх. Согрі́й Ма́тери́нською любо́вію, возвесели́ нас ві́чною ра́достію. Спаси́ от ві́чних мук непреста́нною к Си́ну Твоєму́ моли́твою і Небе́снаго Ца́рствія нас, Цари́це, сподо́би, о Тебі́ вопію́щих: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Молитва","ps":["О, Пресвята́я і Пренепоро́чная Ма́ти Ді́во, Наде́ждо христия́н і Прибі́жище грі́шним! Защити́ всіх, в несча́стіях к Тебі́ прибіга́ющих, усли́ши стена́нія на́ша, приклони́ у́хо Твоє́ к моле́нію на́шему. Влади́чице і Ма́ти Бо́га на́шего, не пре́зри тре́бующия Твоєя́ по́мощі і не отри́ни нас, грі́шних, вразуми́ і научи́ нас, не отступи́ от нас, рабо́в Твої́х, за ропта́ніє на́ше. Бу́ди нам Ма́ти і Покрови́тельниця, вруча́єм себе́ ми́лостивому покро́ву Твоєму́. Приведи́ нас, грі́шних, к ти́хой і безм'яте́жной жи́зні, да опла́чем гріхи́ на́ша. о, Ма́ти Марі́є, на́ша Преблага́я і ско́рая Засту́пнице, покри́й нас Свої́м хода́тайством, защити́ от враг ви́димих і неви́димих, ум'ягчи́ сердця́ злих люде́й, возстаю́щих на нас. О, Ма́ти Го́спода Творця́ на́шего! Ти єси́ Ко́рень Ді́вства і Неув'яда́ющий Цвіт чистоти́ і цілому́дрія, посли́ по́мощ нам, немощни́м і обурева́ємим плотськи́ми страстьми́ і блужда́ющим сердця́ми. Просвіти́ на́ші душе́вния о́чі, да ви́дим путі́ пра́вди Бо́жия. Благода́тію Си́на Твоєго́ укріпи́ на́шу сла́бую во́лю во ісполне́ніє за́повідей, да ізба́вимся от вся́кия біди́ і напа́сти і оправда́ні бу́дем Твої́м пречу́дним заступле́нієм на Стра́шнім Суді́ Си́на Твоєго́, Єму́же ми воздає́м сла́ву, честь і поклоне́ніє, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Акафіст Господу Богу про мир і взаємну любов серед людей","e":"Akathist to the Lord God for peace and mutual love among people","secs":[{"h":"Кондак 1","ps":["Возбра́нний Воєво́до і Созда́телю ми́ра, усли́ши на́с, грі́шних, моля́щихся Тебі́, Творцю́ і Промисли́телю на́шему. При́зри с висоти́ свята́го жили́ща Твоєго́ на ізсо́хшия от не́нависти сердця́ на́ша і обнови́ я́ благода́тію Пресвята́го Твоєго́ Ду́ха, да і ми́, Благоді́телю і Влади́ці жи́зні на́шея, зове́м Ті́:","Бо́же, Істо́чниче ми́ра і любве́, водрузи́ ми́р і любо́в в сердця́х на́ших."]},{"h":"Ікос 1","ps":["А́нгелов Тво́рче, вели́кий і всемогу́щий Бо́же на́ш, Ти́ покори́л єси́ под но́зі Своя́ вся́ стихі́ї, Ти́ єди́ним сло́вом Свої́м запрети́л єси́ бу́рі і повелі́л єси́ би́ти тишині́ на є́зері Геннисаре́тстім. Див’я́щеся Твоєму́ всемогу́ществу, Тебі́, Влади́ці Ми́ра, взива́єм такова́я:","Бо́же, Істо́чниче ми́ра і любве́, ороси́ ка́плею благода́ті Свята́го Твоєго́ Ду́ха лю́тия оледені́вшия сердця́ на́ша.","Бо́же, Істо́чниче ми́ра і любве́, возрасти́ в сердця́х люде́й Твої́х доброді́тель кро́тости і смире́нія.","Бо́же, Істо́чниче ми́ра і любве́, іскорени́ в на́с многообра́зноє лука́вство і лицемі́ріє.","Бо́же, Істо́чниче ми́ра і любве́, водрузи́ ми́р і любо́в в сердця́х на́ших."]},{"h":"Кондак 2","ps":["Вседержи́телю і Спаси́телю на́ш, не оста́ви на́с, сиро́т, но воньми́ моле́нію на́шему, с ві́рою зову́щих Ті́: Аллилу́я."]},{"h":"Ікос 2","ps":["Рече́ Госпо́дь Свої́м ученико́м: «За́повідь но́вую даю́ ва́м, да лю́бите дру́г дру́га; я́коже возлюби́х ви́, да і ви лю́бите себе́». І ми́ со умиле́нієм взива́єм Ті́:","Бо́же, Істо́чниче ми́ра і любве́, ми́р ми́рові Твоєму́ да́руй.","Бо́же, Істо́чниче ми́ра і любве́, А́нгела ми́рнаго, ві́рнаго на́шего наста́вника, пошли́ лю́дем Твої́м.","Бо́же, Істо́чниче ми́ра і любве́, распали́ огне́м благода́тния любве́ і ми́ра ду́ші і сердця́ на́ша.","Бо́же, Істо́чниче ми́ра і любве́, во́лю на́шу напра́ви уклоня́тися от зла́ і твори́ти благо́є.","Бо́же, Істо́чниче ми́ра і любве́, водрузи́ ми́р і любо́в в сердця́х на́ших."]},{"h":"Кондак 3","ps":["Си́лою облече́нния сви́ше, святі́ї учени́ці Твої́ і апо́столи, ше́дше в ми́р і пропові́дуя Свято́є Єва́нгеліє любве́ і ми́ра, с ра́достію взива́ють Ті́: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яй бога́тство любве́ і милосе́рдіє неізрече́нноє, Го́споди Бо́же на́ш, отврати́ раздо́ри от на́с, призива́ющих і́м’я Госпо́днє, і пода́ждь ско́роє примире́ніє лю́дем Твої́м. Напо́лни сердця́ на́ша теплото́ю любве́ Твоєя́, да і ми́, ра́ди сла́ви свята́го і́мені Твоєго́, Тебі́, Спаси́телю і Бо́гу на́шему, прино́сим сицева́я:","Бо́же, Істо́чниче ми́ра і любве́, ізба́ви на́с от за́висти, гні́ва і братоненавиді́нія.","Бо́же, Істо́чниче ми́ра і любве́, благода́ть Го́спода на́шего Ісу́са Христа́ і люби́ Бо́га і Отця́ да бу́дуть с на́ми.","Бо́же, Істо́чниче ми́ра і любве́, умири́ на́шу жи́знь і ми́р Тво́й, і поми́луй на́с.","Бо́же, Істо́чниче ми́ра і любве́, водрузи́ ми́р і любо́в в сердця́х на́ших."]},{"h":"Кондак 4","ps":["Бу́рю я́рости і негодова́нія отжени́ от на́с, Человіколю́бче Го́споди, і научи́ ни єди́ними усти́ і єди́ним се́рдцем взива́ти Ті́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша святі́ї учени́ци Твої́ глаго́ли із Пречи́стих у́ст Твої́х: «Імі́яй за́повіді Моя́ і соблюда́яй я, то́й є́сть люб’я́й М’я, а люб’я́й М’я́ возлю́блен бу́деть Отце́м Мої́м». Ми́ же, удивля́ющеся неізрече́нной любві́ і за́повідем Твої́м, дерза́єм пі́ти Тебі́:","Бо́же, Істо́чниче ми́ра і любве́, очи́сти і на́с от гріхо́в на́ших, ізсуша́ющих в на́с і́скреннюю любо́в.","Бо́же, Істо́чниче ми́ра і любве́, те́плую любо́в к Тебі́ пода́ждь на́м і і́скреннюю в на́с благода́ть Пресвята́го Ду́ха.","Бо́же, Істо́чниче ми́ра і любве́, во́ду із ка́мня в пусти́ні істочи́вий, істочи́ із серде́ць на́ших человіколю́біє і милосе́рдіє.","Бо́же, Істо́чниче ми́ра і любве́, от всі́х душе́вних страсте́й невреди́мо соблюди́ ни́.","Бо́же, Істо́чниче ми́ра і любве́, водрузи́ ми́р і любо́в в сердця́х на́ших."]},{"h":"Кондак 5","ps":["Спа́се на́ш, Бо́же ми́ра і любве́, ми́р оста́вивий лю́дем, посіти́ лю́ди Твоя́ ми́ром, да благодари́м Тя́, всі́м се́рдцем зову́ще: Аллилу́я."]},{"h":"Ікос 5","ps":["Влади́ко Небесе́ і землі́, чу́дний Бо́же, О́тче щедро́т, приста́нище милосе́рдія і человіколю́бія, неістощи́мий Істо́чниче прему́дрості, вся́ содержа́й в десни́ці Своє́й, Диха́ніє всі́х живи́х, Єго́же послу́шають і зві́зди, Ти́ у́бо, Со́лнце ми́ра і любве́, пощади́ наслі́діє Твоє́, при́зри на лю́ди Твоя́ согріши́вшия і із глубини́ се́рдця зову́щия:","Бо́же, Істо́чниче ми́ра і любве́, да́руй на́м ни́ні возлюби́ти Тя́ всі́м се́рдцем і все́ю душе́ю.","Бо́же, Істо́чниче ми́ра і любве́, да́руй на́м возлюби́ти дру́г дру́га сло́вом і і́стиною.","Бо́же, Істо́чниче ми́ра і любве́, смири́ окамені́вшия сердця́ на́ша в нелицемі́рній любві́ дру́г ко дру́гу.","Бо́же, Істо́чниче ми́ра і любве́, да́руй на́м в любві́ і благоче́стії пожи́ти вся́ дні́ живота́ на́шего.","Бо́же, Істо́чниче ми́ра і любве́, водрузи́ ми́р і любо́в в сердця́х на́ших."]},{"h":"Кондак 6","ps":["Поми́луй на́с, Го́споди, поми́луй на́с, взива́ющих к Тебі́: Аллилу́я."]},{"h":"Ікос 6","ps":["Вели́кий єси́ Го́споди, Ти́ возлюби́л єси ми́р, я́ко Си́на Своєго́ Єдиноро́днаго да́л єси́, да вся́к ві́руяй Вонь не поги́бнеть, но імі́єть жи́знь ві́чную. Ми́ же, упова́я на неізрече́нную любо́в і Твоє́ милосе́рдіє, дерза́єм пі́ти Ті́ такова́я:","Бо́же, Істо́чниче ми́ра і любве́, пода́ждь на́м милосе́рдіє і долготерпі́ніє.","Бо́же, Істо́чниче ми́ра і любве́, отими́ от на́с за́висть, го́рдость і помишле́нія о злі́.","Бо́же, Істо́чниче ми́ра і любве́, іскорени́ в на́с гніздя́щуюся па́губу самолю́бія – ко́рень всі́х зо́л – і іспо́лни ни ти́хим і ра́достним чу́вством братолю́бія.","Бо́же, Істо́чниче ми́ра і любве́, да́руй на́м зрі́ти согріше́нія на́ша і смиря́ти ся пред Тобо́ю; бра́та николи́же осужда́ти, но люби́ти єго́, я́ко сами́х себе́.","Бо́же, Істо́чниче ми́ра і любве́, водрузи́ ми́р і любо́в в сердця́х на́ших."]},{"h":"Кондак 7","ps":["Хвалі́те І́м’я Госпо́днє, хвалі́те раби́ Го́спода. Прийми́, Го́споди, моли́тви Тебе́ велича́ющих і взива́ющих Тебі́: Аллилу́я."]},{"h":"Ікос 7","ps":["«Да лю́бите дру́г дру́га; я́ко же А́з возлюби́х ви́, да ви́ лю́бите». Та́кожде велича́юще Твою́ неізрече́нную любо́в, дерза́єм Тебі́ взива́ти такова́я:","Бо́же, Істо́чниче ми́ра і любве́, св’яза́вий Твоя́ апо́столи сою́зом любве́, св’яжи́ і ни люби́ти нелицемі́рно дру́г дру́га.","Бо́же, Істо́чниче ми́ра і любве́, распали́ пла́менем любве́ сердця́ на́ша к Тебі́, Христе́ Бо́же на́ш, да ми́слею і все́ю крі́постію на́шею возлю́бим Тебе́ і і́скренняго своєго́, я́ко сами́х себе́.","Бо́же, Істо́чниче ми́ра і любве́, к братолю́бному доброжела́тельному жи́тельству наста́ви нас.","Бо́же, Істо́чниче ми́ра і любве́, сподо́би ни в согла́сном єдиноми́слії сла́вити і благодари́ти Тя́ Человіколю́бця.","Бо́же, Істо́чниче ми́ра і любве́, водрузи́ ми́р і любо́в в сердця́х на́ших."]},{"h":"Кондак 8","ps":["Сотвори́ с на́ми зна́меніє во бла́го, і да ви́дять ненави́дящії нас і постидя́ться, я́ко Ти, Го́споди, помо́гл єси́ нам. Тебі́, Промисли́телю на́шему і Пода́телю бла́г ві́чних, вопіє́м: Аллилу́я."]},{"h":"Ікос 8","ps":["Возлюблю́ Тя́, Го́споди, Крі́посте моя́. Госпо́дь утвержде́ніє моє́ і прибі́жище моє́. К Тебі́, Бо́гу моєму́ і Сві́ту І́стинному, воспіва́єм си́це:","Бо́же, Істо́чниче ми́ра і любве́, ороси́ на́с ка́плями Твоєго́ милосе́рдія і возвесели́ сердця́ на́ша.","Бо́же, Істо́чниче ми́ра і любве́, разбуди́ со́вість, сп’я́щую в на́с, і укріпи́ гла́с єя́.","Бо́же, Істо́чниче ми́ра і любве́, да́ждь на́м позна́ти си́лу любве́ Твоєя́ к па́дшему челові́ку.","Бо́же, Істо́чниче ми́ра і любве́, умудри́ ни би́ти провозві́стниками любве́ Твоє́я бра́тії на́шей.","Бо́же, Істо́чниче ми́ра і любве́, укра́си на́с цві́том і плода́ми благи́х чу́вств.","Бо́же, Істо́чниче ми́ра і любве́, водрузи́ ми́р і любо́в в сердця́х на́ших."]},{"h":"Кондак 9","ps":["Возлю́бим дру́г дру́га, да єдиноми́слієм вопіє́м Ті́: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́ї многовіща́нния, я́ко же ри́би безгла́сния не мо́гуть глаго́лати слове́с Твої́х: «А́ще за́повіді моя́ соблюде́те, пребу́дите в любві́ Моє́й, я́ко же і А́з за́повіді Отця́ Моєго́ соблюдо́х і пребива́ю в любві́ Єго́». Ми́ же воспіва́єм пі́снь любві́ Твоє́й:","Бо́же, Істо́чниче ми́ра і любве́, всі́м на́м ми́р подая́й.","Бо́же, Істо́чниче ми́ра і любве́, не терп’я́й вражду́, примири́ на́с всі́х, да в ра́дості Твоє́й пребу́дем.","Бо́же, Істо́чниче ми́ра і любве́, в пусти́ні наси́тивий наро́д п’ятьма́ хліба́ми, наси́ти і ни́ ми́ром і любо́вію.","Бо́же, Істо́чниче ми́ра і любве́, претворя́й во́ду і вино́ на бра́ці в Ка́ні Галиле́йстій, претвори́ не́нависть в любо́в в оледені́вших сердця́х на́ших.","Бо́же, Істо́чниче ми́ра і любве́, водрузи́ ми́р і любо́в в сердця́х на́ших."]},{"h":"Кондак 10","ps":["Спаси́, Бо́же, лю́ди Твоя́ і благослови́ достоя́ніє Твоє́, Тебі́ зову́щих: Аллилу́я."]},{"h":"Ікос 10","ps":["Царю́ Си́л, чистоти́ і цілому́дрія, Ісу́се Христе́, росо́ю сви́ше погаси́ пла́мень страсте́й на́ших, да чи́стим се́рдцем вопіє́м Ті́ хвале́бную пі́снь сію́:","Бо́же, Істо́чниче ми́ра і любве́, руко́ю свята́го А́нгела Твоєго́ отста́ви от на́с ду́ха горди́ні і за́висти.","Бо́же, Істо́чниче ми́ра і любве́, очи́сти сердця́ на́ша от помисло́в не́нависти.","Бо́же, Істо́чниче ми́ра і любве́, огради́ на́с святи́ми Твої́ми а́нгелами і крі́пким ї́х ополче́нієм.","Бо́же, Істо́чниче ми́ра і любве́, отими́ се́рдце ка́менноє от пло́ті на́шея і да́ждь на́м се́рдце, пила́ющеє любо́вію.","Бо́же, Істо́чниче ми́ра і любве́, водрузи́ ми́р і любо́в в сердця́х на́ших."]},{"h":"Кондак 11","ps":["Преклони́, Го́споди, у́хо Твоє́ і усли́ши ни́, із глубини́ се́рдця взива́ющих Тебі́: Аллилу́я."]},{"h":"Ікос 11","ps":["«Сла́ва в ви́шніх Бо́гу і на землі́ ми́р!» – воспі́ли а́нгели Тебі́, Рожде́нному Царю́ ми́ра і любве́, Спа́су ду́ш на́ших. І ми́ дерза́єм пі́ти Тебі́ сицева́я:","Бо́же, Істо́чниче ми́ра і любве́, із пла́мені ро́су істочи́вий, істочи́ ро́су любве́ із серде́ць на́ших.","Бо́же, Істо́чниче ми́ра і любве́, пода́ждь на́м ми́р і тишину́ в житії́ на́шем.","Бо́же, Істо́чниче ми́ра і любве́, глаго́ляй Свої́м ученико́м «Ми́р ва́м!», поcли́ і на́м ми́р Тво́й.","Бо́же, Істо́чниче ми́ра і любве́, посли́ на́м непрекраща́ємия струї́ любве́ Твоєя́.","Бо́же, Істо́чниче ми́ра і любве́, водрузи́ ми́р і любо́в в сердця́х на́ших."]},{"h":"Кондак 12","ps":["Го́споди Ісу́се Христе́ Бо́же на́ш, Істо́чниче ми́ра і любве́, благослови́ ми́ром лю́ди Твоя́, із глубини́ покая́нних серде́ць взива́ющих к Тебі́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пе́рвую і наібо́льшую за́повідь да́л єси́ на́м, є́же люби́ти Тя́, Бо́га і Творця́ на́шего, от всея́ душі́, все́ю крі́постею і всім помишле́нієм на́шим; і втору́ю, подо́бную є́й, є́же люби́ти бли́жняго, я́ко сами́х себе́. На си́х дву́х за́повідех зи́ждеться ве́сь Зако́н і Проро́ки. Вне́млюще се́рдцем вели́кую благода́ть слове́с Твої́х, зове́м Ті́ сицева́я:","Бо́же, Істо́чниче ми́ра і любве́, да́вий позна́ти на́м найбо́льшую за́повідь о любві́, даждь же позна́ти на́м найбо́льший і тягча́йший грі́х – не́нависть.","Бо́же, Істо́чниче ми́ра і любве́, угаси́ пла́мень не́нависти і преріка́нія на́шего.","Бо́же, Істо́чниче ми́ра і любве́, омо́й прока́зу вражди́ і очи́сти сердця́ на́ша.","Бо́же, Істо́чниче ми́ра і любве́, водрузи́ ми́р і любо́в в сердця́х на́ших."]},{"h":"Кондак 13","ps":["О, Всемогу́щий Бо́же, Промисли́телю на́ш, Істо́чниче жи́зні і бла́г Пода́телю! Прийми́ от всего́ се́рдця сіє́ моле́ніє і благодаре́ніє на́ше, Тебі́ приноси́моє. Усли́ши моли́тву на́шу і утоли́ раздо́ри, не́нависть, братоненавиді́ніє в душа́х на́ших. Пода́ждь ми́р, тишину́, любо́в, примире́ніє лю́дем Твої́м, да в ра́дості Тебі́, Бо́гу на́шему і Істо́чнику всего́ ми́ра і любве́, зове́м: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Тво́рче, вели́кий і всемогу́щий Бо́же на́ш, Ти́ покори́л єси́ под но́зі Своя́ вся́ стихі́ї, Ти́ єди́ним сло́вом Свої́м запрети́л єси́ бу́рі і повелі́л єси́ би́ти тишині́ на є́зері Геннисаре́тстім. Див’я́щеся Твоєму́ всемогу́ществу, Тебі́, Влади́ці Ми́ра, взива́єм такова́я:","Бо́же, Істо́чниче ми́ра і любве́, ороси́ ка́плею благода́ті Свята́го Твоєго́ Ду́ха лю́тия оледені́вшия сердця́ на́ша.","Бо́же, Істо́чниче ми́ра і любве́, возрасти́ в сердця́х люде́й Твої́х доброді́тель кро́тости і смире́нія.","Бо́же, Істо́чниче ми́ра і любве́, іскорени́ в на́с многообра́зноє лука́вство і лицемі́ріє.","Бо́же, Істо́чниче ми́ра і любве́, водрузи́ ми́р і любо́в в сердця́х на́ших."]},{"h":"Кондак 1","ps":["Возбра́нний Воєво́до і Созда́телю ми́ра, усли́ши на́с, грі́шних, моля́щихся Тебі́, Творцю́ і Промисли́телю на́шему. При́зри с висоти́ свята́го жили́ща Твоєго́ на ізсо́хшия от не́нависти сердця́ на́ша і обнови́ я́ благода́тію Пресвята́го Твоєго́ Ду́ха, да і ми́, Благоді́телю і Влади́ці жи́зні на́шея, зове́м Ті́:","Бо́же, Істо́чниче ми́ра і любве́, водрузи́ ми́р і любо́в в сердця́х на́ших."]},{"h":"Молитва преподобного Силуана Афонського за мир усього світу","ps":["Го́споди, даждь мир Твой лю́дем Твої́м! Го́споди, посли́ лю́дем Твої́м Ду́ха Твоєго́ Свята́го, да согрі́єть сердця́ їх любо́вію Твоє́ю і наста́вить я на вся́кую і́стину і бла́го.","Го́споди, да́ждь благода́ть Твою́, да в ми́рі і любві́ позна́ють Тя, і возлю́блять, і да реку́ть я́ко апо́столи на Фаво́рі: \"Го́споди, добро́ єсть нам зді би́ти\". Согрі́й дря́хлиє сердця́ люде́й, да в ра́дості возсла́влять Тя, заби́вшия земни́я ско́рбі.","Уті́шителю Благи́й, со слезьми́ прошу́ Тя: уті́ши дря́хлиє ду́ші люде́й Твої́х. Даждь всім язи́кам Твої́м позна́ти любо́в Твою́ і сла́дость Свята́го Ду́ха, да забу́дуть земну́ю го́ресть, отмету́ться зла́го і притеку́ть к Тебі́ с любо́вію, і да живу́ть в ми́рі, творя́ще во́лю Твою́ во сла́ву Твою́.","Го́споди Ми́лостивий, даждь благода́ть Твою́ всім язи́кам землі́, да позна́ють Тя Ду́хом Твої́м Святи́м. Амі́нь."]},{"h":"Молитва святителя Миколая Сербського про мир в усьому світі","ps":["Го́споди Бо́же наш, Влади́ко живота́ і сме́рти, Тво́рче не́бу і землі́, прийми́ благодаре́ніє на́ше за всі дари́, і́же Ти дає́ши нам в час сей. Дарова́ше і да́руєши при́сно вся, я́же никто́же не би могл нам пода́ти: здра́віє, ізоби́ліє плодо́в земни́х і вся насу́щная, битія́ на́шего ра́ди на землі́. Ду́хом Твої́м Святи́м вдухновля́єши і утвержда́єши ві́ру і́стую, святи́ши наде́жду, воспламеня́єши любо́в, ми́лостію ми́луєши, просвіща́єши і освяща́єши ду́ші люде́й Твої́х. Благодари́м Тя, я́ко мно́жеством ми́лости Твоєя́ покри́л єси́ поги́бельноє мно́жество гріхо́в челові́чеських — так, призира́юще на до́лги на́ша, єще́ не затвори́л єси́ не́бо над на́ми, не ізсуши́л єси́ о́блаки от дождя́, не запрети́л єси́ землі́ приноси́ти плоди́ і не повелі́л єси́ со́лнцю бо́ліє не світи́ти грі́шницям і беззако́ницям.","Но, о Всеблаги́й Царю́ і Го́споди, єди́наго насу́щнаго да́ра не хвата́єть нам ни́ні — ми́ра. То́го свята́го ми́ра, і́же дарова́ Твоїм вели́ким Апо́столом, глаго́ля: \"Мир вам! Мир оставля́ю вам, мир Мой даю́ вам!\" О сем ми́рі, о сем небе́сном дарова́нії, і́же в Твої́х рука́х і от Тя то́чію прийти́ мо́жеть, мо́лимся Тебі́, припа́дающе на колі́на. Ві́ми, Тво́рче наш, ві́ми я́ко не заслужи́ли ї́ єсьми́ і ні́сьми досто́йни сея́ ми́лости, но возлага́юще наде́жду на Твою́ безмі́рную бла́гость, з покая́нієм мо́лим Тя єди́наго: Да́руй ї́ нам, пода́ждь мир всім ві́рним Твої́м по землі́, да би́хом не поги́бли до конця́\". Го́споди, воста́ло і воскипі́ло мо́ре живота́ челові́чеськаго як нікогда́же пре́жде. Страх і волне́ніє воцари́шася среди́ серде́ць людськи́х. Вооружи́ся і воста́ брат на бра́та, сябр на ся́бра, язи́к на язи́к, ца́рствіє на ца́рство.","І се, род людсько́й стої́ть пред но́вой бра́нью, но́вим Каїнови́м гріхо́м, но́вим Іу́диним преда́тельством — пред бра́нью, воню́же попра́ні бу́дуть вся́ твоя́ за́повіді, і́м'я свято́є Твоє́ бу́деть уничиже́но, же́ртва Твоя́ бу́деть осмі́яна і любо́в Твоя́ свята́я к нам, грі́шним, ста́неть оглумлена́. О, Всемогу́щий Вседержи́телю, простри́ непобіди́мую Твою́ десни́цю і не ізво́ли би́ти сему́, воспрети́ сему́ си́лою Своє́ю і бла́гостію. Я́ко утихомири́л єси́ мо́ре Галиле́йськоє і Свої́м держа́вним сло́вом останови́л єси́ вітри́, вселя́ще мир і ра́дость в ду́ші ученико́в Твої́х, се і ни́ні утихоми́ри бу́рю в сердця́х люде́й і язи́ков, да вмі́сто стра́ха пред бра́нью возсія́єть в них ра́дость ми́ра. Сохрани́, Го́споди, ізбра́нних Твої́х от глумле́нія пред язи́ками, спаси́ охреще́нних люде́й і язи́ки Твої́ от подражне́нія сатани́ над созда́нієм руку́ Твоє́ю. Уми́лостивись над святи́ми Твої́ми А́нгели і не попусти́ ї́м вно́вь с го́рестію зрі́ти безбо́жниє діла́ христия́нських язи́ков. Уми́лостивись над Свої́ми святи́ми і пра́ведниками, і не пригоди́ їм ни́ні опуска́ти о́чі своя́, стидя́ся свої́х ю́жиків і сино́в на сей грі́шной землі́.","Се — бо́ліє ра́ди Сил Небе́сних, святи́х і пра́ведников на небеса́х, не́желі нас ра́ди — поми́луй нас, Многоми́лостиве. І любве́ ра́ди Пресвяти́я Твоєя́ Ма́тере, Богоро́диці, к Тебі́, Го́споди Ісу́се Христе́, і Це́ркві Твоє́й земно́й, Твоє́й ви́нной лозі́, удержи́ ру́ки на́ша от злодія́ній і ізба́ви ни от нас сами́х. Спаси́ на́шу со́вість і ду́ші, да і ми, свобожде́ннії ми́лостію Твоє́ю, смогли́ би́хом в час благоприя́тний умножи́ти святи́й наро́д Твой в безсме́ртном Ца́рствії ми́ра, сві́та і жи́зні, іді́же при́сно живе́ши і ца́рствуєши, Триєди́ний Бо́же наш. Тебі́ сла́ва і хвала́, благодаре́ніє і поклоне́ніє подоба́єть — от всіх святи́х Сил на небеса́х і всіх колі́н земни́х — во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Акафіст преподобному отцю нашому Сергію, ігумену Радонезькому, чудотворцю","e":"Akathist to our Venerable Father Sergius, Abbot of Radonezh, Wonderworker","secs":[{"h":"Кондак 1","ps":["Возбра́нний от Царя́ сил, Го́спода Ісу́са, воєво́до і чудотво́рче преди́вний, преподо́бне о́тче Се́ргіє! Прославля́юще просла́вльшаго тя сла́ви Го́спода, благода́рственноє пі́ніє воспіва́єм ті, і́бо моли́твами твої́ми от прило́гов і ско́рбних обстоя́ній нас при́сно ізбавля́єши, я́ко імі́я дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, да зове́м ті:","Ра́дуйся, Се́ргіє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць, предуві́дівий, по самовла́стному чи́стаго се́рдця твоєго́ ізволе́нію, всеусе́рдствующеє Єго́ во́лі ісполне́ніє, єще́ во чре́ві ма́терні трикра́тним возглаше́нієм, показа́ тя ми́ру і́стиннаго служи́теля би́ти Святи́я Тро́йці, і научи́ всіх вопи́ти тебі́ си́це:","Ра́дуйся, я́ко пре́жде вік і́маши ві́рний раб Христо́в би́ти предусмо́тренний; ра́дуйся, во о́ноже вре́м'я во блаже́нноє і небе́сноє жили́ще предуста́вленний.","Ра́дуйся, от чре́ва ма́терня на слу́жбу Небе́снаго Царя́, я́ко во́їн хотя́щий ві́рен Єму́ би́ти, призва́нний; ра́дуйся, я́ко благода́тію Бо́жиєю оправда́нний.","Ра́дуйся, ти бо єси́ по всей вселе́нній просла́вленний; ра́дуйся, трикра́тним твої́м во чре́ві возглаше́нієм роди́телей і всіх сли́шащих удиви́вий.","Ра́дуйся, по рожде́нії своє́м по́стноє і́ночеськоє житіє́ показа́вий; ра́дуйся, от сосця́ ма́терня воздержа́ніє чу́дноє яви́вий.","Ра́дуйся, я́ко в сре́ду і пято́к млека́ ніка́коже вкуси́вий; ра́дуйся, роди́телей благи́х до́брий і ізбра́нний пло́де.","Ра́дуйся, ра́дости скорб'я́щим і ми́лости с ві́рою у тебе́ прося́щим пода́телю; ра́дуйся, печа́лей злих во вся́ких приключе́ніїх отгони́телю.","Ра́дуйся, Се́ргіє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дящи вся страни́ да́нною тебі́, преподо́бне о́тче Се́ргіє, благода́тію Бо́жиєю, с ві́рою тебі́ приходя́щим, і ско́роє вспоможе́ніє, і при́сноє пресла́вноє чуде́с творе́ніє, удивля́ються. І ми всі веселя́щеся, я́ко імі́єм такова́го ми́лостиваго помо́щника, Просла́вльшаго тя прославля́юще, і тя, блага́го раба́ і ві́рнаго слугу́ Госпо́дня восхваля́юще, вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум, єще́ су́щу ті во чре́ві ма́терні, Святу́ю Тро́йцю просла́вити Ісу́с Христо́с дарова́вий, і ві́ру крі́пкую, наде́жду несумні́нную, любо́в і́стинную к Нему́ імі́ти утверди́вий, сподо́би тя во і́м'я Святи́я Тро́йці пресла́вний храм і оби́тель чу́дную устро́їти, і во о́ну мно́жество і́нок собра́ти. Сего́ ра́ди ві́рнії научи́шася воспіва́ти тебі́ та́ко:","Ра́дуйся, честно́є Пресвяти́я Тро́йці носи́ло і похвале́ніє; ра́дуйся, до́брі ста́до, тобо́ю со́бранноє, во спасе́ніє наставля́вий.","Ра́дуйся, честни́й о́бразе а́гнцем і па́стирем; ра́дуйся, пра́вило ві́ри і о́бразе кро́тости духо́вния.","Ра́дуйся, святи́ням чи́стоє і непоро́чноє жили́ще; ра́дуйся, єще́ в жи́зні сподо́бивийся ви́діти Пресвяту́ю Богоро́дицю со двіма́ апо́столома.","Ра́дуйся, удосто́ївийся во вре́м'я соверше́нія літургі́и сослуже́нія а́нгельськаго; ра́дуйся, во святу́ю літургі́ю в благода́ті Бо́жієй весь, а́ки во огні́, стоя́щий.","Ра́дуйся, о́ним Боже́ственним огне́м, в поти́р вше́дшим, причасти́вийся; ра́дуйся, досто́їн би́вий а́нгельськаго собесі́дованія.","Ра́дуйся, преіспо́лненний вся́кия благости́ні; ра́дуйся, чистоти́ душе́вния і тіле́сния усе́рдний храни́телю.","Ра́дуйся, Се́ргіє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 3","ps":["Си́лою, да́нною ті сви́ше, бу́дущая, я́ко настоя́щая, созерца́я, возвіща́л єси́ пра́вду Єва́нгельськую, ю́же всім бли́жнім і да́льним пропові́дал єси́, да Христу́ ві́рнії служи́теліє яв'я́ться, Єму́же і ти со тща́нієм мно́гим чрез все житіє́ твоє́ послужи́, оби́тель во і́м'я Пресвяти́я Тро́йці созида́я, Є́йже ми ни́ні сла́дці вопіє́м: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще помишле́ніє роди́теліє твої́ і лю́діє о трикра́тнім твоє́м во чре́ві ма́тернем в це́ркві глаше́нії і уди́вльшеся, разумі́ша ні́что пресла́вноє і чу́дноє би́ти; і по сих уві́дівше твоє́ ра́достноє рожде́ніє, ра́довахуся і ра́достная тебі́ приноша́ху, глаго́люще:","Ра́дуйся, отроча́ добродуше́вноє і благонаде́жноє; ра́дуйся, ді́тище, вся́кия благода́ті Бо́жия іспо́лненноє.","Ра́дуйся, пречу́дноє в младе́нчестві по́стничество нам явля́яй; ра́дуйся, о́ним мно́гих приводя́й во удивле́ніє і увеселя́яй.","Ра́дуйся, я́ко с тобо́ю всегда́ бі благода́ть Госпо́дня; ра́дуйся, от ю́ности твоєя́ всім се́рдцем і ми́слію Бо́га возлюби́вий.","Ра́дуйся, кро́тость, смире́ніє і бді́ніє імі́вий; ра́дуйся, вся ми́ра сего́ кра́сная, я́ко ско́ро ісчеза́ющая, презрі́вий.","Ра́дуйся, вся плотські́я по́хоті Бо́га ра́ди умертви́вий; ра́дуйся, многообра́зния ко́зні лука́ваго си́лою Бо́жиєю побіди́вий.","Ра́дуйся, мно́гія лю́ди от гріхо́внаго путі́ ко Го́споду обрати́вий і спаси́й; ра́дуйся, я́ко тобо́ю сла́достей духо́вних ісполня́ємся.","Ра́дуйся, Се́ргіє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́ри житія́ ми́ра сего́, при́сно вну́тренніми і вні́шніми злострада́нії волну́ющагося, преподо́бне о́тче Се́ргіє, ізба́вився, прише́л єси́ во приста́нище нем'яте́жноє небе́сноє, на міста́ зла́чна і прохла́дна, іді́же пото́ци сла́дости неісповіди́мия, пи́ща сла́ви Бо́жия нетлі́нная, пі́нія і гла́си пра́зднующих. Та́мо почива́єши і весели́шися, со всі́ми а́нгельськими си́лами поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша, преподо́бне о́тче Се́ргіє, бли́жнії і да́льнії ангелоподо́бноє твоє́ житіє́ і благода́ті чуде́с струю́ ви́ну теку́щую, я́ко моли́твою твоє́ю прокаже́ннії очища́ються, сліпі́ї прозира́ють, хромі́ї хо́дять і разнообра́зних неду́г с ві́рою притека́ющії здра́віє улуча́ють, сих ізба́вльшеся, вопія́ху к тебі́ такова́я:","Ра́дуйся, мирова́рнице, на вся неду́ги врачева́ніє подава́ющая; ра́дуйся, безме́здно па́че єстества́ врачу́ скороми́лостивий.","Ра́дуйся, ми́лости превели́кия і ско́рбним сострада́нія сокро́вище; ра́дуйся, всеусе́рднаго о лю́дех промишле́нія прия́телище.","Ра́дуйся, ду́шу свою́ за челові́ки положи́ти гото́вий; ра́дуйся, увеселе́ніє і отра́до к тебі́ прибіга́ющим.","Ра́дуйся, мертвеця́ пресла́вно моли́твою твоє́ю оживи́вий; ра́дуйся, оскуді́ніє монасти́рськоє в пи́щі іспо́лнивий.","Ра́дуйся, на сухо́м мі́сті пото́к во́дний тещи́ у Бо́га іспроси́вий; ра́дуйся, я́ко та́яжде вода́, моли́твою твоє́ю ісціля́ющи неду́ги, чудоді́йствуєть.","Ра́дуйся, чуде́с пучи́но, Бо́гом ізлія́нная; ра́дуйся, жела́ємих благ прише́дшим к тебі́ пода́телю.","Ра́дуйся, Се́ргіє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 5","ps":["Боготе́чная пресві́тлая звізда́ яви́лся єси́, преподо́бне о́тче Се́ргіє, не́бо церко́вноє украша́яй і всіх блудя́щих по мо́рю стра́стнаго житія́ сего́ да́нною тебі́ от Со́лнця Пра́вди Христа́ Ісу́са, і́стиннаго Бо́га, благода́тію озаря́яй, мрак печа́лей і мглу неду́г і скорбе́й прогоня́яй, наставля́єши всіх к тебі́ с ві́рою притека́ющих на путь спасе́нний, к ві́чному Небе́сному Оте́честву веду́щий, пою́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів преподо́бний Се́ргій, я́ко в ми́рі сем вся́чеськая суєта́ і тлі́нію прича́стна, потща́ся вседу́шно Преві́чному Бо́гу благоугоди́ти, і воі́стину не вотще́ потруди́ся: преміни́ бо тлі́нная на нетлі́нная, найпа́че же предстоя́нія сподо́бися у стра́шнаго Престо́ла Влади́чня в сла́ві ві́чній. Ті́мже вопіє́м єму́:","Ра́дуйся, я́ко іді́же Христо́с в тілесі́, та́можде і ти пребива́єши; ра́дуйся, та́мо, я́ко в зерца́лі, в Бо́зі вся Єму́ любе́зная созерца́єши.","Ра́дуйся, созерца́я в Нем моля́щихся ті о по́мощі, моли́твою твоє́ю їм поле́зноє хода́тайствуєши; ра́дуйся, ско́рий помо́щниче призива́ющим тя правосла́вним.","Ра́дуйся, моли́твою твоє́ю ві́рним побі́ди на проти́вния подава́яй; ра́дуйся, скорб'я́щим скоропредста́тельний уті́шителю.","Ра́дуйся, не́мощей тіле́сних і душе́вних немздоприє́мний ісціли́телю; ра́дуйся, мно́гая чудеса́ благода́тію Ду́ха Свята́го содіва́яй.","Ра́дуйся, хроми́м хожде́ніє і сліпи́м прозрі́ніє подава́яй; ра́дуйся, гро́зде ви́нний, пита́ющий нас і веселя́щий.","Ра́дуйся, розго́ Христа́ лози́ і́стинния, мног плод в посо́біє правосла́вним творя́щая; ра́дуйся, благи́й ра́бе і ві́рний, і до́брий ді́лателю виногра́да Христо́ва.","Ра́дуйся, Се́ргіє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дуєм, богому́дре Се́ргіє, труди́ твоя́ і болі́зні, бді́ніє же і сухояде́ніє, ра́ди душе́внаго твоєго́ спаcе́нія под'я́тия, єго́же ра́ди просла́ви тя Госпо́дь сла́вою Своє́ю Боже́ственною. Ті́мже, я́ко рай насажде́нний, в Це́ркві яви́лся єси́, іму́щей дре́во жи́зні Самаго́ Го́спода, от Него́же вкуси́вшії вся ско́ро ги́бнущая в ми́рі сем презира́ють і ра́достно в прекра́сний виногра́д ви́шній вхо́дять, іді́же ти, предстоя́ Єму́, вопіє́ши: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ Це́ркві і пра́во в Бо́га ві́рующим просвіще́ніє соверше́нних твої́х доброді́телей, преподо́бне о́тче Се́ргіє, о ни́хже благодаря́ще Отця́ Небе́снаго, да́вшаго тебі́ толи́кую благода́ть вели́чія Своєго́, к тебі́, я́ко к те́плому о нас моли́твеннику, ра́достная воспіва́єм та́ко:","Ра́дуйся, а́нгельськоє житіє́ нам явля́яй; ра́дуйся, стра́сті гріхо́вния уставля́яй.","Ра́дуйся, о́бразе і́стиннаго смире́нія; ра́дуйся, зерца́ло соверше́ннаго терпі́нія.","Ра́дуйся, наста́вниче вели́кий спасе́нію; ра́дуйся, приводя́й грі́шних ко ісправле́нію.","Ра́дуйся, ізві́стний ісполни́телю за́повідей Христо́вих; ра́дуйся, ду́ш немощни́х ісціле́ніє.","Ра́дуйся, ми́лостиню твори́ти науча́яй; ра́дуйся, ри́зи і бра́шна немощни́м подава́ти повеліва́яй.","Ра́дуйся, пусти́нниче, мирську́ю честь і бога́тство возненави́дівий; ра́дуйся, по́стниче, от ю́ности Бо́гу послужи́вий.","Ра́дуйся, Се́ргіє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́ ізбра́н дом Ду́ху Свято́му себе́ сотвори́ти, потща́лся єси́ ті́сним і приско́рбним путе́м, веду́щим в жизнь ві́чную, взем на ра́мо своє́ Крест Христо́в, ше́ствовати, є́же благода́тію Бо́жиєю от ю́ности твоєя́ непоро́чно в творе́ніїх за́повідей Госпо́дніх соверши́в, дости́гл єси́ угото́ваннаго тебі́ в небе́сном всевесе́лом пребива́нії воздая́нія, і та́мо благода́рственно поє́ши Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую благода́ть показа́ всіх Творе́ць і Влади́ка тебі́, богому́дре Се́ргіє: а́ще бо і у́мерл єси́ на землі́ пло́тію, но душе́ю в ви́шнім селе́нії всегда́ жив сий, мно́гая і пресла́вная чудеса́ в ми́рі живу́щим лю́дем ді́йствуєши, і те́плим твої́м хода́тайством посо́бствуєши, вопію́щим к тебі́ такова́я:","Ра́дуйся, ді́вственниче душе́ю і ті́лом; ра́дуйся, і́ноком наста́вниче преди́вний.","Ра́дуйся, ду́ш на́ших ра́дованіє; ра́дуйся, би́строє ни́щим усли́шаніє.","Ра́дуйся, скорб'я́щим прия́тноє попече́ніє; ра́дуйся, чистоти́ усе́рдний храни́телю.","Ра́дуйся, ненаде́жним наді́яніє; ра́дуйся, скорб'я́щим увеселе́ніє.","Ра́дуйся, дре́во чудото́чноє рая́ Ісу́сова; ра́дуйся, кри́не ра́йськаго прозябе́нія.","Ра́дуйся, ми́ро Христо́ва благоуха́нія; ра́дуйся, я́ко тобо́ю прино́ситься ра́дованіє.","Ра́дуйся, Се́ргіє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нноє і пресла́вноє чу́до явля́ється притека́ющим к тебі́, богому́дре Се́ргіє: і́бо да́нною тебі́ с ві́рою прося́щим Бо́жиєю благода́тією неме́дленно от вся́ких многообра́зних тіле́сних і душе́вних скорбе́й ісціля́єши, от бід ізбавля́єши, от напа́стей охраня́єши, і всім вся́ко благополе́зноє проше́ніє ісполня́єши, і вопіє́ши Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь єси́, преподо́бне о́тче Се́ргіє, в ви́шніх, но і ни́жніх не оставля́єши: при́сно со Христо́м Царе́м Ві́чним ца́рствуєши і нас, грі́шних і недосто́йних, пред Ним воспомина́єши, моля́ся о спасе́нії на́шем. Ті́мже от усе́рдія на́шего вопіє́м к тебі́ си́це:","Ра́дуйся, оста́вльшій імі́ніє і возлюби́вий нищету́ Христо́ву; ра́дуйся, дости́гшій к неістощи́мому бога́тству.","Ра́дуйся, Ду́ху Свято́му подклони́вшийся со вся́ким смире́нієм; ра́дуйся, во́їне Христо́в непобіди́мий я́вльшийся.","Ра́дуйся, крило́ма богоми́слія сі́ті вра́жія сокруши́вий; ра́дуйся, смире́нієм возвиша́ємий, в ві́чния кро́ви возлеті́вший.","Ра́дуйся, просвіще́нний внутр благода́тію; ра́дуйся, істреби́вший страсте́й мглу душевре́дную.","Ра́дуйся, в по́двизіх дневни́х і нощни́х тече́ніє соверши́вий; ра́дуйся, в невече́рнім дні Ца́рствія Бо́жия при́сно почива́яй.","Ра́дуйся, та́мо сніде́нія пи́щі разу́мния сподо́бльшийся; ра́дуйся, я́ко того́ блаже́нства от Бо́га ві́чно удосто́ївийся.","Ра́дуйся, Се́ргіє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє удиви́ся вели́кому сви́ше тебі́ дарова́нію, я́ко на землі́ невеще́ственноє житіє́ показа́л єси́, і во пло́ті, а́ки безпло́тен, яви́лся єси́. Сего́ ра́ди мно́гих чуде́с творе́нія от Го́спода приє́м, чи́стою і боголюбе́зною душе́ю твоє́ю Того́ бла́гостію к Небе́сним причте́н єси́ си́лам, в Небесі́х ни́ні поє́ши всеси́льному Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я многовіща́нния недоумі́ють досто́йно сла́вити тя, досто́йний вся́кия сла́ви, сла́вне преподо́бне о́тче Се́ргіє, і́бо пачеєсте́ственная мно́гая пресла́вная чудоді́йствія, єще́ жив сущь, показа́л єси́, но і по сме́рті та́я благода́тію Бо́жиєю твори́ти не престає́ши. Ми же, любо́вію понужда́єми, дерза́єм пі́ти тебі́ си́це:","Ра́дуйся, земни́й а́нгеле і небе́сний челові́че; ра́дуйся, во пло́ті живи́й духо́вно, на землі́ небе́сно.","Ра́дуйся, в челові́честві пребива́яй а́нгельськи, в ми́рі премі́рно; ра́дуйся, душе́внима свої́ма очи́ма ви́ну Го́спода созерца́вий.","Ра́дуйся, пред лице́м Бо́жиїм, я́ко раб пред Го́сподем, ходи́вий; ра́дуйся, пред О́ним, я́ко син пред Отце́м, я́ко учени́к пред Учи́телем, ше́ствовавий.","Ра́дуйся, я́ко во́їн пред Воєво́дою гото́в сий вся повелі́нная Ім твори́ти; ра́дуйся, до́брий ста́да своєго́ і́ночествующих наста́вниче і прави́телю.","Ра́дуйся, ше́ствовавий от си́ли в си́лу, до́ндеже яви́ся тебі́ Бог бого́в в Сіо́ні; ра́дуйся, Єди́наго Го́спода возлюби́вий і к Нему́ очеса́ своя́ ви́ну імі́вий.","Ра́дуйся, во вся дні живота́ своєго́ Єго́ іска́вий і в Нем намі́реніє полага́вий; ра́дуйся, нічесого́ на Небесі́ і на землі́, ра́зві Христа́ Ісу́са, ви́діти жела́вий.","Ра́дуйся, Се́ргіє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ ду́шу твою́, в ю́ності во́зраста своєго́ отре́клся єси́ во́лі своєя́ і во зна́м'я отсіче́нія єя́ постри́гл єси́ власи́ глави́ своєя́, і бил єси́ мона́х, покори́вий себе́ во́лі Бо́жієй. Вся́чеськая же приключе́нія благода́рно, я́ко ві́рний раб от Го́спода прийма́л єси́, Єму́же на Небесі́х предстоя́, ни́ні вопіє́ши: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ всім челові́ком, к заступле́нію твоєму́ прибіга́ющим, преподо́бне богому́дре Се́ргіє. Ті́мже і нам, к тебі́ приходя́щим і ми́лостиваго твоєго́ во вся́ких ну́ждах заступле́нія у Царя́ Небе́снаго прося́щим, бу́ди стіна́ крі́пкая і огражде́ніє непреобори́моє, от вся́ких нас бід і напа́стей застіня́я і огражда́я, за є́же ми вопіє́м тебі́ такова́я:","Ра́дуйся, во́їне Царя́ Небе́снаго, не об'яза́вийся ку́плями жите́йськими, да Єму́ уго́ден бу́деши; ра́дуйся, не восхоті́вий двіма́ господи́нома, Бо́гу і ми́ру, рабо́тати, но Єди́ному Бо́гу то́чію.","Ра́дуйся, от ю́ности на ті́ло своє́, на мир сей і дия́вола вооружи́вийся; ра́дуйся, посто́м, покло́ни, стоя́нієм на моли́тві, бді́нієм умертви́вий плоть свою́.","Ра́дуйся, умертви́вий о́ную пре́жді, не́жели она́ жива́ страсте́м бя́ше; ра́дуйся, ме́ртву соді́явий горта́нь проти́ву прийма́нія сласте́й.","Ра́дуйся, мертв сотвори́вий язи́к проти́ву глаго́ланія скве́рних, клеве́тних і ло́жних; ра́дуйся, ме́ртви устро́ївий ушеса́ проти́ву сли́шанія душевре́дних.","Ра́дуйся, ме́ртви соді́явий ру́ці проти́ву грабле́нія і вся́ких зол творе́нія; ра́дуйся, ме́ртво сотвори́вий чре́во проти́ву об'яде́нія і пія́нства.","Ра́дуйся, ме́ртва соді́лавий труда́ми чре́сла своя́ проти́ву нечистоти́; ра́дуйся, ме́ртви сотвори́вий но́зі проти́ву тече́нія в путь грі́шников і на сові́т нечести́вих.","Ра́дуйся, Се́ргіє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє благода́рственноє благотвори́телю Христу́ Ісу́су, тя, преподо́бне о́тче, прославля́юще, всі правосла́внії взива́ють, я́ко дарова́л ті мно́гих чуде́с си́лу творе́нія: сліпи́я просвіща́ти, прокаже́нния очища́ти, больни́я врачева́ти, бі́сния от де́монськаго друче́нія свобожда́ти, толи́ко си́льні, я́коже і не у приведе́нним к тебі́ би́вшим бі́сним, єще́ на путі́ де́мони от них отбіга́ху, і ктому́ не возвраща́хуся, боя́щеся в тебі́ си́ли Бо́жия, ю́же ви́ну в Небесі́х прославля́я, вопіє́ши Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рноє світи́ло во всей вселе́нній благода́тію немерца́ющаго Со́лнця, Христа́ Ісу́са, просвіща́ющею возсія́вшеє, зрим тя, богому́дре о́тче: с невеще́ственними бо в ви́шніх предстоя́ Престо́лу Тро́йці Пресвяти́я, ра́дости превели́кия іспо́лнен єси́ і Боже́ственними луча́ми Трисо́лнечнаго Сві́та осіява́єм, облиста́єши ві́рних, вопію́щих к тебі́ такова́я:","Ра́дуйся, возше́дий на го́ру превисо́ку доброді́телей Боже́ственних; ра́дуйся, я́ко от тоя́ удо́б возше́л єси́ на го́ру небе́сную.","Ра́дуйся, я́ко от оби́телі земни́я во оби́тель небе́сную водвори́лся єси́; ра́дуйся, я́ко восходя́ та́мо душе́ю, нас заступле́нія своєго́ не оста́вил єси́.","Ра́дуйся, я́ко моли́твою твоє́ю ісціліва́ють вся́кия ско́рбі і болі́зні; ра́дуйся, я́ко святости і пра́вености твоєя́ де́мони трепе́щуть.","Ра́дуйся, я́ко в печа́лі су́щим подає́ши духо́вноє увеселе́ніє; ра́дуйся, душе́ю востекі́й в Сіо́н го́рній, к Царю́ Небе́сному.","Ра́дуйся, я́ко та́мо предстоя́, о всіх нас к Нему́ те́плі хода́тайствуєши; ра́дуйся, я́ко благоутро́біє Єго́ о всіх чту́щих па́м'ять твою́ умилостивля́єши.","Ра́дуйся, христоімени́тим отгна́ніє бісо́вських прило́гов моли́твою твоє́ю содіва́ющий; ра́дуйся, всім правові́рним вся́коє проше́ніє, во їх по́льзу ісполня́ющий.","Ра́дуйся, Се́ргіє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть, да́нную ті от Бо́га, сві́дуще, тебе́, при́снаго на́шего ми́лостиваго отця́, прилі́жно про́сим: проли́й ни́ні те́плую моли́тву о нас, грі́шних, ко Го́споду, я́ко да презрі́в вся на́ша согріше́нія, Це́рков Свою́ Святу́ю от ра́спрей і раско́лов непози́блему да сохрани́ть, оби́ліє вся́ких плодо́в землі́ да да́руєть і вся правосла́вния христия́ни да спасе́ть і поми́луєть, Чесого́ от Него́ твої́ми моли́твами улуче́нія ожида́юще, вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ди́внаго во святи́х Свої́х Царя́ Небе́снаго, просла́вльшаго тя, ві́рнаго Своєго́ раба́, преподо́бнаго отця́ Се́ргія, ми́лостивоє твоє́, ско́роє нам во вся́ких ну́ждах і печа́лех поможе́ніє прославля́єм, і́бо в тебі́ в Тро́йці прославля́ємий Бог наш пресла́вним мно́гим чудоді́йствієм ди́вно просла́вися, о чесо́м удивля́ющеся вопіє́м к тебі́ си́це:","Ра́дуйся, великосла́вний наш засту́пниче, о́тче Се́ргіє; ра́дуйся, соверше́нний в доброді́телех челові́че.","Ра́дуйся, ди́вний подража́телю соверше́нства Отця́ на́шего Небе́снаго; ра́дуйся, преблаги́й і до́брий наста́вниче і́ноков.","Ра́дуйся, о́бразі пустинножи́телей і устрої́телю о́бщаго житія́; ра́дуйся, всіх правосла́вних ско́рий помо́щниче і засту́пниче.","Ра́дуйся, Царя́ Небе́снаго і Бо́га ізві́стний умилостиви́телю; ра́дуйся, мно́гажди заступле́нієм твої́м проше́нія предваря́яй.","Ра́дуйся, покро́ве, Бо́гом зда́нний, і́мже покрива́ються мно́зі; ра́дуйся, ліни́вих подви́гнувий твої́ми христоподража́тельними нра́ви.","Ра́дуйся, доброзра́чноє сві́та єва́нгельськаго всесві́тлоє сія́ніє; ра́дуйся, Трисо́лнечнаго Святи́я Тро́йці сві́та ви́ну просвіща́ющеє озаре́ніє.","Ра́дуйся, Се́ргіє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 13","ps":["О чудотво́рче пресла́вний і засту́пниче всім нам во вся́ких біда́х і ско́рбіх ско́рий і пречу́дний, богому́дре о́тче Се́ргіє! Ни́нішнєє на́ше прийми́ приноше́ніє і богоприя́тним твої́м хода́тайством умоли́ Го́спода сил си́лу сви́ше Того́ благода́тію очи́стившимся, от геє́нни ізба́витися, і гряду́щая в Небесі́х блага́я улучи́ти, вопію́щим Єму́: Аллилу́я.","§Цей кондак співається тричі."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць, предуві́дівий, по самовла́стному чи́стаго се́рдця твоєго́ ізволе́нію, всеусе́рдствующеє Єго́ во́лі ісполне́ніє, єще́ во чре́ві ма́терні трикра́тним возглаше́нієм, показа́ тя ми́ру і́стиннаго служи́теля би́ти Святи́я Тро́йці, і научи́ всіх вопи́ти тебі́ си́це:","Ра́дуйся, я́ко пре́жде вік і́маши ві́рний раб Христо́в би́ти предусмо́тренний; ра́дуйся, во о́ноже вре́м'я во блаже́нноє і небе́сноє жили́ще предуста́вленний.","Ра́дуйся, от чре́ва ма́терня на слу́жбу Небе́снаго Царя́, я́ко во́їн хотя́щий ві́рен Єму́ би́ти, призва́нний; ра́дуйся, я́ко благода́тію Бо́жиєю оправда́нний.","Ра́дуйся, ти бо єси́ по всей вселе́нній просла́вленний; ра́дуйся, трикра́тним твої́м во чре́ві возглаше́нієм роди́телей і всіх сли́шащих удиви́вий.","Ра́дуйся, по рожде́нії своє́м по́стноє і́ночеськоє житіє́ показа́вий; ра́дуйся, от сосця́ ма́терня воздержа́ніє чу́дноє яви́вий.","Ра́дуйся, я́ко в сре́ду і пято́к млека́ ніка́коже вкуси́вий; ра́дуйся, роди́телей благи́х до́брий і ізбра́нний пло́де.","Ра́дуйся, ра́дости скорб'я́щим і ми́лости с ві́рою у тебе́ прося́щим пода́телю; ра́дуйся, печа́лей злих во вся́ких приключе́ніїх отгони́телю.","Ра́дуйся, Се́ргіє, ско́рий помо́щниче і пресла́вний чудотво́рче."]},{"h":"Кондак 1","ps":["Возбра́нний от Царя́ сил, Го́спода Ісу́са, воєво́до і чудотво́рче преди́вний, преподо́бне о́тче Се́ргіє! Прославля́юще просла́вльшаго тя сла́ви Го́спода, благода́рственноє пі́ніє воспіва́єм ті, і́бо моли́твами твої́ми от прило́гов і ско́рбних обстоя́ній нас при́сно ізбавля́єши, я́ко імі́я дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, да зове́м ті:","Ра́дуйся, Се́ргіє, ско́рий помо́щниче і пресла́вний чудотво́рче."]}],"notes":[]}];
